questions.push(...[{"id":50,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 26, 28, 30, 32, 34, …","அடுத்த எண்ணைக் காண்க: 26, 28, 30, 32, 34, …"],"options":[["41","41"],["46","46"],["36","36"],["38","38"]],"answer":2,"explanation":["Add 2 each time. 34 + 2 = 36.","ஒவ்வொரு முறையும் 2 கூட்டுக. 34 + 2 = 36."]},{"id":51,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 35, 70, 140, 280, ?","தொடரை நிறைவு செய்க: 35, 70, 140, 280, ?"],"options":[["559","559"],["1120","1120"],["560","560"],["562","562"]],"answer":2,"explanation":["Double each term: 280 × 2 = 560.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 280 × 2 = 560."]},{"id":52,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 13, 34, 76, 160, ?","அடுத்த உறுப்பைக் காண்க: 13, 34, 76, 160, ?"],"options":[["327","327"],["328","328"],["656","656"],["330","330"]],"answer":1,"explanation":["Multiply by 2, then add 8: 160 × 2 + 8 = 328.","2 ஆல் பெருக்கி 8 கூட்டுக: 160 × 2 + 8 = 328."]},{"id":53,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 14, 16, ?, 20, 22","விடுபட்ட எண்ணைக் காண்க: 14, 16, ?, 20, 22"],"options":[["18","18"],["28","28"],["21","21"],["36","36"]],"answer":0,"explanation":["The common difference is 2. 16 + 2 = 18.","பொது வித்தியாசம் 2. 16 + 2 = 18."]},{"id":54,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 196, 225, 256, 289, ?","தொடர்க: 196, 225, 256, 289, ?"],"options":[["325","325"],["324","324"],["648","648"],["327","327"]],"answer":1,"explanation":["These are squares of 14, 15, 16, 17. Next: 18² = 324.","இவை 14, 15, 16, 17 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 18² = 324."]},{"id":55,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 34 from the front and position 21 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 34 ஆவது, பின்னிருந்து 21 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["108","108"],["53","53"],["54","54"],["59","59"]],"answer":2,"explanation":["Total = 34 + 21 − 1 = 54; the student is counted only once.","மொத்தம் = 34 + 21 − 1 = 54; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":56,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 48 students, a student is in position 15 from the front. Find the position from the back.","48 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 15 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["68","68"],["34","34"],["37","37"],["44","44"]],"answer":1,"explanation":["Position from back = 48 − 15 + 1 = 34.","பின்னிருந்து இடம் = 48 − 15 + 1 = 34."]},{"id":57,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 40 m north, 18 m east, 5 m south and 18 m west. How far are you from the start, in metres?","40 மீ வடக்கு, 18 மீ கிழக்கு, 5 மீ தெற்கு, 18 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["70","70"],["35","35"],["38","38"],["45","45"]],"answer":1,"explanation":["East and west cancel. Net northward distance = 40 − 5 = 35 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 40 − 5 = 35 மீ."]},{"id":58,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 9 km east and then 12 km north. Find the straight-line distance from the start in km.","9 கி.மீ கிழக்கிலும் பின்னர் 12 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["25","25"],["17","17"],["15","15"],["30","30"]],"answer":2,"explanation":["Pythagoras: √(9² + 12²) = 15 km.","பிதாகரஸ் தேற்றம்: √(9² + 12²) = 15 கி.மீ."]},{"id":59,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 13 → 182, then 19 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 13 → 182 எனில் 19 → ?"],"options":[["380","380"],["382","382"],["379","379"],["383","383"]],"answer":0,"explanation":["19 × (19 + 1) = 380.","19 × (19 + 1) = 380."]},{"id":60,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 3 : 27 :: 14 : ?","மும்மடி விதியைப் பயன்படுத்துக: 3 : 27 :: 14 : ?"],"options":[["2743","2743"],["2744","2744"],["2754","2754"],["5488","5488"]],"answer":1,"explanation":["3³ = 27, so 14³ = 2744.","3³ = 27; எனவே 14³ = 2744."]},{"id":61,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 5 places forward in the alphabet (wrap Z to A). Code HOME.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 5 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). HOME இன் குறியீடு என்ன?"],"options":[["NUSK","NUSK"],["MTRJ","MTRJ"],["OVTL","OVTL"],["LSQI","LSQI"]],"answer":1,"explanation":["Each letter advances by 5: H → M, O → T, M → R, E → J","ஒவ்வோர் எழுத்தும் 5 இடங்கள் முன்னேறும்: H → M, O → T, M → R, E → J"]},{"id":62,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 15% of 200.","200 இல் 15% காண்க."],"options":[["33","33"],["31","31"],["60","60"],["30","30"]],"answer":3,"explanation":["200 × 15 / 100 = 30.","200 × 15 / 100 = 30."]},{"id":63,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹2100. Find the price after a 25% discount, in rupees.","குறித்த விலை ₹2100. 25% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["1575","1575"],["1574","1574"],["1578","1578"],["1580","1580"]],"answer":0,"explanation":["Discount = ₹525. Pay 2100 − 525 = ₹1575.","தள்ளுபடி = ₹525. செலுத்துவது 2100 − 525 = ₹1575."]},{"id":64,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2900 at 9% per year for 5 years.","₹2900 க்கு ஆண்டுக்கு 9% வீதம் 5 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1306","1306"],["2610","2610"],["1308","1308"],["1305","1305"]],"answer":3,"explanation":["PRT/100 = 2900 × 9 × 5 / 100 = ₹1305.","PRT/100 = 2900 × 9 × 5 / 100 = ₹1305."]},{"id":65,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 14x + 25 = 277.","x காண்க: 14x + 25 = 277."],"options":[["28","28"],["18","18"],["17","17"],["21","21"]],"answer":1,"explanation":["x = (277 − 25) ÷ 14 = 18.","x = (277 − 25) ÷ 14 = 18."]},{"id":66,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 12 cm long and 7 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 12 செ.மீ, அகலம் 7 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["85","85"],["94","94"],["86","86"],["84","84"]],"answer":3,"explanation":["Area = length × width = 12 × 7 = 84 cm².","பரப்பளவு = நீளம் × அகலம் = 12 × 7 = 84 ச.செ.மீ."]},{"id":67,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 7 m and 8 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 7 மீ மற்றும் 8 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["33","33"],["60","60"],["30","30"],["40","40"]],"answer":2,"explanation":["Perimeter = 2(7 + 8) = 30 m.","சுற்றளவு = 2(7 + 8) = 30 மீ."]},{"id":68,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 30 cm and height 7 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 30 செ.மீ, உயரம் 7 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["106","106"],["105","105"],["108","108"],["104","104"]],"answer":1,"explanation":["Area = ½ × 30 × 7 = 105 cm².","பரப்பளவு = ½ × 30 × 7 = 105 ச.செ.மீ."]},{"id":69,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 22 cm × 8 cm × 6 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 22 செ.மீ × 8 செ.மீ × 6 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["1056","1056"],["1057","1057"],["1066","1066"],["1059","1059"]],"answer":0,"explanation":["Volume = length × breadth × height = 22 × 8 × 6 = 1056 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 22 × 8 × 6 = 1056 க.செ.மீ."]},{"id":70,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The green pigment that absorbs light for photosynthesis.","கண்டறிக: ஒளிச்சேர்க்கைக்காக ஒளியை உறிஞ்சும் பச்சை நிறமி."],"options":[["Chlorophyll","பச்சையம்"],["Watt","வாட்"],["Phloem","புளோயம்"],["Root hairs","வேர்த்தூவிகள்"]],"answer":0,"explanation":["Chlorophyll: The green pigment that absorbs light for photosynthesis.","பச்சையம்: ஒளிச்சேர்க்கைக்காக ஒளியை உறிஞ்சும் பச்சை நிறமி."]},{"id":71,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Tiny pores on leaves that allow gas exchange.","கண்டறிக: இலைகளில் வாயுப் பரிமாற்றத்திற்கு உதவும் சிறிய துளைகள்."],"options":[["Stomata","இலைத்துளைகள்"],["Chloroplast","பசுங்கணிகம்"],["Condensation","ஆவி சுருங்குதல்"],["Nitrogen","நைட்ரஜன்"]],"answer":0,"explanation":["Stomata: Tiny pores on leaves that allow gas exchange.","இலைத்துளைகள்: இலைகளில் வாயுப் பரிமாற்றத்திற்கு உதவும் சிறிய துளைகள்."]},{"id":72,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Plant tissue that transports water and minerals from roots.","கண்டறிக: வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு."],"options":[["Condensation","ஆவி சுருங்குதல்"],["Refraction","ஒளிவிலகல்"],["Xylem","சைலம்"],["Friction","உராய்வு"]],"answer":2,"explanation":["Xylem: Plant tissue that transports water and minerals from roots.","சைலம்: வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு."]},{"id":73,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The largest continent by land area.","கண்டறிக: நிலப்பரப்பில் மிகப்பெரிய கண்டம்."],"options":[["Subhas Chandra Bose","சுபாஷ் சந்திர போஸ்"],["V. O. Chidambaranar","வ. உ. சிதம்பரனார்"],["Asia","ஆசியா"],["Revolution","சுற்றிவருதல்"]],"answer":2,"explanation":["Asia: The largest continent by land area.","ஆசியா: நிலப்பரப்பில் மிகப்பெரிய கண்டம்."]},{"id":74,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The smallest of the seven continents.","கண்டறிக: ஏழு கண்டங்களில் மிகச்சிறிய கண்டம்."],"options":[["Island","தீவு"],["Tropic of Capricorn","மகரரேகை"],["Australia","ஆஸ்திரேலியா"],["Plateau","பீடபூமி"]],"answer":2,"explanation":["Australia: The smallest of the seven continents.","ஆஸ்திரேலியா: ஏழு கண்டங்களில் மிகச்சிறிய கண்டம்."]},{"id":75,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in PARK.","A = 1, B = 2, …, Z = 26 எனில், PARK என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["56","56"],["51","51"],["46","46"],["47","47"]],"answer":2,"explanation":["16 + 1 + 18 + 11 = 46.","16 + 1 + 18 + 11 = 46."]},{"id":76,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Wednesday. What day will it be after 96 days?","இன்று புதன். 96 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Wednesday","புதன்"],["Monday","திங்கள்"],["Tuesday","செவ்வாய்"],["Thursday","வியாழன்"]],"answer":1,"explanation":["96 ÷ 7 leaves remainder 5. Move 5 days from Wednesday: Monday.","96 ஐ 7 ஆல் வகுக்க மீதி 5. புதன் கிழமையிலிருந்து 5 நாட்கள் நகர்ந்தால் திங்கள்."]},{"id":77,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 4 students shakes hands once with every other student. How many handshakes occur?","4 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["11","11"],["7","7"],["6","6"],["8","8"]],"answer":2,"explanation":["Each pair is counted once: 4 × 3 ÷ 2 = 6.","ஒவ்வொரு இணையும் ஒருமுறை: 4 × 3 ÷ 2 = 6."]},{"id":78,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 32 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 32 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["194","194"],["107","107"],["96","96"],["97","97"]],"answer":3,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 31 = 97.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 31 = 97."]},{"id":79,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 7, 10, 14, 19, 25, ?","நிறைவு செய்க: 7, 10, 14, 19, 25, ?"],"options":[["35","35"],["32","32"],["34","34"],["42","42"]],"answer":1,"explanation":["Differences increase by 1: 3, 4, 5, 6, 7. Next = 32.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 3, 4, 5, 6, 7. அடுத்த எண் 32."]},{"id":80,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 4, 7, 11, 18, 29, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 4, 7, 11, 18, 29, ?"],"options":[["48","48"],["50","50"],["46","46"],["47","47"]],"answer":3,"explanation":["18 + 29 = 47.","18 + 29 = 47."]},{"id":81,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 5, 11, 17, 23, 29, …","அடுத்த எண்ணைக் காண்க: 5, 11, 17, 23, 29, …"],"options":[["35","35"],["45","45"],["40","40"],["38","38"]],"answer":0,"explanation":["Add 6 each time. 29 + 6 = 35.","ஒவ்வொரு முறையும் 6 கூட்டுக. 29 + 6 = 35."]},{"id":82,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 9, 18, 36, 72, ?","தொடரை நிறைவு செய்க: 9, 18, 36, 72, ?"],"options":[["145","145"],["144","144"],["146","146"],["143","143"]],"answer":1,"explanation":["Double each term: 72 × 2 = 144.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 72 × 2 = 144."]},{"id":83,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 9, 20, 42, 86, ?","அடுத்த உறுப்பைக் காண்க: 9, 20, 42, 86, ?"],"options":[["176","176"],["174","174"],["348","348"],["179","179"]],"answer":1,"explanation":["Multiply by 2, then add 2: 86 × 2 + 2 = 174.","2 ஆல் பெருக்கி 2 கூட்டுக: 86 × 2 + 2 = 174."]},{"id":84,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 8, 11, ?, 17, 20","விடுபட்ட எண்ணைக் காண்க: 8, 11, ?, 17, 20"],"options":[["14","14"],["17","17"],["28","28"],["19","19"]],"answer":0,"explanation":["The common difference is 3. 11 + 3 = 14.","பொது வித்தியாசம் 3. 11 + 3 = 14."]},{"id":85,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 900, 961, 1024, 1089, ?","தொடர்க: 900, 961, 1024, 1089, ?"],"options":[["1157","1157"],["1155","1155"],["2312","2312"],["1156","1156"]],"answer":3,"explanation":["These are squares of 30, 31, 32, 33. Next: 34² = 1156.","இவை 30, 31, 32, 33 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 34² = 1156."]},{"id":86,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 19 from the front and position 13 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 19 ஆவது, பின்னிருந்து 13 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["31","31"],["33","33"],["41","41"],["62","62"]],"answer":0,"explanation":["Total = 19 + 13 − 1 = 31; the student is counted only once.","மொத்தம் = 19 + 13 − 1 = 31; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":87,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 19, 32, 45, 58, 71.","19, 32, 45, 58, 71 ஆகியவற்றின் சராசரி காண்க."],"options":[["47","47"],["44","44"],["55","55"],["45","45"]],"answer":3,"explanation":["Sum ÷ count = 225 ÷ 5 = 45.","கூடுதல் ÷ எண்ணிக்கை = 225 ÷ 5 = 45."]},{"id":88,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 377 km in 13 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 13 மணி நேரத்தில் 377 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["29","29"],["28","28"],["30","30"],["58","58"]],"answer":0,"explanation":["Speed = distance ÷ time = 377 ÷ 13 = 29 km/h.","வேகம் = தொலைவு ÷ நேரம் = 377 ÷ 13 = 29 கி.மீ/மணி."]},{"id":89,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 196 in the ratio 6 : 8. Find the smaller share.","196 ஐ 6 : 8 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["84","84"],["86","86"],["83","83"],["168","168"]],"answer":0,"explanation":["Smaller share = 196 × 6/(6+8) = 84.","சிறிய பங்கு = 196 × 6/(6+8) = 84."]},{"id":90,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 20 and 38.","20 மற்றும் 38 இன் மீ.பொ.வ. காண்க."],"options":[["12","12"],["2","2"],["4","4"],["3","3"]],"answer":1,"explanation":["Common factors: 1, 2. Greatest = 2.","பொதுக் காரணிகள்: 1, 2. மிகப்பெரியது 2."]},{"id":91,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 25 and 13.","25 மற்றும் 13 இன் மீ.பொ.ம. காண்க."],"options":[["328","328"],["324","324"],["335","335"],["325","325"]],"answer":3,"explanation":["LCM = product ÷ HCF = 325 ÷ 1 = 325.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 325 ÷ 1 = 325."]},{"id":92,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹3400 is sold for ₹4080. Find the profit percentage.","₹3400 க்கு வாங்கிய பொருள் ₹4080 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["20","20"],["21","21"],["25","25"],["40","40"]],"answer":0,"explanation":["Profit = ₹680. Profit% = 680 × 100 / 3400 = 20%.","இலாபம் = ₹680. இலாப% = 680 × 100 / 3400 = 20%."]},{"id":93,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 66° and 36°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 66°, 36°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["83","83"],["78","78"],["88","88"],["156","156"]],"answer":1,"explanation":["180 − 66 − 36 = 78°.","180 − 66 − 36 = 78°."]},{"id":94,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 5°, in degrees.","5° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["176","176"],["185","185"],["350","350"],["175","175"]],"answer":3,"explanation":["Supplementary angles sum to 180°. 180 − 5 = 175°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 5 = 175°."]},{"id":95,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Plant tissue that transports prepared food.","கண்டறிக: தயாரிக்கப்பட்ட உணவை எடுத்துச் செல்லும் தாவரத் திசு."],"options":[["Phloem","புளோயம்"],["Sublimation","பதங்கமாதல்"],["Reflection","எதிரொளிப்பு"],["Ohm","ஓம்"]],"answer":0,"explanation":["Phloem: Plant tissue that transports prepared food.","புளோயம்: தயாரிக்கப்பட்ட உணவை எடுத்துச் செல்லும் தாவரத் திசு."]},{"id":96,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Root extensions that increase the surface area for absorption.","கண்டறிக: உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்."],"options":[["Root hairs","வேர்த்தூவிகள்"],["Xylem","சைலம்"],["Neutralisation","நடுநிலையாக்கல்"],["Kelvin","கெல்வின்"]],"answer":0,"explanation":["Root hairs: Root extensions that increase the surface area for absorption.","வேர்த்தூவிகள்: உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்."]},{"id":97,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Loss of water as vapour from aerial parts of plants.","கண்டறிக: தாவரத்தின் தரைக்கு மேலுள்ள பகுதிகளிலிருந்து நீர் ஆவியாக வெளியேறுதல்."],"options":[["Radiation","வெப்பக் கதிர்வீச்சு"],["Transpiration","நீராவிப்போக்கு"],["Root hairs","வேர்த்தூவிகள்"],["Watt","வாட்"]],"answer":1,"explanation":["Transpiration: Loss of water as vapour from aerial parts of plants.","நீராவிப்போக்கு: தாவரத்தின் தரைக்கு மேலுள்ள பகுதிகளிலிருந்து நீர் ஆவியாக வெளியேறுதல்."]},{"id":98,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The largest ocean on Earth.","கண்டறிக: புவியின் மிகப்பெரிய பெருங்கடல்."],"options":[["Deposition","படிதல்"],["Tropic of Cancer","கடகரேகை"],["Longitude","தீர்க்கம்"],["Pacific Ocean","பசிபிக் பெருங்கடல்"]],"answer":3,"explanation":["Pacific Ocean: The largest ocean on Earth.","பசிபிக் பெருங்கடல்: புவியின் மிகப்பெரிய பெருங்கடல்."]},{"id":99,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The smallest of the five oceans.","கண்டறிக: ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்."],"options":[["V. O. Chidambaranar","வ. உ. சிதம்பரனார்"],["Peninsula","தீபகற்பம்"],["Arctic Ocean","ஆர்க்டிக் பெருங்கடல்"],["Tributary","துணையாறு"]],"answer":2,"explanation":["Arctic Ocean: The smallest of the five oceans.","ஆர்க்டிக் பெருங்கடல்: ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்."]},{"id":100,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 28 students, a student is in position 15 from the front. Find the position from the back.","28 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 15 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["14","14"],["15","15"],["28","28"],["16","16"]],"answer":0,"explanation":["Position from back = 28 − 15 + 1 = 14.","பின்னிருந்து இடம் = 28 − 15 + 1 = 14."]},{"id":101,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 28 m north, 21 m east, 7 m south and 21 m west. How far are you from the start, in metres?","28 மீ வடக்கு, 21 மீ கிழக்கு, 7 மீ தெற்கு, 21 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["21","21"],["24","24"],["22","22"],["42","42"]],"answer":0,"explanation":["East and west cancel. Net northward distance = 28 − 7 = 21 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 28 − 7 = 21 மீ."]},{"id":102,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 27 km east and then 36 km north. Find the straight-line distance from the start in km.","27 கி.மீ கிழக்கிலும் பின்னர் 36 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["44","44"],["45","45"],["55","55"],["48","48"]],"answer":1,"explanation":["Pythagoras: √(27² + 36²) = 45 km.","பிதாகரஸ் தேற்றம்: √(27² + 36²) = 45 கி.மீ."]},{"id":103,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 15 → 240, then 18 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 15 → 240 எனில் 18 → ?"],"options":[["344","344"],["342","342"],["345","345"],["347","347"]],"answer":1,"explanation":["18 × (18 + 1) = 342.","18 × (18 + 1) = 342."]},{"id":104,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 8 : 512 :: 11 : ?","மும்மடி விதியைப் பயன்படுத்துக: 8 : 512 :: 11 : ?"],"options":[["1331","1331"],["1336","1336"],["1334","1334"],["1332","1332"]],"answer":0,"explanation":["8³ = 512, so 11³ = 1331.","8³ = 512; எனவே 11³ = 1331."]},{"id":105,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 5 places forward in the alphabet (wrap Z to A). Code ROAD.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 5 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). ROAD இன் குறியீடு என்ன?"],"options":[["WTFI","WTFI"],["YVHK","YVHK"],["XUGJ","XUGJ"],["VSEH","VSEH"]],"answer":0,"explanation":["Each letter advances by 5: R → W, O → T, A → F, D → I","ஒவ்வோர் எழுத்தும் 5 இடங்கள் முன்னேறும்: R → W, O → T, A → F, D → I"]},{"id":106,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in RAIN.","A = 1, B = 2, …, Z = 26 எனில், RAIN என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["52","52"],["42","42"],["45","45"],["43","43"]],"answer":1,"explanation":["18 + 1 + 9 + 14 = 42.","18 + 1 + 9 + 14 = 42."]},{"id":107,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Tuesday. What day will it be after 66 days?","இன்று செவ்வாய். 66 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Sunday","ஞாயிறு"],["Monday","திங்கள்"],["Saturday","சனி"],["Friday","வெள்ளி"]],"answer":3,"explanation":["66 ÷ 7 leaves remainder 3. Move 3 days from Tuesday: Friday.","66 ஐ 7 ஆல் வகுக்க மீதி 3. செவ்வாய் கிழமையிலிருந்து 3 நாட்கள் நகர்ந்தால் வெள்ளி."]},{"id":108,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 12 students shakes hands once with every other student. How many handshakes occur?","12 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["71","71"],["67","67"],["66","66"],["132","132"]],"answer":2,"explanation":["Each pair is counted once: 12 × 11 ÷ 2 = 66.","ஒவ்வொரு இணையும் ஒருமுறை: 12 × 11 ÷ 2 = 66."]},{"id":109,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 32 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 32 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["99","99"],["100","100"],["97","97"],["194","194"]],"answer":2,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 31 = 97.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 31 = 97."]},{"id":110,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 8, 12, 17, 23, 30, ?","நிறைவு செய்க: 8, 12, 17, 23, 30, ?"],"options":[["43","43"],["76","76"],["38","38"],["39","39"]],"answer":2,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 38.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 38."]},{"id":111,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 17, 25, 42, 67, 109, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 17, 25, 42, 67, 109, ?"],"options":[["176","176"],["179","179"],["178","178"],["175","175"]],"answer":0,"explanation":["67 + 109 = 176.","67 + 109 = 176."]},{"id":112,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/8 + 1/8.","கூட்டிச் சுருக்குக: 4/8 + 1/8."],"options":[["1","1"],["7/8","7/8"],["3/4","3/4"],["5/8","5/8"]],"answer":3,"explanation":["(4 + 1)/8 = 5/8 = 5/8.","(4 + 1)/8 = 5/8 = 5/8."]},{"id":113,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 4 red and 12 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 4 சிவப்பு, 12 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["7/19","7/19"],["1/3","1/3"],["5/17","5/17"],["1/4","1/4"]],"answer":3,"explanation":["Favourable outcomes / total = 4/16 = 1/4.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 4/16 = 1/4."]},{"id":114,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 40% of 540.","540 இல் 40% காண்க."],"options":[["226","226"],["432","432"],["217","217"],["216","216"]],"answer":3,"explanation":["540 × 40 / 100 = 216.","540 × 40 / 100 = 216."]},{"id":115,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹900. Find the price after a 25% discount, in rupees.","குறித்த விலை ₹900. 25% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["1350","1350"],["678","678"],["685","685"],["675","675"]],"answer":3,"explanation":["Discount = ₹225. Pay 900 − 225 = ₹675.","தள்ளுபடி = ₹225. செலுத்துவது 900 − 225 = ₹675."]},{"id":116,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2800 at 6% per year for 4 years.","₹2800 க்கு ஆண்டுக்கு 6% வீதம் 4 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["672","672"],["682","682"],["675","675"],["671","671"]],"answer":0,"explanation":["PRT/100 = 2800 × 6 × 4 / 100 = ₹672.","PRT/100 = 2800 × 6 × 4 / 100 = ₹672."]},{"id":117,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 8x + 27 = 147.","x காண்க: 8x + 27 = 147."],"options":[["14","14"],["17","17"],["15","15"],["30","30"]],"answer":2,"explanation":["x = (147 − 27) ÷ 8 = 15.","x = (147 − 27) ÷ 8 = 15."]},{"id":118,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 7 cm long and 12 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 7 செ.மீ, அகலம் 12 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["84","84"],["83","83"],["87","87"],["168","168"]],"answer":0,"explanation":["Area = length × width = 7 × 12 = 84 cm².","பரப்பளவு = நீளம் × அகலம் = 7 × 12 = 84 ச.செ.மீ."]},{"id":119,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 30 m and 7 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 30 மீ மற்றும் 7 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["148","148"],["73","73"],["74","74"],["76","76"]],"answer":2,"explanation":["Perimeter = 2(30 + 7) = 74 m.","சுற்றளவு = 2(30 + 7) = 74 மீ."]},{"id":120,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The development of a seed into a seedling.","கண்டறிக: விதை ஒரு நாற்றாக வளரத் தொடங்கும் நிகழ்வு."],"options":[["Germination","முளைத்தல்"],["Hertz","ஹெர்ட்ஸ்"],["Root hairs","வேர்த்தூவிகள்"],["Freezing","உறைதல்"]],"answer":0,"explanation":["Germination: The development of a seed into a seedling.","முளைத்தல்: விதை ஒரு நாற்றாக வளரத் தொடங்கும் நிகழ்வு."]},{"id":121,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Transfer of pollen from anther to stigma.","கண்டறிக: மகரந்தப்பையிலிருந்து சூலகமுடிக்கு மகரந்தம் மாற்றப்படுதல்."],"options":[["Chlorophyll","பச்சையம்"],["Pollination","மகரந்தச் சேர்க்கை"],["Kelvin","கெல்வின்"],["Nitrogen","நைட்ரஜன்"]],"answer":1,"explanation":["Pollination: Transfer of pollen from anther to stigma.","மகரந்தச் சேர்க்கை: மகரந்தப்பையிலிருந்து சூலகமுடிக்கு மகரந்தம் மாற்றப்படுதல்."]},{"id":122,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Fusion of male and female gametes.","கண்டறிக: ஆண் மற்றும் பெண் இனச்செல்களின் இணைவு."],"options":[["Mitochondrion","மைட்டோகாண்ட்ரியா"],["Fertilisation","கருவுறுதல்"],["Chloroplast","பசுங்கணிகம்"],["Reflection","எதிரொளிப்பு"]],"answer":1,"explanation":["Fertilisation: Fusion of male and female gametes.","கருவுறுதல்: ஆண் மற்றும் பெண் இனச்செல்களின் இணைவு."]},{"id":123,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The imaginary circle at 0° latitude.","கண்டறிக: 0° அட்சத்தில் அமைந்துள்ள கற்பனை வட்டம்."],"options":[["Equator","நிலநடுக்கோடு"],["Subhas Chandra Bose","சுபாஷ் சந்திர போஸ்"],["Anemometer","காற்று வேகமானி"],["Longitude","தீர்க்கம்"]],"answer":0,"explanation":["Equator: The imaginary circle at 0° latitude.","நிலநடுக்கோடு: 0° அட்சத்தில் அமைந்துள்ள கற்பனை வட்டம்."]},{"id":124,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The reference meridian at 0° longitude.","கண்டறிக: 0° தீர்க்கத்தில் அமைந்துள்ள ஆதாரத் தீர்க்கக்கோடு."],"options":[["V. O. Chidambaranar","வ. உ. சிதம்பரனார்"],["Prime Meridian","முதன்மை தீர்க்கக்கோடு"],["Peninsula","தீபகற்பம்"],["Australia","ஆஸ்திரேலியா"]],"answer":1,"explanation":["Prime Meridian: The reference meridian at 0° longitude.","முதன்மை தீர்க்கக்கோடு: 0° தீர்க்கத்தில் அமைந்துள்ள ஆதாரத் தீர்க்கக்கோடு."]},{"id":125,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 16, 21, 26, 31, 36, …","அடுத்த எண்ணைக் காண்க: 16, 21, 26, 31, 36, …"],"options":[["46","46"],["82","82"],["40","40"],["41","41"]],"answer":3,"explanation":["Add 5 each time. 36 + 5 = 41.","ஒவ்வொரு முறையும் 5 கூட்டுக. 36 + 5 = 41."]},{"id":126,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 24, 48, 96, 192, ?","தொடரை நிறைவு செய்க: 24, 48, 96, 192, ?"],"options":[["384","384"],["394","394"],["386","386"],["387","387"]],"answer":0,"explanation":["Double each term: 192 × 2 = 384.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 192 × 2 = 384."]},{"id":127,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 4, 16, 40, 88, ?","அடுத்த உறுப்பைக் காண்க: 4, 16, 40, 88, ?"],"options":[["184","184"],["186","186"],["187","187"],["368","368"]],"answer":0,"explanation":["Multiply by 2, then add 8: 88 × 2 + 8 = 184.","2 ஆல் பெருக்கி 8 கூட்டுக: 88 × 2 + 8 = 184."]},{"id":128,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 14, 20, ?, 32, 38","விடுபட்ட எண்ணைக் காண்க: 14, 20, ?, 32, 38"],"options":[["27","27"],["25","25"],["26","26"],["31","31"]],"answer":2,"explanation":["The common difference is 6. 20 + 6 = 26.","பொது வித்தியாசம் 6. 20 + 6 = 26."]},{"id":129,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 9, 16, 25, 36, ?","தொடர்க: 9, 16, 25, 36, ?"],"options":[["49","49"],["98","98"],["51","51"],["52","52"]],"answer":0,"explanation":["These are squares of 3, 4, 5, 6. Next: 7² = 49.","இவை 3, 4, 5, 6 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 7² = 49."]},{"id":130,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 26 from the front and position 4 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 26 ஆவது, பின்னிருந்து 4 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["29","29"],["39","39"],["58","58"],["28","28"]],"answer":0,"explanation":["Total = 26 + 4 − 1 = 29; the student is counted only once.","மொத்தம் = 26 + 4 − 1 = 29; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":131,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 53 students, a student is in position 21 from the front. Find the position from the back.","53 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 21 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["36","36"],["66","66"],["35","35"],["33","33"]],"answer":3,"explanation":["Position from back = 53 − 21 + 1 = 33.","பின்னிருந்து இடம் = 53 − 21 + 1 = 33."]},{"id":132,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 41 m north, 24 m east, 8 m south and 24 m west. How far are you from the start, in metres?","41 மீ வடக்கு, 24 மீ கிழக்கு, 8 மீ தெற்கு, 24 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["34","34"],["43","43"],["33","33"],["38","38"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 41 − 8 = 33 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 41 − 8 = 33 மீ."]},{"id":133,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 18 km east and then 24 km north. Find the straight-line distance from the start in km.","18 கி.மீ கிழக்கிலும் பின்னர் 24 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["29","29"],["60","60"],["30","30"],["31","31"]],"answer":2,"explanation":["Pythagoras: √(18² + 24²) = 30 km.","பிதாகரஸ் தேற்றம்: √(18² + 24²) = 30 கி.மீ."]},{"id":134,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 11 → 132, then 21 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 11 → 132 எனில் 21 → ?"],"options":[["924","924"],["472","472"],["467","467"],["462","462"]],"answer":3,"explanation":["21 × (21 + 1) = 462.","21 × (21 + 1) = 462."]},{"id":135,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 2 : 8 :: 17 : ?","மும்மடி விதியைப் பயன்படுத்துக: 2 : 8 :: 17 : ?"],"options":[["4923","4923"],["4915","4915"],["4913","4913"],["4912","4912"]],"answer":2,"explanation":["2³ = 8, so 17³ = 4913.","2³ = 8; எனவே 17³ = 4913."]},{"id":136,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 2 places forward in the alphabet (wrap Z to A). Code FISH.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 2 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). FISH இன் குறியீடு என்ன?"],"options":[["ILVK","ILVK"],["HKUJ","HKUJ"],["JMWL","JMWL"],["GJTI","GJTI"]],"answer":1,"explanation":["Each letter advances by 2: F → H, I → K, S → U, H → J","ஒவ்வோர் எழுத்தும் 2 இடங்கள் முன்னேறும்: F → H, I → K, S → U, H → J"]},{"id":137,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 54 cm and height 15 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 54 செ.மீ, உயரம் 15 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["407","407"],["404","404"],["405","405"],["415","415"]],"answer":2,"explanation":["Area = ½ × 54 × 15 = 405 cm².","பரப்பளவு = ½ × 54 × 15 = 405 ச.செ.மீ."]},{"id":138,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 13 cm × 12 cm × 2 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 13 செ.மீ × 12 செ.மீ × 2 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["312","312"],["317","317"],["311","311"],["314","314"]],"answer":0,"explanation":["Volume = length × breadth × height = 13 × 12 × 2 = 312 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 13 × 12 × 2 = 312 க.செ.மீ."]},{"id":139,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 16, 26, 36, 46, 56.","16, 26, 36, 46, 56 ஆகியவற்றின் சராசரி காண்க."],"options":[["72","72"],["38","38"],["46","46"],["36","36"]],"answer":3,"explanation":["Sum ÷ count = 180 ÷ 5 = 36.","கூடுதல் ÷ எண்ணிக்கை = 180 ÷ 5 = 36."]},{"id":140,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 486 km in 18 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 18 மணி நேரத்தில் 486 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["32","32"],["54","54"],["30","30"],["27","27"]],"answer":3,"explanation":["Speed = distance ÷ time = 486 ÷ 18 = 27 km/h.","வேகம் = தொலைவு ÷ நேரம் = 486 ÷ 18 = 27 கி.மீ/மணி."]},{"id":141,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 217 in the ratio 3 : 4. Find the smaller share.","217 ஐ 3 : 4 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["96","96"],["98","98"],["93","93"],["103","103"]],"answer":2,"explanation":["Smaller share = 217 × 3/(3+4) = 93.","சிறிய பங்கு = 217 × 3/(3+4) = 93."]},{"id":142,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 19 and 22.","19 மற்றும் 22 இன் மீ.பொ.வ. காண்க."],"options":[["1","1"],["3","3"],["4","4"],["0","0"]],"answer":0,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":143,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 39 and 12.","39 மற்றும் 12 இன் மீ.பொ.ம. காண்க."],"options":[["157","157"],["158","158"],["159","159"],["156","156"]],"answer":3,"explanation":["LCM = product ÷ HCF = 468 ÷ 3 = 156.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 468 ÷ 3 = 156."]},{"id":144,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹2600 is sold for ₹3120. Find the profit percentage.","₹2600 க்கு வாங்கிய பொருள் ₹3120 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["30","30"],["20","20"],["19","19"],["25","25"]],"answer":1,"explanation":["Profit = ₹520. Profit% = 520 × 100 / 2600 = 20%.","இலாபம் = ₹520. இலாப% = 520 × 100 / 2600 = 20%."]},{"id":145,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The floral part that usually develops into a fruit after fertilisation.","கண்டறிக: கருவுறுதலுக்குப் பிறகு பொதுவாக கனியாக வளரும் மலரின் பகுதி."],"options":[["Arteries","தமனிகள்"],["Ovary of a flower","மலரின் சூலகப்பை"],["Convection","வெப்பச் சலனம்"],["Cell membrane","செல் சவ்வு"]],"answer":1,"explanation":["Ovary of a flower: The floral part that usually develops into a fruit after fertilisation.","மலரின் சூலகப்பை: கருவுறுதலுக்குப் பிறகு பொதுவாக கனியாக வளரும் மலரின் பகுதி."]},{"id":146,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The organelle where most aerobic cellular respiration takes place.","கண்டறிக: பெரும்பாலான ஆக்சிஜன் சார்ந்த செல் சுவாசம் நடைபெறும் செல் நுண்ணுறுப்பு."],"options":[["Kelvin","கெல்வின்"],["Mitochondrion","மைட்டோகாண்ட்ரியா"],["Iodine","அயோடின்"],["Fertilisation","கருவுறுதல்"]],"answer":1,"explanation":["Mitochondrion: The organelle where most aerobic cellular respiration takes place.","மைட்டோகாண்ட்ரியா: பெரும்பாலான ஆக்சிஜன் சார்ந்த செல் சுவாசம் நடைபெறும் செல் நுண்ணுறுப்பு."]},{"id":147,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The cellular structure responsible for protein synthesis.","கண்டறிக: புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு."],"options":[["Chlorophyll","பச்சையம்"],["Veins","சிரைகள்"],["Ribosome","ரைபோசோம்"],["Fertilisation","கருவுறுதல்"]],"answer":2,"explanation":["Ribosome: The cellular structure responsible for protein synthesis.","ரைபோசோம்: புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு."]},{"id":148,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The latitude circle at about 23.5° north.","கண்டறிக: சுமார் 23.5° வட அட்சத்தில் அமைந்துள்ள வட்டம்."],"options":[["Subhas Chandra Bose","சுபாஷ் சந்திர போஸ்"],["Tropic of Cancer","கடகரேகை"],["Climate","காலநிலை"],["Pacific Ocean","பசிபிக் பெருங்கடல்"]],"answer":1,"explanation":["Tropic of Cancer: The latitude circle at about 23.5° north.","கடகரேகை: சுமார் 23.5° வட அட்சத்தில் அமைந்துள்ள வட்டம்."]},{"id":149,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The latitude circle at about 23.5° south.","கண்டறிக: சுமார் 23.5° தென் அட்சத்தில் அமைந்துள்ள வட்டம்."],"options":[["Equator","நிலநடுக்கோடு"],["Barometer","காற்றழுத்தமானி"],["Tropic of Capricorn","மகரரேகை"],["Rajaraja I","முதலாம் இராஜராஜன்"]],"answer":2,"explanation":["Tropic of Capricorn: The latitude circle at about 23.5° south.","மகரரேகை: சுமார் 23.5° தென் அட்சத்தில் அமைந்துள்ள வட்டம்."]},{"id":150,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in EARTH.","A = 1, B = 2, …, Z = 26 எனில், EARTH என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["57","57"],["55","55"],["62","62"],["52","52"]],"answer":3,"explanation":["5 + 1 + 18 + 20 + 8 = 52.","5 + 1 + 18 + 20 + 8 = 52."]},{"id":151,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Friday. What day will it be after 71 days?","இன்று வெள்ளி. 71 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Saturday","சனி"],["Tuesday","செவ்வாய்"],["Monday","திங்கள்"],["Sunday","ஞாயிறு"]],"answer":0,"explanation":["71 ÷ 7 leaves remainder 1. Move 1 days from Friday: Saturday.","71 ஐ 7 ஆல் வகுக்க மீதி 1. வெள்ளி கிழமையிலிருந்து 1 நாட்கள் நகர்ந்தால் சனி."]},{"id":152,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 16 students shakes hands once with every other student. How many handshakes occur?","16 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["240","240"],["130","130"],["120","120"],["119","119"]],"answer":2,"explanation":["Each pair is counted once: 16 × 15 ÷ 2 = 120.","ஒவ்வொரு இணையும் ஒருமுறை: 16 × 15 ÷ 2 = 120."]},{"id":153,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 9 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 9 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["30","30"],["33","33"],["27","27"],["28","28"]],"answer":3,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 8 = 28.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 8 = 28."]},{"id":154,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 11, 14, 18, 23, 29, ?","நிறைவு செய்க: 11, 14, 18, 23, 29, ?"],"options":[["72","72"],["36","36"],["41","41"],["35","35"]],"answer":1,"explanation":["Differences increase by 1: 3, 4, 5, 6, 7. Next = 36.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 3, 4, 5, 6, 7. அடுத்த எண் 36."]},{"id":155,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 8, 13, 21, 34, 55, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 8, 13, 21, 34, 55, ?"],"options":[["88","88"],["94","94"],["89","89"],["92","92"]],"answer":2,"explanation":["34 + 55 = 89.","34 + 55 = 89."]},{"id":156,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 11, 13, 15, 17, 19, …","அடுத்த எண்ணைக் காண்க: 11, 13, 15, 17, 19, …"],"options":[["23","23"],["42","42"],["20","20"],["21","21"]],"answer":3,"explanation":["Add 2 each time. 19 + 2 = 21.","ஒவ்வொரு முறையும் 2 கூட்டுக. 19 + 2 = 21."]},{"id":157,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 5, 10, 20, 40, ?","தொடரை நிறைவு செய்க: 5, 10, 20, 40, ?"],"options":[["90","90"],["79","79"],["80","80"],["83","83"]],"answer":2,"explanation":["Double each term: 40 × 2 = 80.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 40 × 2 = 80."]},{"id":158,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 10, 29, 67, 143, ?","அடுத்த உறுப்பைக் காண்க: 10, 29, 67, 143, ?"],"options":[["297","297"],["296","296"],["298","298"],["295","295"]],"answer":3,"explanation":["Multiply by 2, then add 9: 143 × 2 + 9 = 295.","2 ஆல் பெருக்கி 9 கூட்டுக: 143 × 2 + 9 = 295."]},{"id":159,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 26, 28, ?, 32, 34","விடுபட்ட எண்ணைக் காண்க: 26, 28, ?, 32, 34"],"options":[["30","30"],["29","29"],["40","40"],["31","31"]],"answer":0,"explanation":["The common difference is 2. 28 + 2 = 30.","பொது வித்தியாசம் 2. 28 + 2 = 30."]},{"id":160,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 196, 225, 256, 289, ?","தொடர்க: 196, 225, 256, 289, ?"],"options":[["325","325"],["324","324"],["329","329"],["326","326"]],"answer":1,"explanation":["These are squares of 14, 15, 16, 17. Next: 18² = 324.","இவை 14, 15, 16, 17 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 18² = 324."]},{"id":161,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 5 from the front and position 4 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 5 ஆவது, பின்னிருந்து 4 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["8","8"],["16","16"],["9","9"],["10","10"]],"answer":0,"explanation":["Total = 5 + 4 − 1 = 8; the student is counted only once.","மொத்தம் = 5 + 4 − 1 = 8; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":162,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 70° and 50°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 70°, 50°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["65","65"],["59","59"],["60","60"],["120","120"]],"answer":2,"explanation":["180 − 70 − 50 = 60°.","180 − 70 − 50 = 60°."]},{"id":163,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 29°, in degrees.","29° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["154","154"],["150","150"],["153","153"],["151","151"]],"answer":3,"explanation":["Supplementary angles sum to 180°. 180 − 29 = 151°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 29 = 151°."]},{"id":164,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/5 + 1/5.","கூட்டிச் சுருக்குக: 4/5 + 1/5."],"options":[["6/5","6/5"],["7/5","7/5"],["1","1"],["8/5","8/5"]],"answer":2,"explanation":["(4 + 1)/5 = 5/5 = 1.","(4 + 1)/5 = 5/5 = 1."]},{"id":165,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 5 red and 12 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 5 சிவப்பு, 12 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["5/17","5/17"],["1/3","1/3"],["7/19","7/19"],["2/5","2/5"]],"answer":0,"explanation":["Favourable outcomes / total = 5/17 = 5/17.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 5/17 = 5/17."]},{"id":166,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 75% of 560.","560 இல் 75% காண்க."],"options":[["420","420"],["423","423"],["430","430"],["421","421"]],"answer":0,"explanation":["560 × 75 / 100 = 420.","560 × 75 / 100 = 420."]},{"id":167,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹1100. Find the price after a 15% discount, in rupees.","குறித்த விலை ₹1100. 15% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["937","937"],["934","934"],["935","935"],["945","945"]],"answer":2,"explanation":["Discount = ₹165. Pay 1100 − 165 = ₹935.","தள்ளுபடி = ₹165. செலுத்துவது 1100 − 165 = ₹935."]},{"id":168,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹1200 at 6% per year for 3 years.","₹1200 க்கு ஆண்டுக்கு 6% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["221","221"],["216","216"],["217","217"],["215","215"]],"answer":1,"explanation":["PRT/100 = 1200 × 6 × 3 / 100 = ₹216.","PRT/100 = 1200 × 6 × 3 / 100 = ₹216."]},{"id":169,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 14x + 6 = 90.","x காண்க: 14x + 6 = 90."],"options":[["9","9"],["16","16"],["6","6"],["5","5"]],"answer":2,"explanation":["x = (90 − 6) ÷ 14 = 6.","x = (90 − 6) ÷ 14 = 6."]},{"id":170,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The selectively permeable boundary of a cell.","கண்டறிக: தேர்ந்தெடுத்துப் பொருட்களை அனுமதிக்கும் செல்லின் எல்லை."],"options":[["Arteries","தமனிகள்"],["Cell membrane","செல் சவ்வு"],["Xylem","சைலம்"],["Pollination","மகரந்தச் சேர்க்கை"]],"answer":1,"explanation":["Cell membrane: The selectively permeable boundary of a cell.","செல் சவ்வு: தேர்ந்தெடுத்துப் பொருட்களை அனுமதிக்கும் செல்லின் எல்லை."]},{"id":171,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The rigid outer layer outside the membrane in a plant cell.","கண்டறிக: தாவரச் செல்லில் செல் சவ்விற்கு வெளியே உள்ள உறுதியான அடுக்கு."],"options":[["Mitochondrion","மைட்டோகாண்ட்ரியா"],["Cell wall","செல்சுவர்"],["Transpiration","நீராவிப்போக்கு"],["Enamel","பற்சிப்பி"]],"answer":1,"explanation":["Cell wall: The rigid outer layer outside the membrane in a plant cell.","செல்சுவர்: தாவரச் செல்லில் செல் சவ்விற்கு வெளியே உள்ள உறுதியான அடுக்கு."]},{"id":172,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The organelle in green plant cells where photosynthesis occurs.","கண்டறிக: பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு."],"options":[["Condensation","ஆவி சுருங்குதல்"],["Neutralisation","நடுநிலையாக்கல்"],["Kelvin","கெல்வின்"],["Chloroplast","பசுங்கணிகம்"]],"answer":3,"explanation":["Chloroplast: The organelle in green plant cells where photosynthesis occurs.","பசுங்கணிகம்: பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு."]},{"id":173,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Angular distance north or south of the Equator.","கண்டறிக: நிலநடுக்கோட்டிலிருந்து வடக்கு அல்லது தெற்காக அளவிடப்படும் கோணத் தொலைவு."],"options":[["Subhas Chandra Bose","சுபாஷ் சந்திர போஸ்"],["Latitude","அட்சம்"],["V. O. Chidambaranar","வ. உ. சிதம்பரனார்"],["Rain gauge","மழைமானி"]],"answer":1,"explanation":["Latitude: Angular distance north or south of the Equator.","அட்சம்: நிலநடுக்கோட்டிலிருந்து வடக்கு அல்லது தெற்காக அளவிடப்படும் கோணத் தொலைவு."]},{"id":174,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Angular distance east or west of the Prime Meridian.","கண்டறிக: முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு."],"options":[["Longitude","தீர்க்கம்"],["Tropic of Capricorn","மகரரேகை"],["Rajendra I","முதலாம் இராஜேந்திரன்"],["Barometer","காற்றழுத்தமானி"]],"answer":0,"explanation":["Longitude: Angular distance east or west of the Prime Meridian.","தீர்க்கம்: முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு."]},{"id":175,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 12 students, a student is in position 6 from the front. Find the position from the back.","12 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 6 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["7","7"],["17","17"],["9","9"],["8","8"]],"answer":0,"explanation":["Position from back = 12 − 6 + 1 = 7.","பின்னிருந்து இடம் = 12 − 6 + 1 = 7."]},{"id":176,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 38 m north, 11 m east, 8 m south and 11 m west. How far are you from the start, in metres?","38 மீ வடக்கு, 11 மீ கிழக்கு, 8 மீ தெற்கு, 11 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["60","60"],["35","35"],["40","40"],["30","30"]],"answer":3,"explanation":["East and west cancel. Net northward distance = 38 − 8 = 30 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 38 − 8 = 30 மீ."]},{"id":177,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 6 km east and then 8 km north. Find the straight-line distance from the start in km.","6 கி.மீ கிழக்கிலும் பின்னர் 8 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["20","20"],["10","10"],["12","12"],["13","13"]],"answer":1,"explanation":["Pythagoras: √(6² + 8²) = 10 km.","பிதாகரஸ் தேற்றம்: √(6² + 8²) = 10 கி.மீ."]},{"id":178,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 7 → 56, then 22 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 7 → 56 எனில் 22 → ?"],"options":[["516","516"],["1012","1012"],["506","506"],["511","511"]],"answer":2,"explanation":["22 × (22 + 1) = 506.","22 × (22 + 1) = 506."]},{"id":179,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 2 : 8 :: 15 : ?","மும்மடி விதியைப் பயன்படுத்துக: 2 : 8 :: 15 : ?"],"options":[["6750","6750"],["3378","3378"],["3380","3380"],["3375","3375"]],"answer":3,"explanation":["2³ = 8, so 15³ = 3375.","2³ = 8; எனவே 15³ = 3375."]},{"id":180,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 3 places forward in the alphabet (wrap Z to A). Code FISH.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 3 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). FISH இன் குறியீடு என்ன?"],"options":[["KNXM","KNXM"],["JMWL","JMWL"],["HKUJ","HKUJ"],["ILVK","ILVK"]],"answer":3,"explanation":["Each letter advances by 3: F → I, I → L, S → V, H → K","ஒவ்வோர் எழுத்தும் 3 இடங்கள் முன்னேறும்: F → I, I → L, S → V, H → K"]},{"id":181,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in BOOK.","A = 1, B = 2, …, Z = 26 எனில், BOOK என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["48","48"],["43","43"],["53","53"],["42","42"]],"answer":1,"explanation":["2 + 15 + 15 + 11 = 43.","2 + 15 + 15 + 11 = 43."]},{"id":182,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Tuesday. What day will it be after 20 days?","இன்று செவ்வாய். 20 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Tuesday","செவ்வாய்"],["Wednesday","புதன்"],["Monday","திங்கள்"],["Thursday","வியாழன்"]],"answer":2,"explanation":["20 ÷ 7 leaves remainder 6. Move 6 days from Tuesday: Monday.","20 ஐ 7 ஆல் வகுக்க மீதி 6. செவ்வாய் கிழமையிலிருந்து 6 நாட்கள் நகர்ந்தால் திங்கள்."]},{"id":183,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 10 students shakes hands once with every other student. How many handshakes occur?","10 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["45","45"],["44","44"],["47","47"],["50","50"]],"answer":0,"explanation":["Each pair is counted once: 10 × 9 ÷ 2 = 45.","ஒவ்வொரு இணையும் ஒருமுறை: 10 × 9 ÷ 2 = 45."]},{"id":184,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 30 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 30 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["91","91"],["101","101"],["182","182"],["94","94"]],"answer":0,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 29 = 91.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 29 = 91."]},{"id":185,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 11, 15, 20, 26, 33, ?","நிறைவு செய்க: 11, 15, 20, 26, 33, ?"],"options":[["51","51"],["82","82"],["41","41"],["44","44"]],"answer":2,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 41.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 41."]},{"id":186,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 20, 28, 48, 76, 124, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 20, 28, 48, 76, 124, ?"],"options":[["205","205"],["200","200"],["210","210"],["203","203"]],"answer":1,"explanation":["76 + 124 = 200.","76 + 124 = 200."]},{"id":187,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 17 cm long and 12 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 17 செ.மீ, அகலம் 12 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["209","209"],["203","203"],["204","204"],["214","214"]],"answer":2,"explanation":["Area = length × width = 17 × 12 = 204 cm².","பரப்பளவு = நீளம் × அகலம் = 17 × 12 = 204 ச.செ.மீ."]},{"id":188,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 16 m and 16 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 16 மீ மற்றும் 16 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["64","64"],["69","69"],["63","63"],["74","74"]],"answer":0,"explanation":["Perimeter = 2(16 + 16) = 64 m.","சுற்றளவு = 2(16 + 16) = 64 மீ."]},{"id":189,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 12 cm and height 18 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 12 செ.மீ, உயரம் 18 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["108","108"],["110","110"],["118","118"],["111","111"]],"answer":0,"explanation":["Area = ½ × 12 × 18 = 108 cm².","பரப்பளவு = ½ × 12 × 18 = 108 ச.செ.மீ."]},{"id":190,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 33 cm × 3 cm × 8 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 33 செ.மீ × 3 செ.மீ × 8 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["794","794"],["795","795"],["791","791"],["792","792"]],"answer":3,"explanation":["Volume = length × breadth × height = 33 × 3 × 8 = 792 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 33 × 3 × 8 = 792 க.செ.மீ."]},{"id":191,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 19, 33, 47, 61, 75.","19, 33, 47, 61, 75 ஆகியவற்றின் சராசரி காண்க."],"options":[["50","50"],["57","57"],["47","47"],["46","46"]],"answer":2,"explanation":["Sum ÷ count = 235 ÷ 5 = 47.","கூடுதல் ÷ எண்ணிக்கை = 235 ÷ 5 = 47."]},{"id":192,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 387 km in 9 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 9 மணி நேரத்தில் 387 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["43","43"],["53","53"],["46","46"],["45","45"]],"answer":0,"explanation":["Speed = distance ÷ time = 387 ÷ 9 = 43 km/h.","வேகம் = தொலைவு ÷ நேரம் = 387 ÷ 9 = 43 கி.மீ/மணி."]},{"id":193,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 238 in the ratio 7 : 10. Find the smaller share.","238 ஐ 7 : 10 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["100","100"],["99","99"],["98","98"],["196","196"]],"answer":2,"explanation":["Smaller share = 238 × 7/(7+10) = 98.","சிறிய பங்கு = 238 × 7/(7+10) = 98."]},{"id":194,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 37 and 46.","37 மற்றும் 46 இன் மீ.பொ.வ. காண்க."],"options":[["3","3"],["1","1"],["2","2"],["0","0"]],"answer":1,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":195,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: A fluid-filled cell compartment used for storage.","கண்டறிக: சேமிப்பிற்கு உதவும் திரவம் நிரம்பிய செல் பகுதி."],"options":[["Iodine","அயோடின்"],["Vacuole","நுண்குமிழ்"],["Solute","கரைபொருள்"],["Evaporation","ஆவியாக்குதல்"]],"answer":1,"explanation":["Vacuole: A fluid-filled cell compartment used for storage.","நுண்குமிழ்: சேமிப்பிற்கு உதவும் திரவம் நிரம்பிய செல் பகுதி."]},{"id":196,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Blood components that help in clotting.","கண்டறிக: இரத்தம் உறைதலுக்கு உதவும் இரத்தக் கூறுகள்."],"options":[["Ampere","ஆம்பியர்"],["Mitochondrion","மைட்டோகாண்ட்ரியா"],["Platelets","இரத்தத் தட்டுகள்"],["Melting","உருகுதல்"]],"answer":2,"explanation":["Platelets: Blood components that help in clotting.","இரத்தத் தட்டுகள்: இரத்தம் உறைதலுக்கு உதவும் இரத்தக் கூறுகள்."]},{"id":197,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Blood cells chiefly involved in defence against infection.","கண்டறிக: நோய்த்தொற்றுக்கு எதிரான பாதுகாப்பில் முதன்மையாக ஈடுபடும் இரத்த அணுக்கள்."],"options":[["Nitrogen","நைட்ரஜன்"],["White blood cells","வெள்ளையணுக்கள்"],["Chloroplast","பசுங்கணிகம்"],["Xylem","சைலம்"]],"answer":1,"explanation":["White blood cells: Blood cells chiefly involved in defence against infection.","வெள்ளையணுக்கள்: நோய்த்தொற்றுக்கு எதிரான பாதுகாப்பில் முதன்மையாக ஈடுபடும் இரத்த அணுக்கள்."]},{"id":198,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Earth’s movement around its own axis.","கண்டறிக: புவி தனது அச்சில் சுழலும் இயக்கம்."],"options":[["Weather","வானிலை"],["Rotation","தற்சுழற்சி"],["Australia","ஆஸ்திரேலியா"],["Latitude","அட்சம்"]],"answer":1,"explanation":["Rotation: Earth’s movement around its own axis.","தற்சுழற்சி: புவி தனது அச்சில் சுழலும் இயக்கம்."]},{"id":199,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Earth’s movement around the Sun.","கண்டறிக: புவி சூரியனைச் சுற்றி வரும் இயக்கம்."],"options":[["Revolution","சுற்றிவருதல்"],["Arctic Ocean","ஆர்க்டிக் பெருங்கடல்"],["Plateau","பீடபூமி"],["Asia","ஆசியா"]],"answer":0,"explanation":["Revolution: Earth’s movement around the Sun.","சுற்றிவருதல்: புவி சூரியனைச் சுற்றி வரும் இயக்கம்."]},{"id":200,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 4, 6, 8, 10, 12, …","அடுத்த எண்ணைக் காண்க: 4, 6, 8, 10, 12, …"],"options":[["17","17"],["13","13"],["16","16"],["14","14"]],"answer":3,"explanation":["Add 2 each time. 12 + 2 = 14.","ஒவ்வொரு முறையும் 2 கூட்டுக. 12 + 2 = 14."]},{"id":201,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 31, 62, 124, 248, ?","தொடரை நிறைவு செய்க: 31, 62, 124, 248, ?"],"options":[["495","495"],["499","499"],["496","496"],["506","506"]],"answer":2,"explanation":["Double each term: 248 × 2 = 496.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 248 × 2 = 496."]},{"id":202,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 22, 46, 94, 190, ?","அடுத்த உறுப்பைக் காண்க: 22, 46, 94, 190, ?"],"options":[["383","383"],["385","385"],["382","382"],["384","384"]],"answer":2,"explanation":["Multiply by 2, then add 2: 190 × 2 + 2 = 382.","2 ஆல் பெருக்கி 2 கூட்டுக: 190 × 2 + 2 = 382."]},{"id":203,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 28, 30, ?, 34, 36","விடுபட்ட எண்ணைக் காண்க: 28, 30, ?, 34, 36"],"options":[["37","37"],["35","35"],["32","32"],["64","64"]],"answer":2,"explanation":["The common difference is 2. 30 + 2 = 32.","பொது வித்தியாசம் 2. 30 + 2 = 32."]},{"id":204,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 576, 625, 676, 729, ?","தொடர்க: 576, 625, 676, 729, ?"],"options":[["783","783"],["1568","1568"],["794","794"],["784","784"]],"answer":3,"explanation":["These are squares of 24, 25, 26, 27. Next: 28² = 784.","இவை 24, 25, 26, 27 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 28² = 784."]},{"id":205,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 21 from the front and position 11 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 21 ஆவது, பின்னிருந்து 11 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["30","30"],["31","31"],["34","34"],["32","32"]],"answer":1,"explanation":["Total = 21 + 11 − 1 = 31; the student is counted only once.","மொத்தம் = 21 + 11 − 1 = 31; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":206,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 37 students, a student is in position 11 from the front. Find the position from the back.","37 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 11 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["27","27"],["28","28"],["32","32"],["54","54"]],"answer":0,"explanation":["Position from back = 37 − 11 + 1 = 27.","பின்னிருந்து இடம் = 37 − 11 + 1 = 27."]},{"id":207,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 38 m north, 13 m east, 6 m south and 13 m west. How far are you from the start, in metres?","38 மீ வடக்கு, 13 மீ கிழக்கு, 6 மீ தெற்கு, 13 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["33","33"],["32","32"],["37","37"],["64","64"]],"answer":1,"explanation":["East and west cancel. Net northward distance = 38 − 6 = 32 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 38 − 6 = 32 மீ."]},{"id":208,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 21 km east and then 28 km north. Find the straight-line distance from the start in km.","21 கி.மீ கிழக்கிலும் பின்னர் 28 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["70","70"],["38","38"],["34","34"],["35","35"]],"answer":3,"explanation":["Pythagoras: √(21² + 28²) = 35 km.","பிதாகரஸ் தேற்றம்: √(21² + 28²) = 35 கி.மீ."]},{"id":209,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 5 → 30, then 30 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 5 → 30 எனில் 30 → ?"],"options":[["935","935"],["930","930"],["931","931"],["929","929"]],"answer":1,"explanation":["30 × (30 + 1) = 930.","30 × (30 + 1) = 930."]},{"id":210,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 9 : 729 :: 17 : ?","மும்மடி விதியைப் பயன்படுத்துக: 9 : 729 :: 17 : ?"],"options":[["4913","4913"],["4923","4923"],["4915","4915"],["4916","4916"]],"answer":0,"explanation":["9³ = 729, so 17³ = 4913.","9³ = 729; எனவே 17³ = 4913."]},{"id":211,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 5 places forward in the alphabet (wrap Z to A). Code LAMP.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 5 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). LAMP இன் குறியீடு என்ன?"],"options":[["PEQT","PEQT"],["QFRU","QFRU"],["RGSV","RGSV"],["SHTW","SHTW"]],"answer":1,"explanation":["Each letter advances by 5: L → Q, A → F, M → R, P → U","ஒவ்வோர் எழுத்தும் 5 இடங்கள் முன்னேறும்: L → Q, A → F, M → R, P → U"]},{"id":212,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 23 and 6.","23 மற்றும் 6 இன் மீ.பொ.ம. காண்க."],"options":[["138","138"],["140","140"],["137","137"],["148","148"]],"answer":0,"explanation":["LCM = product ÷ HCF = 138 ÷ 1 = 138.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 138 ÷ 1 = 138."]},{"id":213,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹700 is sold for ₹735. Find the profit percentage.","₹700 க்கு வாங்கிய பொருள் ₹735 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["7","7"],["4","4"],["6","6"],["5","5"]],"answer":3,"explanation":["Profit = ₹35. Profit% = 35 × 100 / 700 = 5%.","இலாபம் = ₹35. இலாப% = 35 × 100 / 700 = 5%."]},{"id":214,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 29° and 31°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 29°, 31°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["123","123"],["120","120"],["122","122"],["119","119"]],"answer":1,"explanation":["180 − 29 − 31 = 120°.","180 − 29 − 31 = 120°."]},{"id":215,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 52°, in degrees.","52° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["129","129"],["256","256"],["128","128"],["131","131"]],"answer":2,"explanation":["Supplementary angles sum to 180°. 180 − 52 = 128°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 52 = 128°."]},{"id":216,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/8 + 4/8.","கூட்டிச் சுருக்குக: 2/8 + 4/8."],"options":[["9/8","9/8"],["3/4","3/4"],["1","1"],["7/8","7/8"]],"answer":1,"explanation":["(2 + 4)/8 = 6/8 = 3/4.","(2 + 4)/8 = 6/8 = 3/4."]},{"id":217,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 12 red and 6 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 12 சிவப்பு, 6 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["7/10","7/10"],["5/7","5/7"],["2/3","2/3"],["13/19","13/19"]],"answer":2,"explanation":["Favourable outcomes / total = 12/18 = 2/3.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 12/18 = 2/3."]},{"id":218,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 15% of 200.","200 இல் 15% காண்க."],"options":[["29","29"],["40","40"],["30","30"],["33","33"]],"answer":2,"explanation":["200 × 15 / 100 = 30.","200 × 15 / 100 = 30."]},{"id":219,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹800. Find the price after a 25% discount, in rupees.","குறித்த விலை ₹800. 25% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["600","600"],["601","601"],["610","610"],["1200","1200"]],"answer":0,"explanation":["Discount = ₹200. Pay 800 − 200 = ₹600.","தள்ளுபடி = ₹200. செலுத்துவது 800 − 200 = ₹600."]},{"id":220,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Blood vessels that carry blood away from the heart.","கண்டறிக: இதயத்திலிருந்து இரத்தத்தை வெளியே எடுத்துச் செல்லும் இரத்தக் குழாய்கள்."],"options":[["Arteries","தமனிகள்"],["Ribosome","ரைபோசோம்"],["Joule","ஜூல்"],["Mitochondrion","மைட்டோகாண்ட்ரியா"]],"answer":0,"explanation":["Arteries: Blood vessels that carry blood away from the heart.","தமனிகள்: இதயத்திலிருந்து இரத்தத்தை வெளியே எடுத்துச் செல்லும் இரத்தக் குழாய்கள்."]},{"id":221,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Blood vessels that carry blood towards the heart.","கண்டறிக: இதயத்தை நோக்கி இரத்தத்தை எடுத்துச் செல்லும் இரத்தக் குழாய்கள்."],"options":[["Chloroplast","பசுங்கணிகம்"],["Watt","வாட்"],["Sublimation","பதங்கமாதல்"],["Veins","சிரைகள்"]],"answer":3,"explanation":["Veins: Blood vessels that carry blood towards the heart.","சிரைகள்: இதயத்தை நோக்கி இரத்தத்தை எடுத்துச் செல்லும் இரத்தக் குழாய்கள்."]},{"id":222,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Tiny air sacs in lungs where gas exchange occurs.","கண்டறிக: நுரையீரலில் வாயுப் பரிமாற்றம் நடைபெறும் சிறிய காற்றுப் பைகள்."],"options":[["Alveoli","காற்று நுண்ணறைகள்"],["Enamel","பற்சிப்பி"],["Filtration","வடிகட்டுதல்"],["White blood cells","வெள்ளையணுக்கள்"]],"answer":0,"explanation":["Alveoli: Tiny air sacs in lungs where gas exchange occurs.","காற்று நுண்ணறைகள்: நுரையீரலில் வாயுப் பரிமாற்றம் நடைபெறும் சிறிய காற்றுப் பைகள்."]},{"id":223,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The atmospheric conditions at a place over a short period.","கண்டறிக: ஓர் இடத்தில் குறுகிய காலத்தில் நிலவும் வளிமண்டல நிலை."],"options":[["Weather","வானிலை"],["Equator","நிலநடுக்கோடு"],["Erosion","அரித்தல்"],["Deposition","படிதல்"]],"answer":0,"explanation":["Weather: The atmospheric conditions at a place over a short period.","வானிலை: ஓர் இடத்தில் குறுகிய காலத்தில் நிலவும் வளிமண்டல நிலை."]},{"id":224,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The long-term pattern of weather in a region.","கண்டறிக: ஒரு பகுதியில் நீண்ட காலமாக நிலவும் வானிலையின் அமைப்பு."],"options":[["Isthmus","நிலச்சந்தி"],["Climate","காலநிலை"],["Revolution","சுற்றிவருதல்"],["Erosion","அரித்தல்"]],"answer":1,"explanation":["Climate: The long-term pattern of weather in a region.","காலநிலை: ஒரு பகுதியில் நீண்ட காலமாக நிலவும் வானிலையின் அமைப்பு."]},{"id":225,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in HOME.","A = 1, B = 2, …, Z = 26 எனில், HOME என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["51","51"],["41","41"],["43","43"],["44","44"]],"answer":1,"explanation":["8 + 15 + 13 + 5 = 41.","8 + 15 + 13 + 5 = 41."]},{"id":226,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Tuesday. What day will it be after 11 days?","இன்று செவ்வாய். 11 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Monday","திங்கள்"],["Tuesday","செவ்வாய்"],["Saturday","சனி"],["Sunday","ஞாயிறு"]],"answer":2,"explanation":["11 ÷ 7 leaves remainder 4. Move 4 days from Tuesday: Saturday.","11 ஐ 7 ஆல் வகுக்க மீதி 4. செவ்வாய் கிழமையிலிருந்து 4 நாட்கள் நகர்ந்தால் சனி."]},{"id":227,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 24 students shakes hands once with every other student. How many handshakes occur?","24 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["279","279"],["276","276"],["278","278"],["552","552"]],"answer":1,"explanation":["Each pair is counted once: 24 × 23 ÷ 2 = 276.","ஒவ்வொரு இணையும் ஒருமுறை: 24 × 23 ÷ 2 = 276."]},{"id":228,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 25 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 25 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["76","76"],["75","75"],["86","86"],["152","152"]],"answer":0,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 24 = 76.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 24 = 76."]},{"id":229,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 9, 13, 18, 24, 31, ?","நிறைவு செய்க: 9, 13, 18, 24, 31, ?"],"options":[["42","42"],["44","44"],["39","39"],["78","78"]],"answer":2,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 39.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 39."]},{"id":230,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 7, 10, 17, 27, 44, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 7, 10, 17, 27, 44, ?"],"options":[["76","76"],["70","70"],["71","71"],["142","142"]],"answer":2,"explanation":["27 + 44 = 71.","27 + 44 = 71."]},{"id":231,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 11, 20, 29, 38, 47, …","அடுத்த எண்ணைக் காண்க: 11, 20, 29, 38, 47, …"],"options":[["61","61"],["56","56"],["58","58"],["66","66"]],"answer":1,"explanation":["Add 9 each time. 47 + 9 = 56.","ஒவ்வொரு முறையும் 9 கூட்டுக. 47 + 9 = 56."]},{"id":232,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 35, 70, 140, 280, ?","தொடரை நிறைவு செய்க: 35, 70, 140, 280, ?"],"options":[["562","562"],["561","561"],["563","563"],["560","560"]],"answer":3,"explanation":["Double each term: 280 × 2 = 560.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 280 × 2 = 560."]},{"id":233,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 3, 14, 36, 80, ?","அடுத்த உறுப்பைக் காண்க: 3, 14, 36, 80, ?"],"options":[["336","336"],["170","170"],["178","178"],["168","168"]],"answer":3,"explanation":["Multiply by 2, then add 8: 80 × 2 + 8 = 168.","2 ஆல் பெருக்கி 8 கூட்டுக: 80 × 2 + 8 = 168."]},{"id":234,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 35, 41, ?, 53, 59","விடுபட்ட எண்ணைக் காண்க: 35, 41, ?, 53, 59"],"options":[["46","46"],["49","49"],["47","47"],["57","57"]],"answer":2,"explanation":["The common difference is 6. 41 + 6 = 47.","பொது வித்தியாசம் 6. 41 + 6 = 47."]},{"id":235,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 1089, 1156, 1225, 1296, ?","தொடர்க: 1089, 1156, 1225, 1296, ?"],"options":[["1369","1369"],["1374","1374"],["1372","1372"],["2738","2738"]],"answer":0,"explanation":["These are squares of 33, 34, 35, 36. Next: 37² = 1369.","இவை 33, 34, 35, 36 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 37² = 1369."]},{"id":236,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 22 from the front and position 23 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 22 ஆவது, பின்னிருந்து 23 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["88","88"],["49","49"],["44","44"],["54","54"]],"answer":2,"explanation":["Total = 22 + 23 − 1 = 44; the student is counted only once.","மொத்தம் = 22 + 23 − 1 = 44; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":237,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹1500 at 9% per year for 5 years.","₹1500 க்கு ஆண்டுக்கு 9% வீதம் 5 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["678","678"],["674","674"],["685","685"],["675","675"]],"answer":3,"explanation":["PRT/100 = 1500 × 9 × 5 / 100 = ₹675.","PRT/100 = 1500 × 9 × 5 / 100 = ₹675."]},{"id":238,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 8x + 7 = 135.","x காண்க: 8x + 7 = 135."],"options":[["17","17"],["32","32"],["21","21"],["16","16"]],"answer":3,"explanation":["x = (135 − 7) ÷ 8 = 16.","x = (135 − 7) ÷ 8 = 16."]},{"id":239,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 12 cm long and 9 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 12 செ.மீ, அகலம் 9 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["108","108"],["118","118"],["107","107"],["110","110"]],"answer":0,"explanation":["Area = length × width = 12 × 9 = 108 cm².","பரப்பளவு = நீளம் × அகலம் = 12 × 9 = 108 ச.செ.மீ."]},{"id":240,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 25 m and 3 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 25 மீ மற்றும் 3 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["57","57"],["56","56"],["112","112"],["55","55"]],"answer":1,"explanation":["Perimeter = 2(25 + 3) = 56 m.","சுற்றளவு = 2(25 + 3) = 56 மீ."]},{"id":241,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 60 cm and height 11 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 60 செ.மீ, உயரம் 11 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["335","335"],["330","330"],["331","331"],["333","333"]],"answer":1,"explanation":["Area = ½ × 60 × 11 = 330 cm².","பரப்பளவு = ½ × 60 × 11 = 330 ச.செ.மீ."]},{"id":242,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 38 cm × 18 cm × 11 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 38 செ.மீ × 18 செ.மீ × 11 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["7524","7524"],["7526","7526"],["7527","7527"],["7529","7529"]],"answer":0,"explanation":["Volume = length × breadth × height = 38 × 18 × 11 = 7524 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 38 × 18 × 11 = 7524 க.செ.மீ."]},{"id":243,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 34, 37, 40, 43, 46.","34, 37, 40, 43, 46 ஆகியவற்றின் சராசரி காண்க."],"options":[["41","41"],["39","39"],["40","40"],["45","45"]],"answer":2,"explanation":["Sum ÷ count = 200 ÷ 5 = 40.","கூடுதல் ÷ எண்ணிக்கை = 200 ÷ 5 = 40."]},{"id":244,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 840 km in 15 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 15 மணி நேரத்தில் 840 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["56","56"],["57","57"],["112","112"],["61","61"]],"answer":0,"explanation":["Speed = distance ÷ time = 840 ÷ 15 = 56 km/h.","வேகம் = தொலைவு ÷ நேரம் = 840 ÷ 15 = 56 கி.மீ/மணி."]},{"id":245,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The main site of absorption of digested nutrients in humans.","கண்டறிக: மனிதரில் செரிக்கப்பட்ட ஊட்டச்சத்துகள் உறிஞ்சப்படும் முக்கிய இடம்."],"options":[["Small intestine","சிறுகுடல்"],["Xylem","சைலம்"],["Solute","கரைபொருள்"],["Vacuole","நுண்குமிழ்"]],"answer":0,"explanation":["Small intestine: The main site of absorption of digested nutrients in humans.","சிறுகுடல்: மனிதரில் செரிக்கப்பட்ட ஊட்டச்சத்துகள் உறிஞ்சப்படும் முக்கிய இடம்."]},{"id":246,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Organs that filter blood and form urine.","கண்டறிக: இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்."],"options":[["Vitamin D","வைட்டமின் D"],["Kidneys","சிறுநீரகங்கள்"],["Stomata","இலைத்துளைகள்"],["Xylem","சைலம்"]],"answer":1,"explanation":["Kidneys: Organs that filter blood and form urine.","சிறுநீரகங்கள்: இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்."]},{"id":247,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The hard outer covering of the crown of a tooth.","கண்டறிக: பல்லின் மகுடப்பகுதியை மூடியுள்ள கடினமான வெளிப்புறப் படலம்."],"options":[["Watt","வாட்"],["Sublimation","பதங்கமாதல்"],["Germination","முளைத்தல்"],["Enamel","பற்சிப்பி"]],"answer":3,"explanation":["Enamel: The hard outer covering of the crown of a tooth.","பற்சிப்பி: பல்லின் மகுடப்பகுதியை மூடியுள்ள கடினமான வெளிப்புறப் படலம்."]},{"id":248,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: An instrument used to measure rainfall.","கண்டறிக: மழையளவை அளக்கப் பயன்படும் கருவி."],"options":[["Plateau","பீடபூமி"],["Rain gauge","மழைமானி"],["Tributary","துணையாறு"],["Equator","நிலநடுக்கோடு"]],"answer":1,"explanation":["Rain gauge: An instrument used to measure rainfall.","மழைமானி: மழையளவை அளக்கப் பயன்படும் கருவி."]},{"id":249,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: An instrument used to measure atmospheric pressure.","கண்டறிக: வளிமண்டல அழுத்தத்தை அளக்கப் பயன்படும் கருவி."],"options":[["Rajaraja I","முதலாம் இராஜராஜன்"],["Barometer","காற்றழுத்தமானி"],["Strait","நீர்ச்சந்தி"],["Sedimentary rock","படிவுப்பாறை"]],"answer":1,"explanation":["Barometer: An instrument used to measure atmospheric pressure.","காற்றழுத்தமானி: வளிமண்டல அழுத்தத்தை அளக்கப் பயன்படும் கருவி."]},{"id":250,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 16 students, a student is in position 6 from the front. Find the position from the back.","16 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 6 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["22","22"],["11","11"],["10","10"],["14","14"]],"answer":1,"explanation":["Position from back = 16 − 6 + 1 = 11.","பின்னிருந்து இடம் = 16 − 6 + 1 = 11."]},{"id":251,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 43 m north, 13 m east, 8 m south and 13 m west. How far are you from the start, in metres?","43 மீ வடக்கு, 13 மீ கிழக்கு, 8 மீ தெற்கு, 13 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["35","35"],["70","70"],["45","45"],["34","34"]],"answer":0,"explanation":["East and west cancel. Net northward distance = 43 − 8 = 35 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 43 − 8 = 35 மீ."]},{"id":252,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 21 km east and then 28 km north. Find the straight-line distance from the start in km.","21 கி.மீ கிழக்கிலும் பின்னர் 28 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["45","45"],["35","35"],["34","34"],["38","38"]],"answer":1,"explanation":["Pythagoras: √(21² + 28²) = 35 km.","பிதாகரஸ் தேற்றம்: √(21² + 28²) = 35 கி.மீ."]},{"id":253,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 6 → 42, then 25 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 6 → 42 எனில் 25 → ?"],"options":[["655","655"],["650","650"],["653","653"],["651","651"]],"answer":1,"explanation":["25 × (25 + 1) = 650.","25 × (25 + 1) = 650."]},{"id":254,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 6 : 216 :: 10 : ?","மும்மடி விதியைப் பயன்படுத்துக: 6 : 216 :: 10 : ?"],"options":[["999","999"],["2000","2000"],["1005","1005"],["1000","1000"]],"answer":3,"explanation":["6³ = 216, so 10³ = 1000.","6³ = 216; எனவே 10³ = 1000."]},{"id":255,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 4 places forward in the alphabet (wrap Z to A). Code GAME.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 4 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). GAME இன் குறியீடு என்ன?"],"options":[["LFRJ","LFRJ"],["JDPH","JDPH"],["MGSK","MGSK"],["KEQI","KEQI"]],"answer":3,"explanation":["Each letter advances by 4: G → K, A → E, M → Q, E → I","ஒவ்வோர் எழுத்தும் 4 இடங்கள் முன்னேறும்: G → K, A → E, M → Q, E → I"]},{"id":256,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in RAIN.","A = 1, B = 2, …, Z = 26 எனில், RAIN என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["84","84"],["41","41"],["42","42"],["47","47"]],"answer":2,"explanation":["18 + 1 + 9 + 14 = 42.","18 + 1 + 9 + 14 = 42."]},{"id":257,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Tuesday. What day will it be after 63 days?","இன்று செவ்வாய். 63 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Thursday","வியாழன்"],["Wednesday","புதன்"],["Friday","வெள்ளி"],["Tuesday","செவ்வாய்"]],"answer":3,"explanation":["63 ÷ 7 leaves remainder 0. Move 0 days from Tuesday: Tuesday.","63 ஐ 7 ஆல் வகுக்க மீதி 0. செவ்வாய் கிழமையிலிருந்து 0 நாட்கள் நகர்ந்தால் செவ்வாய்."]},{"id":258,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 14 students shakes hands once with every other student. How many handshakes occur?","14 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["92","92"],["101","101"],["91","91"],["182","182"]],"answer":2,"explanation":["Each pair is counted once: 14 × 13 ÷ 2 = 91.","ஒவ்வொரு இணையும் ஒருமுறை: 14 × 13 ÷ 2 = 91."]},{"id":259,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 10 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 10 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["31","31"],["30","30"],["36","36"],["62","62"]],"answer":0,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 9 = 31.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 9 = 31."]},{"id":260,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 7, 9, 12, 16, 21, ?","நிறைவு செய்க: 7, 9, 12, 16, 21, ?"],"options":[["27","27"],["32","32"],["30","30"],["29","29"]],"answer":0,"explanation":["Differences increase by 1: 2, 3, 4, 5, 6. Next = 27.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 2, 3, 4, 5, 6. அடுத்த எண் 27."]},{"id":261,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 35, 40, 75, 115, 190, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 35, 40, 75, 115, 190, ?"],"options":[["308","308"],["305","305"],["610","610"],["307","307"]],"answer":1,"explanation":["115 + 190 = 305.","115 + 190 = 305."]},{"id":262,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 544 in the ratio 8 : 9. Find the smaller share.","544 ஐ 8 : 9 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["512","512"],["256","256"],["259","259"],["255","255"]],"answer":1,"explanation":["Smaller share = 544 × 8/(8+9) = 256.","சிறிய பங்கு = 544 × 8/(8+9) = 256."]},{"id":263,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 38 and 46.","38 மற்றும் 46 இன் மீ.பொ.வ. காண்க."],"options":[["4","4"],["7","7"],["3","3"],["2","2"]],"answer":3,"explanation":["Common factors: 1, 2. Greatest = 2.","பொதுக் காரணிகள்: 1, 2. மிகப்பெரியது 2."]},{"id":264,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 37 and 10.","37 மற்றும் 10 இன் மீ.பொ.ம. காண்க."],"options":[["740","740"],["370","370"],["369","369"],["371","371"]],"answer":1,"explanation":["LCM = product ÷ HCF = 370 ÷ 1 = 370.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 370 ÷ 1 = 370."]},{"id":265,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹2900 is sold for ₹3190. Find the profit percentage.","₹2900 க்கு வாங்கிய பொருள் ₹3190 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["9","9"],["10","10"],["20","20"],["12","12"]],"answer":1,"explanation":["Profit = ₹290. Profit% = 290 × 100 / 2900 = 10%.","இலாபம் = ₹290. இலாப% = 290 × 100 / 2900 = 10%."]},{"id":266,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 75° and 34°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 75°, 34°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["71","71"],["72","72"],["73","73"],["70","70"]],"answer":0,"explanation":["180 − 75 − 34 = 71°.","180 − 75 − 34 = 71°."]},{"id":267,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 17°, in degrees.","17° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["166","166"],["163","163"],["326","326"],["164","164"]],"answer":1,"explanation":["Supplementary angles sum to 180°. 180 − 17 = 163°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 17 = 163°."]},{"id":268,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 15/17 + 11/17.","கூட்டிச் சுருக்குக: 15/17 + 11/17."],"options":[["29/17","29/17"],["26/17","26/17"],["27/17","27/17"],["28/17","28/17"]],"answer":1,"explanation":["(15 + 11)/17 = 26/17 = 26/17.","(15 + 11)/17 = 26/17 = 26/17."]},{"id":269,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 10 red and 12 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 10 சிவப்பு, 12 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["13/25","13/25"],["1/2","1/2"],["11/23","11/23"],["5/11","5/11"]],"answer":3,"explanation":["Favourable outcomes / total = 10/22 = 5/11.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 10/22 = 5/11."]},{"id":270,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The vitamin whose deficiency causes scurvy.","கண்டறிக: குறைபாட்டால் ஸ்கர்வி நோயை ஏற்படுத்தும் வைட்டமின்."],"options":[["Inertia","நிலைமம்"],["Solute","கரைபொருள்"],["Vitamin C","வைட்டமின் C"],["Stomata","இலைத்துளைகள்"]],"answer":2,"explanation":["Vitamin C: The vitamin whose deficiency causes scurvy.","வைட்டமின் C: குறைபாட்டால் ஸ்கர்வி நோயை ஏற்படுத்தும் வைட்டமின்."]},{"id":271,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The vitamin whose deficiency can cause rickets in children.","கண்டறிக: குழந்தைகளில் குறைபாட்டால் ரிக்கெட்ஸ் ஏற்படக்கூடிய வைட்டமின்."],"options":[["Vitamin D","வைட்டமின் D"],["Watt","வாட்"],["Chlorophyll","பச்சையம்"],["Newton","நியூட்டன்"]],"answer":0,"explanation":["Vitamin D: The vitamin whose deficiency can cause rickets in children.","வைட்டமின் D: குழந்தைகளில் குறைபாட்டால் ரிக்கெட்ஸ் ஏற்படக்கூடிய வைட்டமின்."]},{"id":272,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The vitamin whose deficiency can cause night blindness.","கண்டறிக: குறைபாட்டால் மாலைக்கண் நோய் ஏற்படக்கூடிய வைட்டமின்."],"options":[["Stomata","இலைத்துளைகள்"],["Neutralisation","நடுநிலையாக்கல்"],["Refraction","ஒளிவிலகல்"],["Vitamin A","வைட்டமின் A"]],"answer":3,"explanation":["Vitamin A: The vitamin whose deficiency can cause night blindness.","வைட்டமின் A: குறைபாட்டால் மாலைக்கண் நோய் ஏற்படக்கூடிய வைட்டமின்."]},{"id":273,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: An instrument used to measure wind speed.","கண்டறிக: காற்றின் வேகத்தை அளக்கப் பயன்படும் கருவி."],"options":[["Rotation","தற்சுழற்சி"],["Anemometer","காற்று வேகமானி"],["Tropic of Cancer","கடகரேகை"],["Asia","ஆசியா"]],"answer":1,"explanation":["Anemometer: An instrument used to measure wind speed.","காற்று வேகமானி: காற்றின் வேகத்தை அளக்கப் பயன்படும் கருவி."]},{"id":274,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: An instrument used to show wind direction.","கண்டறிக: காற்று வீசும் திசையைக் காட்டும் கருவி."],"options":[["Subhas Chandra Bose","சுபாஷ் சந்திர போஸ்"],["Rajendra I","முதலாம் இராஜேந்திரன்"],["Wind vane","காற்றுத்திசை காட்டி"],["Tributary","துணையாறு"]],"answer":2,"explanation":["Wind vane: An instrument used to show wind direction.","காற்றுத்திசை காட்டி: காற்று வீசும் திசையைக் காட்டும் கருவி."]},{"id":275,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 23, 30, 37, 44, 51, …","அடுத்த எண்ணைக் காண்க: 23, 30, 37, 44, 51, …"],"options":[["58","58"],["68","68"],["57","57"],["59","59"]],"answer":0,"explanation":["Add 7 each time. 51 + 7 = 58.","ஒவ்வொரு முறையும் 7 கூட்டுக. 51 + 7 = 58."]},{"id":276,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 28, 56, 112, 224, ?","தொடரை நிறைவு செய்க: 28, 56, 112, 224, ?"],"options":[["450","450"],["447","447"],["451","451"],["448","448"]],"answer":3,"explanation":["Double each term: 224 × 2 = 448.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 224 × 2 = 448."]},{"id":277,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 14, 35, 77, 161, ?","அடுத்த உறுப்பைக் காண்க: 14, 35, 77, 161, ?"],"options":[["332","332"],["328","328"],["329","329"],["330","330"]],"answer":2,"explanation":["Multiply by 2, then add 7: 161 × 2 + 7 = 329.","2 ஆல் பெருக்கி 7 கூட்டுக: 161 × 2 + 7 = 329."]},{"id":278,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 10, 19, ?, 37, 46","விடுபட்ட எண்ணைக் காண்க: 10, 19, ?, 37, 46"],"options":[["28","28"],["29","29"],["56","56"],["27","27"]],"answer":0,"explanation":["The common difference is 9. 19 + 9 = 28.","பொது வித்தியாசம் 9. 19 + 9 = 28."]},{"id":279,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 196, 225, 256, 289, ?","தொடர்க: 196, 225, 256, 289, ?"],"options":[["326","326"],["325","325"],["324","324"],["334","334"]],"answer":2,"explanation":["These are squares of 14, 15, 16, 17. Next: 18² = 324.","இவை 14, 15, 16, 17 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 18² = 324."]},{"id":280,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 26 from the front and position 14 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 26 ஆவது, பின்னிருந்து 14 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["40","40"],["44","44"],["39","39"],["49","49"]],"answer":2,"explanation":["Total = 26 + 14 − 1 = 39; the student is counted only once.","மொத்தம் = 26 + 14 − 1 = 39; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":281,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 45 students, a student is in position 13 from the front. Find the position from the back.","45 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 13 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["38","38"],["66","66"],["33","33"],["34","34"]],"answer":2,"explanation":["Position from back = 45 − 13 + 1 = 33.","பின்னிருந்து இடம் = 45 − 13 + 1 = 33."]},{"id":282,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 8 m north, 23 m east, 2 m south and 23 m west. How far are you from the start, in metres?","8 மீ வடக்கு, 23 மீ கிழக்கு, 2 மீ தெற்கு, 23 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["5","5"],["6","6"],["8","8"],["16","16"]],"answer":1,"explanation":["East and west cancel. Net northward distance = 8 − 2 = 6 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 8 − 2 = 6 மீ."]},{"id":283,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 12 km east and then 16 km north. Find the straight-line distance from the start in km.","12 கி.மீ கிழக்கிலும் பின்னர் 16 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["20","20"],["22","22"],["23","23"],["19","19"]],"answer":0,"explanation":["Pythagoras: √(12² + 16²) = 20 km.","பிதாகரஸ் தேற்றம்: √(12² + 16²) = 20 கி.மீ."]},{"id":284,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 11 → 132, then 30 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 11 → 132 எனில் 30 → ?"],"options":[["933","933"],["930","930"],["940","940"],["935","935"]],"answer":1,"explanation":["30 × (30 + 1) = 930.","30 × (30 + 1) = 930."]},{"id":285,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 8 : 512 :: 12 : ?","மும்மடி விதியைப் பயன்படுத்துக: 8 : 512 :: 12 : ?"],"options":[["1731","1731"],["1728","1728"],["1729","1729"],["1738","1738"]],"answer":1,"explanation":["8³ = 512, so 12³ = 1728.","8³ = 512; எனவே 12³ = 1728."]},{"id":286,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 2 places forward in the alphabet (wrap Z to A). Code STAR.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 2 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). STAR இன் குறியீடு என்ன?"],"options":[["UVCT","UVCT"],["TUBS","TUBS"],["WXEV","WXEV"],["VWDU","VWDU"]],"answer":0,"explanation":["Each letter advances by 2: S → U, T → V, A → C, R → T","ஒவ்வோர் எழுத்தும் 2 இடங்கள் முன்னேறும்: S → U, T → V, A → C, R → T"]},{"id":287,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 20% of 200.","200 இல் 20% காண்க."],"options":[["40","40"],["39","39"],["43","43"],["42","42"]],"answer":0,"explanation":["200 × 20 / 100 = 40.","200 × 20 / 100 = 40."]},{"id":288,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹2300. Find the price after a 5% discount, in rupees.","குறித்த விலை ₹2300. 5% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["2186","2186"],["4370","4370"],["2195","2195"],["2185","2185"]],"answer":3,"explanation":["Discount = ₹115. Pay 2300 − 115 = ₹2185.","தள்ளுபடி = ₹115. செலுத்துவது 2300 − 115 = ₹2185."]},{"id":289,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2300 at 8% per year for 3 years.","₹2300 க்கு ஆண்டுக்கு 8% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1104","1104"],["552","552"],["555","555"],["562","562"]],"answer":1,"explanation":["PRT/100 = 2300 × 8 × 3 / 100 = ₹552.","PRT/100 = 2300 × 8 × 3 / 100 = ₹552."]},{"id":290,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 7x + 39 = 144.","x காண்க: 7x + 39 = 144."],"options":[["15","15"],["18","18"],["20","20"],["25","25"]],"answer":0,"explanation":["x = (144 − 39) ÷ 7 = 15.","x = (144 − 39) ÷ 7 = 15."]},{"id":291,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 15 cm long and 10 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 15 செ.மீ, அகலம் 10 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["153","153"],["150","150"],["149","149"],["151","151"]],"answer":1,"explanation":["Area = length × width = 15 × 10 = 150 cm².","பரப்பளவு = நீளம் × அகலம் = 15 × 10 = 150 ச.செ.மீ."]},{"id":292,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 32 m and 6 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 32 மீ மற்றும் 6 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["76","76"],["152","152"],["79","79"],["75","75"]],"answer":0,"explanation":["Perimeter = 2(32 + 6) = 76 m.","சுற்றளவு = 2(32 + 6) = 76 மீ."]},{"id":293,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 34 cm and height 5 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 34 செ.மீ, உயரம் 5 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["95","95"],["87","87"],["85","85"],["170","170"]],"answer":2,"explanation":["Area = ½ × 34 × 5 = 85 cm².","பரப்பளவு = ½ × 34 × 5 = 85 ச.செ.மீ."]},{"id":294,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 40 cm × 14 cm × 3 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 40 செ.மீ × 14 செ.மீ × 3 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["1680","1680"],["1683","1683"],["1681","1681"],["1685","1685"]],"answer":0,"explanation":["Volume = length × breadth × height = 40 × 14 × 3 = 1680 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 40 × 14 × 3 = 1680 க.செ.மீ."]},{"id":295,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The mineral essential for haemoglobin formation.","கண்டறிக: ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது."],"options":[["Melting","உருகுதல்"],["Iron","இரும்பு"],["Freezing","உறைதல்"],["Transpiration","நீராவிப்போக்கு"]],"answer":1,"explanation":["Iron: The mineral essential for haemoglobin formation.","இரும்பு: ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது."]},{"id":296,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The mineral required to make thyroid hormones.","கண்டறிக: தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது."],"options":[["Filtration","வடிகட்டுதல்"],["Vitamin A","வைட்டமின் A"],["Iodine","அயோடின்"],["Freezing","உறைதல்"]],"answer":2,"explanation":["Iodine: The mineral required to make thyroid hormones.","அயோடின்: தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது."]},{"id":297,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI unit of force.","கண்டறிக: விசையின் SI அலகு."],"options":[["Xylem","சைலம்"],["Pascal","பாஸ்கல்"],["Cell wall","செல்சுவர்"],["Newton","நியூட்டன்"]],"answer":3,"explanation":["Newton: The SI unit of force.","நியூட்டன்: விசையின் SI அலகு."]},{"id":298,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Rock formed by cooling and solidification of magma or lava.","கண்டறிக: மாக்மா அல்லது லாவா குளிர்ந்து இறுகுவதால் உருவாகும் பாறை."],"options":[["Igneous rock","தீப்பாறை"],["Mahatma Gandhi","மகாத்மா காந்தி"],["Equator","நிலநடுக்கோடு"],["Asia","ஆசியா"]],"answer":0,"explanation":["Igneous rock: Rock formed by cooling and solidification of magma or lava.","தீப்பாறை: மாக்மா அல்லது லாவா குளிர்ந்து இறுகுவதால் உருவாகும் பாறை."]},{"id":299,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Rock formed from accumulated sediments.","கண்டறிக: சேர்ந்த படிவுகளிலிருந்து உருவாகும் பாறை."],"options":[["Wind vane","காற்றுத்திசை காட்டி"],["Australia","ஆஸ்திரேலியா"],["Sedimentary rock","படிவுப்பாறை"],["Arctic Ocean","ஆர்க்டிக் பெருங்கடல்"]],"answer":2,"explanation":["Sedimentary rock: Rock formed from accumulated sediments.","படிவுப்பாறை: சேர்ந்த படிவுகளிலிருந்து உருவாகும் பாறை."]},{"id":300,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in TREE.","A = 1, B = 2, …, Z = 26 எனில், TREE என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["51","51"],["53","53"],["58","58"],["48","48"]],"answer":3,"explanation":["20 + 18 + 5 + 5 = 48.","20 + 18 + 5 + 5 = 48."]},{"id":301,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Saturday. What day will it be after 42 days?","இன்று சனி. 42 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Tuesday","செவ்வாய்"],["Saturday","சனி"],["Monday","திங்கள்"],["Sunday","ஞாயிறு"]],"answer":1,"explanation":["42 ÷ 7 leaves remainder 0. Move 0 days from Saturday: Saturday.","42 ஐ 7 ஆல் வகுக்க மீதி 0. சனி கிழமையிலிருந்து 0 நாட்கள் நகர்ந்தால் சனி."]},{"id":302,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 17 students shakes hands once with every other student. How many handshakes occur?","17 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["138","138"],["141","141"],["137","137"],["136","136"]],"answer":3,"explanation":["Each pair is counted once: 17 × 16 ÷ 2 = 136.","ஒவ்வொரு இணையும் ஒருமுறை: 17 × 16 ÷ 2 = 136."]},{"id":303,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 11 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 11 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["36","36"],["34","34"],["68","68"],["37","37"]],"answer":1,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 10 = 34.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 10 = 34."]},{"id":304,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 11, 13, 16, 20, 25, ?","நிறைவு செய்க: 11, 13, 16, 20, 25, ?"],"options":[["31","31"],["41","41"],["62","62"],["30","30"]],"answer":0,"explanation":["Differences increase by 1: 2, 3, 4, 5, 6. Next = 31.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 2, 3, 4, 5, 6. அடுத்த எண் 31."]},{"id":305,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 24, 27, 51, 78, 129, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 24, 27, 51, 78, 129, ?"],"options":[["414","414"],["209","209"],["212","212"],["207","207"]],"answer":3,"explanation":["78 + 129 = 207.","78 + 129 = 207."]},{"id":306,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 18, 26, 34, 42, 50, …","அடுத்த எண்ணைக் காண்க: 18, 26, 34, 42, 50, …"],"options":[["57","57"],["59","59"],["63","63"],["58","58"]],"answer":3,"explanation":["Add 8 each time. 50 + 8 = 58.","ஒவ்வொரு முறையும் 8 கூட்டுக. 50 + 8 = 58."]},{"id":307,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 15, 30, 60, 120, ?","தொடரை நிறைவு செய்க: 15, 30, 60, 120, ?"],"options":[["240","240"],["245","245"],["480","480"],["239","239"]],"answer":0,"explanation":["Double each term: 120 × 2 = 240.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 120 × 2 = 240."]},{"id":308,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 3, 12, 30, 66, ?","அடுத்த உறுப்பைக் காண்க: 3, 12, 30, 66, ?"],"options":[["139","139"],["143","143"],["276","276"],["138","138"]],"answer":3,"explanation":["Multiply by 2, then add 6: 66 × 2 + 6 = 138.","2 ஆல் பெருக்கி 6 கூட்டுக: 66 × 2 + 6 = 138."]},{"id":309,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 24, 32, ?, 48, 56","விடுபட்ட எண்ணைக் காண்க: 24, 32, ?, 48, 56"],"options":[["80","80"],["43","43"],["40","40"],["42","42"]],"answer":2,"explanation":["The common difference is 8. 32 + 8 = 40.","பொது வித்தியாசம் 8. 32 + 8 = 40."]},{"id":310,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 729, 784, 841, 900, ?","தொடர்க: 729, 784, 841, 900, ?"],"options":[["1922","1922"],["971","971"],["961","961"],["964","964"]],"answer":2,"explanation":["These are squares of 27, 28, 29, 30. Next: 31² = 961.","இவை 27, 28, 29, 30 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 31² = 961."]},{"id":311,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 15 from the front and position 6 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 15 ஆவது, பின்னிருந்து 6 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["20","20"],["21","21"],["23","23"],["19","19"]],"answer":0,"explanation":["Total = 15 + 6 − 1 = 20; the student is counted only once.","மொத்தம் = 15 + 6 − 1 = 20; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":312,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 29, 42, 55, 68, 81.","29, 42, 55, 68, 81 ஆகியவற்றின் சராசரி காண்க."],"options":[["60","60"],["54","54"],["57","57"],["55","55"]],"answer":3,"explanation":["Sum ÷ count = 275 ÷ 5 = 55.","கூடுதல் ÷ எண்ணிக்கை = 275 ÷ 5 = 55."]},{"id":313,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 666 km in 18 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 18 மணி நேரத்தில் 666 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["36","36"],["39","39"],["40","40"],["37","37"]],"answer":3,"explanation":["Speed = distance ÷ time = 666 ÷ 18 = 37 km/h.","வேகம் = தொலைவு ÷ நேரம் = 666 ÷ 18 = 37 கி.மீ/மணி."]},{"id":314,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 420 in the ratio 3 : 9. Find the smaller share.","420 ஐ 3 : 9 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["210","210"],["107","107"],["105","105"],["115","115"]],"answer":2,"explanation":["Smaller share = 420 × 3/(3+9) = 105.","சிறிய பங்கு = 420 × 3/(3+9) = 105."]},{"id":315,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 34 and 40.","34 மற்றும் 40 இன் மீ.பொ.வ. காண்க."],"options":[["7","7"],["4","4"],["2","2"],["3","3"]],"answer":2,"explanation":["Common factors: 1, 2. Greatest = 2.","பொதுக் காரணிகள்: 1, 2. மிகப்பெரியது 2."]},{"id":316,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 20 and 8.","20 மற்றும் 8 இன் மீ.பொ.ம. காண்க."],"options":[["80","80"],["50","50"],["41","41"],["40","40"]],"answer":3,"explanation":["LCM = product ÷ HCF = 160 ÷ 4 = 40.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 160 ÷ 4 = 40."]},{"id":317,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1000 is sold for ₹1100. Find the profit percentage.","₹1000 க்கு வாங்கிய பொருள் ₹1100 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["9","9"],["10","10"],["11","11"],["15","15"]],"answer":1,"explanation":["Profit = ₹100. Profit% = 100 × 100 / 1000 = 10%.","இலாபம் = ₹100. இலாப% = 100 × 100 / 1000 = 10%."]},{"id":318,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 61° and 63°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 61°, 63°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["56","56"],["112","112"],["66","66"],["55","55"]],"answer":0,"explanation":["180 − 61 − 63 = 56°.","180 − 61 − 63 = 56°."]},{"id":319,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 38°, in degrees.","38° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["145","145"],["147","147"],["142","142"],["152","152"]],"answer":2,"explanation":["Supplementary angles sum to 180°. 180 − 38 = 142°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 38 = 142°."]},{"id":320,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI unit of energy.","கண்டறிக: ஆற்றலின் SI அலகு."],"options":[["Distillation","காய்ச்சி வடித்தல்"],["Friction","உராய்வு"],["Joule","ஜூல்"],["White blood cells","வெள்ளையணுக்கள்"]],"answer":2,"explanation":["Joule: The SI unit of energy.","ஜூல்: ஆற்றலின் SI அலகு."]},{"id":321,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI unit of power.","கண்டறிக: திறனின் SI அலகு."],"options":[["Condensation","ஆவி சுருங்குதல்"],["Distillation","காய்ச்சி வடித்தல்"],["Watt","வாட்"],["Newton","நியூட்டன்"]],"answer":2,"explanation":["Watt: The SI unit of power.","வாட்: திறனின் SI அலகு."]},{"id":322,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI unit of pressure.","கண்டறிக: அழுத்தத்தின் SI அலகு."],"options":[["Chlorophyll","பச்சையம்"],["Rusting","துருப்பிடித்தல்"],["Pascal","பாஸ்கல்"],["Newton","நியூட்டன்"]],"answer":2,"explanation":["Pascal: The SI unit of pressure.","பாஸ்கல்: அழுத்தத்தின் SI அலகு."]},{"id":323,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Rock altered by heat and pressure without complete melting.","கண்டறிக: முழுமையாக உருகாமல் வெப்பம் மற்றும் அழுத்தத்தால் மாறிய பாறை."],"options":[["Sedimentary rock","படிவுப்பாறை"],["Mahatma Gandhi","மகாத்மா காந்தி"],["Metamorphic rock","உருமாறிய பாறை"],["Longitude","தீர்க்கம்"]],"answer":2,"explanation":["Metamorphic rock: Rock altered by heat and pressure without complete melting.","உருமாறிய பாறை: முழுமையாக உருகாமல் வெப்பம் மற்றும் அழுத்தத்தால் மாறிய பாறை."]},{"id":324,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Wearing away and removal of material by moving agents such as water.","கண்டறிக: நீர் போன்ற நகரும் காரணிகளால் பொருட்கள் தேய்ந்து அகற்றப்படுதல்."],"options":[["Ashoka","அசோகர்"],["Latitude","அட்சம்"],["Delta","கழிமுகம்"],["Erosion","அரித்தல்"]],"answer":3,"explanation":["Erosion: Wearing away and removal of material by moving agents such as water.","அரித்தல்: நீர் போன்ற நகரும் காரணிகளால் பொருட்கள் தேய்ந்து அகற்றப்படுதல்."]},{"id":325,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 26 students, a student is in position 13 from the front. Find the position from the back.","26 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 13 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["14","14"],["17","17"],["24","24"],["15","15"]],"answer":0,"explanation":["Position from back = 26 − 13 + 1 = 14.","பின்னிருந்து இடம் = 26 − 13 + 1 = 14."]},{"id":326,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 38 m north, 14 m east, 9 m south and 14 m west. How far are you from the start, in metres?","38 மீ வடக்கு, 14 மீ கிழக்கு, 9 மீ தெற்கு, 14 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["28","28"],["31","31"],["39","39"],["29","29"]],"answer":3,"explanation":["East and west cancel. Net northward distance = 38 − 9 = 29 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 38 − 9 = 29 மீ."]},{"id":327,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 9 km east and then 12 km north. Find the straight-line distance from the start in km.","9 கி.மீ கிழக்கிலும் பின்னர் 12 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["15","15"],["25","25"],["16","16"],["14","14"]],"answer":0,"explanation":["Pythagoras: √(9² + 12²) = 15 km.","பிதாகரஸ் தேற்றம்: √(9² + 12²) = 15 கி.மீ."]},{"id":328,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 14 → 210, then 25 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 14 → 210 எனில் 25 → ?"],"options":[["650","650"],["652","652"],["649","649"],["660","660"]],"answer":0,"explanation":["25 × (25 + 1) = 650.","25 × (25 + 1) = 650."]},{"id":329,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 5 : 125 :: 15 : ?","மும்மடி விதியைப் பயன்படுத்துக: 5 : 125 :: 15 : ?"],"options":[["3376","3376"],["3377","3377"],["3375","3375"],["3385","3385"]],"answer":2,"explanation":["5³ = 125, so 15³ = 3375.","5³ = 125; எனவே 15³ = 3375."]},{"id":330,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 2 places forward in the alphabet (wrap Z to A). Code DESK.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 2 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). DESK இன் குறியீடு என்ன?"],"options":[["HIWO","HIWO"],["EFTL","EFTL"],["FGUM","FGUM"],["GHVN","GHVN"]],"answer":2,"explanation":["Each letter advances by 2: D → F, E → G, S → U, K → M","ஒவ்வோர் எழுத்தும் 2 இடங்கள் முன்னேறும்: D → F, E → G, S → U, K → M"]},{"id":331,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in LEAF.","A = 1, B = 2, …, Z = 26 எனில், LEAF என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["23","23"],["24","24"],["26","26"],["34","34"]],"answer":1,"explanation":["12 + 5 + 1 + 6 = 24.","12 + 5 + 1 + 6 = 24."]},{"id":332,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Sunday. What day will it be after 40 days?","இன்று ஞாயிறு. 40 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Friday","வெள்ளி"],["Saturday","சனி"],["Monday","திங்கள்"],["Sunday","ஞாயிறு"]],"answer":0,"explanation":["40 ÷ 7 leaves remainder 5. Move 5 days from Sunday: Friday.","40 ஐ 7 ஆல் வகுக்க மீதி 5. ஞாயிறு கிழமையிலிருந்து 5 நாட்கள் நகர்ந்தால் வெள்ளி."]},{"id":333,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 15 students shakes hands once with every other student. How many handshakes occur?","15 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["108","108"],["104","104"],["110","110"],["105","105"]],"answer":3,"explanation":["Each pair is counted once: 15 × 14 ÷ 2 = 105.","ஒவ்வொரு இணையும் ஒருமுறை: 15 × 14 ÷ 2 = 105."]},{"id":334,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 38 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 38 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["114","114"],["117","117"],["115","115"],["125","125"]],"answer":2,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 37 = 115.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 37 = 115."]},{"id":335,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 11, 13, 16, 20, 25, ?","நிறைவு செய்க: 11, 13, 16, 20, 25, ?"],"options":[["30","30"],["31","31"],["41","41"],["34","34"]],"answer":1,"explanation":["Differences increase by 1: 2, 3, 4, 5, 6. Next = 31.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 2, 3, 4, 5, 6. அடுத்த எண் 31."]},{"id":336,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 23, 25, 48, 73, 121, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 23, 25, 48, 73, 121, ?"],"options":[["197","197"],["194","194"],["193","193"],["195","195"]],"answer":1,"explanation":["73 + 121 = 194.","73 + 121 = 194."]},{"id":337,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 8/12 + 6/12.","கூட்டிச் சுருக்குக: 8/12 + 6/12."],"options":[["4/3","4/3"],["17/12","17/12"],["7/6","7/6"],["5/4","5/4"]],"answer":2,"explanation":["(8 + 6)/12 = 14/12 = 7/6.","(8 + 6)/12 = 14/12 = 7/6."]},{"id":338,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 9 red and 12 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 9 சிவப்பு, 12 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["11/23","11/23"],["1/2","1/2"],["5/11","5/11"],["3/7","3/7"]],"answer":3,"explanation":["Favourable outcomes / total = 9/21 = 3/7.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 9/21 = 3/7."]},{"id":339,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 10% of 320.","320 இல் 10% காண்க."],"options":[["37","37"],["32","32"],["34","34"],["35","35"]],"answer":1,"explanation":["320 × 10 / 100 = 32.","320 × 10 / 100 = 32."]},{"id":340,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹2400. Find the price after a 25% discount, in rupees.","குறித்த விலை ₹2400. 25% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["1800","1800"],["1799","1799"],["1801","1801"],["1802","1802"]],"answer":0,"explanation":["Discount = ₹600. Pay 2400 − 600 = ₹1800.","தள்ளுபடி = ₹600. செலுத்துவது 2400 − 600 = ₹1800."]},{"id":341,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2600 at 12% per year for 5 years.","₹2600 க்கு ஆண்டுக்கு 12% வீதம் 5 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1570","1570"],["1563","1563"],["1560","1560"],["3120","3120"]],"answer":2,"explanation":["PRT/100 = 2600 × 12 × 5 / 100 = ₹1560.","PRT/100 = 2600 × 12 × 5 / 100 = ₹1560."]},{"id":342,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 15x + 10 = 205.","x காண்க: 15x + 10 = 205."],"options":[["13","13"],["23","23"],["14","14"],["26","26"]],"answer":0,"explanation":["x = (205 − 10) ÷ 15 = 13.","x = (205 − 10) ÷ 15 = 13."]},{"id":343,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 17 cm long and 9 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 17 செ.மீ, அகலம் 9 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["158","158"],["163","163"],["152","152"],["153","153"]],"answer":3,"explanation":["Area = length × width = 17 × 9 = 153 cm².","பரப்பளவு = நீளம் × அகலம் = 17 × 9 = 153 ச.செ.மீ."]},{"id":344,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 30 m and 18 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 30 மீ மற்றும் 18 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["96","96"],["99","99"],["98","98"],["106","106"]],"answer":0,"explanation":["Perimeter = 2(30 + 18) = 96 m.","சுற்றளவு = 2(30 + 18) = 96 மீ."]},{"id":345,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI unit of electric current.","கண்டறிக: மின்னோட்டத்தின் SI அலகு."],"options":[["Inertia","நிலைமம்"],["Radiation","வெப்பக் கதிர்வீச்சு"],["Vitamin C","வைட்டமின் C"],["Ampere","ஆம்பியர்"]],"answer":3,"explanation":["Ampere: The SI unit of electric current.","ஆம்பியர்: மின்னோட்டத்தின் SI அலகு."]},{"id":346,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI unit of electric potential difference.","கண்டறிக: மின்னழுத்த வேறுபாட்டின் SI அலகு."],"options":[["Solute","கரைபொருள்"],["Volt","வோல்ட்"],["Stomata","இலைத்துளைகள்"],["Freezing","உறைதல்"]],"answer":1,"explanation":["Volt: The SI unit of electric potential difference.","வோல்ட்: மின்னழுத்த வேறுபாட்டின் SI அலகு."]},{"id":347,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI unit of electrical resistance.","கண்டறிக: மின்தடையின் SI அலகு."],"options":[["Ohm","ஓம்"],["Friction","உராய்வு"],["Pollination","மகரந்தச் சேர்க்கை"],["Alveoli","காற்று நுண்ணறைகள்"]],"answer":0,"explanation":["Ohm: The SI unit of electrical resistance.","ஓம்: மின்தடையின் SI அலகு."]},{"id":348,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The laying down of material carried by water, wind or ice.","கண்டறிக: நீர், காற்று அல்லது பனியால் எடுத்துச் செல்லப்பட்ட பொருட்கள் படியுதல்."],"options":[["Tropic of Cancer","கடகரேகை"],["Mahatma Gandhi","மகாத்மா காந்தி"],["Weather","வானிலை"],["Deposition","படிதல்"]],"answer":3,"explanation":["Deposition: The laying down of material carried by water, wind or ice.","படிதல்: நீர், காற்று அல்லது பனியால் எடுத்துச் செல்லப்பட்ட பொருட்கள் படியுதல்."]},{"id":349,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: A depositional landform that may develop at a river mouth.","கண்டறிக: ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்."],"options":[["Sedimentary rock","படிவுப்பாறை"],["Delta","கழிமுகம்"],["Australia","ஆஸ்திரேலியா"],["Latitude","அட்சம்"]],"answer":1,"explanation":["Delta: A depositional landform that may develop at a river mouth.","கழிமுகம்: ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்."]},{"id":350,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 13, 17, 21, 25, 29, …","அடுத்த எண்ணைக் காண்க: 13, 17, 21, 25, 29, …"],"options":[["38","38"],["43","43"],["66","66"],["33","33"]],"answer":3,"explanation":["Add 4 each time. 29 + 4 = 33.","ஒவ்வொரு முறையும் 4 கூட்டுக. 29 + 4 = 33."]},{"id":351,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 23, 46, 92, 184, ?","தொடரை நிறைவு செய்க: 23, 46, 92, 184, ?"],"options":[["370","370"],["378","378"],["367","367"],["368","368"]],"answer":3,"explanation":["Double each term: 184 × 2 = 368.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 184 × 2 = 368."]},{"id":352,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 35, 72, 146, 294, ?","அடுத்த உறுப்பைக் காண்க: 35, 72, 146, 294, ?"],"options":[["589","589"],["591","591"],["600","600"],["590","590"]],"answer":3,"explanation":["Multiply by 2, then add 2: 294 × 2 + 2 = 590.","2 ஆல் பெருக்கி 2 கூட்டுக: 294 × 2 + 2 = 590."]},{"id":353,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 24, 31, ?, 45, 52","விடுபட்ட எண்ணைக் காண்க: 24, 31, ?, 45, 52"],"options":[["37","37"],["38","38"],["76","76"],["43","43"]],"answer":1,"explanation":["The common difference is 7. 31 + 7 = 38.","பொது வித்தியாசம் 7. 31 + 7 = 38."]},{"id":354,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 1225, 1296, 1369, 1444, ?","தொடர்க: 1225, 1296, 1369, 1444, ?"],"options":[["1531","1531"],["1524","1524"],["1521","1521"],["1523","1523"]],"answer":2,"explanation":["These are squares of 35, 36, 37, 38. Next: 39² = 1521.","இவை 35, 36, 37, 38 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 39² = 1521."]},{"id":355,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 31 from the front and position 9 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 31 ஆவது, பின்னிருந்து 9 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["44","44"],["38","38"],["42","42"],["39","39"]],"answer":3,"explanation":["Total = 31 + 9 − 1 = 39; the student is counted only once.","மொத்தம் = 31 + 9 − 1 = 39; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":356,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 33 students, a student is in position 7 from the front. Find the position from the back.","33 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 7 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["27","27"],["30","30"],["26","26"],["29","29"]],"answer":0,"explanation":["Position from back = 33 − 7 + 1 = 27.","பின்னிருந்து இடம் = 33 − 7 + 1 = 27."]},{"id":357,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 20 m north, 16 m east, 9 m south and 16 m west. How far are you from the start, in metres?","20 மீ வடக்கு, 16 மீ கிழக்கு, 9 மீ தெற்கு, 16 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["21","21"],["10","10"],["11","11"],["13","13"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 20 − 9 = 11 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 20 − 9 = 11 மீ."]},{"id":358,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 12 km east and then 16 km north. Find the straight-line distance from the start in km.","12 கி.மீ கிழக்கிலும் பின்னர் 16 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["22","22"],["23","23"],["21","21"],["20","20"]],"answer":3,"explanation":["Pythagoras: √(12² + 16²) = 20 km.","பிதாகரஸ் தேற்றம்: √(12² + 16²) = 20 கி.மீ."]},{"id":359,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 15 → 240, then 24 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 15 → 240 எனில் 24 → ?"],"options":[["1200","1200"],["603","603"],["600","600"],["602","602"]],"answer":2,"explanation":["24 × (24 + 1) = 600.","24 × (24 + 1) = 600."]},{"id":360,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 9 : 729 :: 10 : ?","மும்மடி விதியைப் பயன்படுத்துக: 9 : 729 :: 10 : ?"],"options":[["1010","1010"],["1000","1000"],["1005","1005"],["1002","1002"]],"answer":1,"explanation":["9³ = 729, so 10³ = 1000.","9³ = 729; எனவே 10³ = 1000."]},{"id":361,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 1 places forward in the alphabet (wrap Z to A). Code PARK.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 1 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). PARK இன் குறியீடு என்ன?"],"options":[["SDUN","SDUN"],["PARK","PARK"],["RCTM","RCTM"],["QBSL","QBSL"]],"answer":3,"explanation":["Each letter advances by 1: P → Q, A → B, R → S, K → L","ஒவ்வோர் எழுத்தும் 1 இடங்கள் முன்னேறும்: P → Q, A → B, R → S, K → L"]},{"id":362,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 48 cm and height 12 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 48 செ.மீ, உயரம் 12 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["288","288"],["298","298"],["576","576"],["290","290"]],"answer":0,"explanation":["Area = ½ × 48 × 12 = 288 cm².","பரப்பளவு = ½ × 48 × 12 = 288 ச.செ.மீ."]},{"id":363,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 22 cm × 11 cm × 3 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 22 செ.மீ × 11 செ.மீ × 3 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["725","725"],["1452","1452"],["729","729"],["726","726"]],"answer":3,"explanation":["Volume = length × breadth × height = 22 × 11 × 3 = 726 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 22 × 11 × 3 = 726 க.செ.மீ."]},{"id":364,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 36, 41, 46, 51, 56.","36, 41, 46, 51, 56 ஆகியவற்றின் சராசரி காண்க."],"options":[["92","92"],["56","56"],["45","45"],["46","46"]],"answer":3,"explanation":["Sum ÷ count = 230 ÷ 5 = 46.","கூடுதல் ÷ எண்ணிக்கை = 230 ÷ 5 = 46."]},{"id":365,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 990 km in 18 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 18 மணி நேரத்தில் 990 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["55","55"],["65","65"],["58","58"],["57","57"]],"answer":0,"explanation":["Speed = distance ÷ time = 990 ÷ 18 = 55 km/h.","வேகம் = தொலைவு ÷ நேரம் = 990 ÷ 18 = 55 கி.மீ/மணி."]},{"id":366,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 126 in the ratio 5 : 9. Find the smaller share.","126 ஐ 5 : 9 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["48","48"],["45","45"],["55","55"],["44","44"]],"answer":1,"explanation":["Smaller share = 126 × 5/(5+9) = 45.","சிறிய பங்கு = 126 × 5/(5+9) = 45."]},{"id":367,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 31 and 37.","31 மற்றும் 37 இன் மீ.பொ.வ. காண்க."],"options":[["1","1"],["2","2"],["3","3"],["0","0"]],"answer":0,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":368,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 37 and 5.","37 மற்றும் 5 இன் மீ.பொ.ம. காண்க."],"options":[["188","188"],["184","184"],["185","185"],["186","186"]],"answer":2,"explanation":["LCM = product ÷ HCF = 185 ÷ 1 = 185.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 185 ÷ 1 = 185."]},{"id":369,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹2400 is sold for ₹2640. Find the profit percentage.","₹2400 க்கு வாங்கிய பொருள் ₹2640 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["12","12"],["20","20"],["10","10"],["11","11"]],"answer":2,"explanation":["Profit = ₹240. Profit% = 240 × 100 / 2400 = 10%.","இலாபம் = ₹240. இலாப% = 240 × 100 / 2400 = 10%."]},{"id":370,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI unit of frequency.","கண்டறிக: அதிர்வெண்ணின் SI அலகு."],"options":[["Chlorophyll","பச்சையம்"],["Hertz","ஹெர்ட்ஸ்"],["Root hairs","வேர்த்தூவிகள்"],["Distillation","காய்ச்சி வடித்தல்"]],"answer":1,"explanation":["Hertz: The SI unit of frequency.","ஹெர்ட்ஸ்: அதிர்வெண்ணின் SI அலகு."]},{"id":371,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The SI base unit of thermodynamic temperature.","கண்டறிக: வெப்ப இயக்கவியல் வெப்பநிலையின் SI அடிப்படை அலகு."],"options":[["Joule","ஜூல்"],["Arteries","தமனிகள்"],["Kelvin","கெல்வின்"],["Friction","உராய்வு"]],"answer":2,"explanation":["Kelvin: The SI base unit of thermodynamic temperature.","கெல்வின்: வெப்ப இயக்கவியல் வெப்பநிலையின் SI அடிப்படை அலகு."]},{"id":372,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The tendency to resist a change in the state of rest or motion.","கண்டறிக: ஓய்வு அல்லது இயக்க நிலையில் ஏற்படும் மாற்றத்தை எதிர்க்கும் தன்மை."],"options":[["Fertilisation","கருவுறுதல்"],["Rusting","துருப்பிடித்தல்"],["Inertia","நிலைமம்"],["Hertz","ஹெர்ட்ஸ்"]],"answer":2,"explanation":["Inertia: The tendency to resist a change in the state of rest or motion.","நிலைமம்: ஓய்வு அல்லது இயக்க நிலையில் ஏற்படும் மாற்றத்தை எதிர்க்கும் தன்மை."]},{"id":373,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: A smaller river that joins a larger river.","கண்டறிக: ஒரு பெரிய ஆற்றுடன் இணையும் சிறிய ஆறு."],"options":[["Climate","காலநிலை"],["Revolution","சுற்றிவருதல்"],["Barometer","காற்றழுத்தமானி"],["Tributary","துணையாறு"]],"answer":3,"explanation":["Tributary: A smaller river that joins a larger river.","துணையாறு: ஒரு பெரிய ஆற்றுடன் இணையும் சிறிய ஆறு."]},{"id":374,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: An elevated region with a relatively flat top.","கண்டறிக: ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி."],"options":[["Deposition","படிதல்"],["Longitude","தீர்க்கம்"],["Strait","நீர்ச்சந்தி"],["Plateau","பீடபூமி"]],"answer":3,"explanation":["Plateau: An elevated region with a relatively flat top.","பீடபூமி: ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி."]},{"id":375,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in DESK.","A = 1, B = 2, …, Z = 26 எனில், DESK என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["41","41"],["39","39"],["38","38"],["78","78"]],"answer":1,"explanation":["4 + 5 + 19 + 11 = 39.","4 + 5 + 19 + 11 = 39."]},{"id":376,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Friday. What day will it be after 45 days?","இன்று வெள்ளி. 45 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Monday","திங்கள்"],["Wednesday","புதன்"],["Thursday","வியாழன்"],["Tuesday","செவ்வாய்"]],"answer":0,"explanation":["45 ÷ 7 leaves remainder 3. Move 3 days from Friday: Monday.","45 ஐ 7 ஆல் வகுக்க மீதி 3. வெள்ளி கிழமையிலிருந்து 3 நாட்கள் நகர்ந்தால் திங்கள்."]},{"id":377,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 13 students shakes hands once with every other student. How many handshakes occur?","13 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["83","83"],["80","80"],["78","78"],["156","156"]],"answer":2,"explanation":["Each pair is counted once: 13 × 12 ÷ 2 = 78.","ஒவ்வொரு இணையும் ஒருமுறை: 13 × 12 ÷ 2 = 78."]},{"id":378,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 32 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 32 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["102","102"],["97","97"],["107","107"],["100","100"]],"answer":1,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 31 = 97.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 31 = 97."]},{"id":379,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 8, 10, 13, 17, 22, ?","நிறைவு செய்க: 8, 10, 13, 17, 22, ?"],"options":[["30","30"],["31","31"],["28","28"],["56","56"]],"answer":2,"explanation":["Differences increase by 1: 2, 3, 4, 5, 6. Next = 28.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 2, 3, 4, 5, 6. அடுத்த எண் 28."]},{"id":380,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 21, 27, 48, 75, 123, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 21, 27, 48, 75, 123, ?"],"options":[["396","396"],["208","208"],["200","200"],["198","198"]],"answer":3,"explanation":["75 + 123 = 198.","75 + 123 = 198."]},{"id":381,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 15, 22, 29, 36, 43, …","அடுத்த எண்ணைக் காண்க: 15, 22, 29, 36, 43, …"],"options":[["51","51"],["50","50"],["60","60"],["100","100"]],"answer":1,"explanation":["Add 7 each time. 43 + 7 = 50.","ஒவ்வொரு முறையும் 7 கூட்டுக. 43 + 7 = 50."]},{"id":382,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 26, 52, 104, 208, ?","தொடரை நிறைவு செய்க: 26, 52, 104, 208, ?"],"options":[["832","832"],["416","416"],["415","415"],["419","419"]],"answer":1,"explanation":["Double each term: 208 × 2 = 416.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 208 × 2 = 416."]},{"id":383,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 6, 18, 42, 90, ?","அடுத்த உறுப்பைக் காண்க: 6, 18, 42, 90, ?"],"options":[["186","186"],["191","191"],["196","196"],["187","187"]],"answer":0,"explanation":["Multiply by 2, then add 6: 90 × 2 + 6 = 186.","2 ஆல் பெருக்கி 6 கூட்டுக: 90 × 2 + 6 = 186."]},{"id":384,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 6, 11, ?, 21, 26","விடுபட்ட எண்ணைக் காண்க: 6, 11, ?, 21, 26"],"options":[["21","21"],["19","19"],["16","16"],["17","17"]],"answer":2,"explanation":["The common difference is 5. 11 + 5 = 16.","பொது வித்தியாசம் 5. 11 + 5 = 16."]},{"id":385,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 529, 576, 625, 676, ?","தொடர்க: 529, 576, 625, 676, ?"],"options":[["729","729"],["732","732"],["1458","1458"],["739","739"]],"answer":0,"explanation":["These are squares of 23, 24, 25, 26. Next: 27² = 729.","இவை 23, 24, 25, 26 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 27² = 729."]},{"id":386,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 28 from the front and position 15 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 28 ஆவது, பின்னிருந்து 15 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["42","42"],["45","45"],["52","52"],["44","44"]],"answer":0,"explanation":["Total = 28 + 15 − 1 = 42; the student is counted only once.","மொத்தம் = 28 + 15 − 1 = 42; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":387,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 35° and 78°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 35°, 78°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["67","67"],["134","134"],["68","68"],["77","77"]],"answer":0,"explanation":["180 − 35 − 78 = 67°.","180 − 35 − 78 = 67°."]},{"id":388,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 5°, in degrees.","5° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["350","350"],["178","178"],["177","177"],["175","175"]],"answer":3,"explanation":["Supplementary angles sum to 180°. 180 − 5 = 175°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 5 = 175°."]},{"id":389,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/5 + 4/5.","கூட்டிச் சுருக்குக: 3/5 + 4/5."],"options":[["7/5","7/5"],["9/5","9/5"],["2","2"],["8/5","8/5"]],"answer":0,"explanation":["(3 + 4)/5 = 7/5 = 7/5.","(3 + 4)/5 = 7/5 = 7/5."]},{"id":390,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 10 red and 6 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 10 சிவப்பு, 6 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["13/19","13/19"],["5/8","5/8"],["2/3","2/3"],["11/17","11/17"]],"answer":1,"explanation":["Favourable outcomes / total = 10/16 = 5/8.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 10/16 = 5/8."]},{"id":391,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 15% of 260.","260 இல் 15% காண்க."],"options":[["49","49"],["42","42"],["78","78"],["39","39"]],"answer":3,"explanation":["260 × 15 / 100 = 39.","260 × 15 / 100 = 39."]},{"id":392,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹2500. Find the price after a 20% discount, in rupees.","குறித்த விலை ₹2500. 20% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["2000","2000"],["1999","1999"],["2001","2001"],["2010","2010"]],"answer":0,"explanation":["Discount = ₹500. Pay 2500 − 500 = ₹2000.","தள்ளுபடி = ₹500. செலுத்துவது 2500 − 500 = ₹2000."]},{"id":393,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3000 at 9% per year for 4 years.","₹3000 க்கு ஆண்டுக்கு 9% வீதம் 4 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1090","1090"],["1083","1083"],["1082","1082"],["1080","1080"]],"answer":3,"explanation":["PRT/100 = 3000 × 9 × 4 / 100 = ₹1080.","PRT/100 = 3000 × 9 × 4 / 100 = ₹1080."]},{"id":394,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 14x + 39 = 305.","x காண்க: 14x + 39 = 305."],"options":[["19","19"],["22","22"],["24","24"],["38","38"]],"answer":0,"explanation":["x = (305 − 39) ÷ 14 = 19.","x = (305 − 39) ÷ 14 = 19."]},{"id":395,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The force that opposes relative sliding between surfaces.","கண்டறிக: பரப்புகளுக்கிடையேயான சார்பு சறுக்கல் இயக்கத்தை எதிர்க்கும் விசை."],"options":[["Iodine","அயோடின்"],["Kelvin","கெல்வின்"],["Friction","உராய்வு"],["Volt","வோல்ட்"]],"answer":2,"explanation":["Friction: The force that opposes relative sliding between surfaces.","உராய்வு: பரப்புகளுக்கிடையேயான சார்பு சறுக்கல் இயக்கத்தை எதிர்க்கும் விசை."]},{"id":396,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The attractive interaction between objects with mass.","கண்டறிக: நிறையுள்ள பொருட்களுக்கிடையேயான ஈர்ப்பு."],"options":[["Evaporation","ஆவியாக்குதல்"],["Gravity","ஈர்ப்புவிசை"],["Newton","நியூட்டன்"],["Sublimation","பதங்கமாதல்"]],"answer":1,"explanation":["Gravity: The attractive interaction between objects with mass.","ஈர்ப்புவிசை: நிறையுள்ள பொருட்களுக்கிடையேயான ஈர்ப்பு."]},{"id":397,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Heat transfer through the bulk movement of a fluid.","கண்டறிக: ஒரு பாய்மத்தின் ஒட்டுமொத்த இயக்கத்தால் வெப்பம் கடத்தப்படுதல்."],"options":[["Melting","உருகுதல்"],["Kidneys","சிறுநீரகங்கள்"],["Convection","வெப்பச் சலனம்"],["Phloem","புளோயம்"]],"answer":2,"explanation":["Convection: Heat transfer through the bulk movement of a fluid.","வெப்பச் சலனம்: ஒரு பாய்மத்தின் ஒட்டுமொத்த இயக்கத்தால் வெப்பம் கடத்தப்படுதல்."]},{"id":398,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Land surrounded by water on all sides.","கண்டறிக: அனைத்துப் பக்கங்களிலும் நீரால் சூழப்பட்ட நிலம்."],"options":[["Delta","கழிமுகம்"],["Rajendra I","முதலாம் இராஜேந்திரன்"],["Australia","ஆஸ்திரேலியா"],["Island","தீவு"]],"answer":3,"explanation":["Island: Land surrounded by water on all sides.","தீவு: அனைத்துப் பக்கங்களிலும் நீரால் சூழப்பட்ட நிலம்."]},{"id":399,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: Land surrounded by water on three sides.","கண்டறிக: மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்."],"options":[["Delta","கழிமுகம்"],["Island","தீவு"],["Rajendra I","முதலாம் இராஜேந்திரன்"],["Peninsula","தீபகற்பம்"]],"answer":3,"explanation":["Peninsula: Land surrounded by water on three sides.","தீபகற்பம்: மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்."]},{"id":400,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 27 students, a student is in position 13 from the front. Find the position from the back.","27 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 13 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["15","15"],["25","25"],["16","16"],["17","17"]],"answer":0,"explanation":["Position from back = 27 − 13 + 1 = 15.","பின்னிருந்து இடம் = 27 − 13 + 1 = 15."]},{"id":401,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 23 m north, 6 m east, 5 m south and 6 m west. How far are you from the start, in metres?","23 மீ வடக்கு, 6 மீ கிழக்கு, 5 மீ தெற்கு, 6 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["21","21"],["28","28"],["18","18"],["20","20"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 23 − 5 = 18 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 23 − 5 = 18 மீ."]},{"id":402,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 6 km east and then 8 km north. Find the straight-line distance from the start in km.","6 கி.மீ கிழக்கிலும் பின்னர் 8 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["11","11"],["20","20"],["13","13"],["10","10"]],"answer":3,"explanation":["Pythagoras: √(6² + 8²) = 10 km.","பிதாகரஸ் தேற்றம்: √(6² + 8²) = 10 கி.மீ."]},{"id":403,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 3 → 12, then 19 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 3 → 12 எனில் 19 → ?"],"options":[["760","760"],["380","380"],["390","390"],["381","381"]],"answer":1,"explanation":["19 × (19 + 1) = 380.","19 × (19 + 1) = 380."]},{"id":404,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 9 : 729 :: 10 : ?","மும்மடி விதியைப் பயன்படுத்துக: 9 : 729 :: 10 : ?"],"options":[["1002","1002"],["1005","1005"],["1000","1000"],["1003","1003"]],"answer":2,"explanation":["9³ = 729, so 10³ = 1000.","9³ = 729; எனவே 10³ = 1000."]},{"id":405,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 5 places forward in the alphabet (wrap Z to A). Code SEED.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 5 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). SEED இன் குறியீடு என்ன?"],"options":[["XJJI","XJJI"],["WIIH","WIIH"],["ZLLK","ZLLK"],["YKKJ","YKKJ"]],"answer":0,"explanation":["Each letter advances by 5: S → X, E → J, E → J, D → I","ஒவ்வோர் எழுத்தும் 5 இடங்கள் முன்னேறும்: S → X, E → J, E → J, D → I"]},{"id":406,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in BOOK.","A = 1, B = 2, …, Z = 26 எனில், BOOK என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["42","42"],["46","46"],["53","53"],["43","43"]],"answer":3,"explanation":["2 + 15 + 15 + 11 = 43.","2 + 15 + 15 + 11 = 43."]},{"id":407,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Sunday. What day will it be after 86 days?","இன்று ஞாயிறு. 86 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Wednesday","புதன்"],["Tuesday","செவ்வாய்"],["Thursday","வியாழன்"],["Friday","வெள்ளி"]],"answer":1,"explanation":["86 ÷ 7 leaves remainder 2. Move 2 days from Sunday: Tuesday.","86 ஐ 7 ஆல் வகுக்க மீதி 2. ஞாயிறு கிழமையிலிருந்து 2 நாட்கள் நகர்ந்தால் செவ்வாய்."]},{"id":408,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 22 students shakes hands once with every other student. How many handshakes occur?","22 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["234","234"],["231","231"],["241","241"],["230","230"]],"answer":1,"explanation":["Each pair is counted once: 22 × 21 ÷ 2 = 231.","ஒவ்வொரு இணையும் ஒருமுறை: 22 × 21 ÷ 2 = 231."]},{"id":409,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 34 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 34 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["206","206"],["113","113"],["104","104"],["103","103"]],"answer":3,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 33 = 103.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 33 = 103."]},{"id":410,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 4, 6, 9, 13, 18, ?","நிறைவு செய்க: 4, 6, 9, 13, 18, ?"],"options":[["24","24"],["25","25"],["23","23"],["29","29"]],"answer":0,"explanation":["Differences increase by 1: 2, 3, 4, 5, 6. Next = 24.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 2, 3, 4, 5, 6. அடுத்த எண் 24."]},{"id":411,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 17, 25, 42, 67, 109, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 17, 25, 42, 67, 109, ?"],"options":[["352","352"],["177","177"],["176","176"],["179","179"]],"answer":2,"explanation":["67 + 109 = 176.","67 + 109 = 176."]},{"id":412,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 27 cm long and 13 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 27 செ.மீ, அகலம் 13 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["702","702"],["361","361"],["351","351"],["353","353"]],"answer":2,"explanation":["Area = length × width = 27 × 13 = 351 cm².","பரப்பளவு = நீளம் × அகலம் = 27 × 13 = 351 ச.செ.மீ."]},{"id":413,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 20 m and 10 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 20 மீ மற்றும் 10 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["120","120"],["62","62"],["61","61"],["60","60"]],"answer":3,"explanation":["Perimeter = 2(20 + 10) = 60 m.","சுற்றளவு = 2(20 + 10) = 60 மீ."]},{"id":414,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 66 cm and height 11 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 66 செ.மீ, உயரம் 11 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["373","373"],["726","726"],["362","362"],["363","363"]],"answer":3,"explanation":["Area = ½ × 66 × 11 = 363 cm².","பரப்பளவு = ½ × 66 × 11 = 363 ச.செ.மீ."]},{"id":415,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 36 cm × 9 cm × 15 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 36 செ.மீ × 9 செ.மீ × 15 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["4861","4861"],["4860","4860"],["4865","4865"],["4863","4863"]],"answer":1,"explanation":["Volume = length × breadth × height = 36 × 9 × 15 = 4860 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 36 × 9 × 15 = 4860 க.செ.மீ."]},{"id":416,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 13, 23, 33, 43, 53.","13, 23, 33, 43, 53 ஆகியவற்றின் சராசரி காண்க."],"options":[["33","33"],["66","66"],["35","35"],["43","43"]],"answer":0,"explanation":["Sum ÷ count = 165 ÷ 5 = 33.","கூடுதல் ÷ எண்ணிக்கை = 165 ÷ 5 = 33."]},{"id":417,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 513 km in 9 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 9 மணி நேரத்தில் 513 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["67","67"],["60","60"],["114","114"],["57","57"]],"answer":3,"explanation":["Speed = distance ÷ time = 513 ÷ 9 = 57 km/h.","வேகம் = தொலைவு ÷ நேரம் = 513 ÷ 9 = 57 கி.மீ/மணி."]},{"id":418,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 42 in the ratio 2 : 4. Find the smaller share.","42 ஐ 2 : 4 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["15","15"],["17","17"],["13","13"],["14","14"]],"answer":3,"explanation":["Smaller share = 42 × 2/(2+4) = 14.","சிறிய பங்கு = 42 × 2/(2+4) = 14."]},{"id":419,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 27 and 32.","27 மற்றும் 32 இன் மீ.பொ.வ. காண்க."],"options":[["3","3"],["11","11"],["0","0"],["1","1"]],"answer":3,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":420,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Heat transfer that can occur through a vacuum.","கண்டறிக: வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்."],"options":[["Pascal","பாஸ்கல்"],["Reflection","எதிரொளிப்பு"],["Xylem","சைலம்"],["Radiation","வெப்பக் கதிர்வீச்சு"]],"answer":3,"explanation":["Radiation: Heat transfer that can occur through a vacuum.","வெப்பக் கதிர்வீச்சு: வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்."]},{"id":421,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The bouncing back of light into the same medium.","கண்டறிக: ஒளி அதே ஊடகத்திற்குத் திரும்பும் நிகழ்வு."],"options":[["Mitochondrion","மைட்டோகாண்ட்ரியா"],["Gravity","ஈர்ப்புவிசை"],["Reflection","எதிரொளிப்பு"],["Transpiration","நீராவிப்போக்கு"]],"answer":2,"explanation":["Reflection: The bouncing back of light into the same medium.","எதிரொளிப்பு: ஒளி அதே ஊடகத்திற்குத் திரும்பும் நிகழ்வு."]},{"id":422,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: A change in light direction at a boundary when its speed changes.","கண்டறிக: ஒளியின் வேகம் மாறும்போது ஊடக எல்லையில் அதன் திசை மாறுதல்."],"options":[["Condensation","ஆவி சுருங்குதல்"],["Sublimation","பதங்கமாதல்"],["Refraction","ஒளிவிலகல்"],["Reflection","எதிரொளிப்பு"]],"answer":2,"explanation":["Refraction: A change in light direction at a boundary when its speed changes.","ஒளிவிலகல்: ஒளியின் வேகம் மாறும்போது ஊடக எல்லையில் அதன் திசை மாறுதல்."]},{"id":423,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: A narrow strip of land joining two larger land areas.","கண்டறிக: இரு பெரிய நிலப்பகுதிகளை இணைக்கும் குறுகிய நிலப்பட்டை."],"options":[["Isthmus","நிலச்சந்தி"],["Equator","நிலநடுக்கோடு"],["Prime Meridian","முதன்மை தீர்க்கக்கோடு"],["Strait","நீர்ச்சந்தி"]],"answer":0,"explanation":["Isthmus: A narrow strip of land joining two larger land areas.","நிலச்சந்தி: இரு பெரிய நிலப்பகுதிகளை இணைக்கும் குறுகிய நிலப்பட்டை."]},{"id":424,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: A narrow water passage connecting two larger water bodies.","கண்டறிக: இரு பெரிய நீர்ப்பரப்புகளை இணைக்கும் குறுகிய நீர்ப்பாதை."],"options":[["Igneous rock","தீப்பாறை"],["Strait","நீர்ச்சந்தி"],["Latitude","அட்சம்"],["Asia","ஆசியா"]],"answer":1,"explanation":["Strait: A narrow water passage connecting two larger water bodies.","நீர்ச்சந்தி: இரு பெரிய நீர்ப்பரப்புகளை இணைக்கும் குறுகிய நீர்ப்பாதை."]},{"id":425,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 30, 37, 44, 51, 58, …","அடுத்த எண்ணைக் காண்க: 30, 37, 44, 51, 58, …"],"options":[["68","68"],["67","67"],["64","64"],["65","65"]],"answer":3,"explanation":["Add 7 each time. 58 + 7 = 65.","ஒவ்வொரு முறையும் 7 கூட்டுக. 58 + 7 = 65."]},{"id":426,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 21, 42, 84, 168, ?","தொடரை நிறைவு செய்க: 21, 42, 84, 168, ?"],"options":[["341","341"],["339","339"],["336","336"],["672","672"]],"answer":2,"explanation":["Double each term: 168 × 2 = 336.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 168 × 2 = 336."]},{"id":427,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 28, 62, 130, 266, ?","அடுத்த உறுப்பைக் காண்க: 28, 62, 130, 266, ?"],"options":[["1076","1076"],["538","538"],["539","539"],["543","543"]],"answer":1,"explanation":["Multiply by 2, then add 6: 266 × 2 + 6 = 538.","2 ஆல் பெருக்கி 6 கூட்டுக: 266 × 2 + 6 = 538."]},{"id":428,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 7, 13, ?, 25, 31","விடுபட்ட எண்ணைக் காண்க: 7, 13, ?, 25, 31"],"options":[["19","19"],["20","20"],["22","22"],["29","29"]],"answer":0,"explanation":["The common difference is 6. 13 + 6 = 19.","பொது வித்தியாசம் 6. 13 + 6 = 19."]},{"id":429,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 169, 196, 225, 256, ?","தொடர்க: 169, 196, 225, 256, ?"],"options":[["291","291"],["289","289"],["299","299"],["290","290"]],"answer":1,"explanation":["These are squares of 13, 14, 15, 16. Next: 17² = 289.","இவை 13, 14, 15, 16 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 17² = 289."]},{"id":430,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 31 from the front and position 6 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 31 ஆவது, பின்னிருந்து 6 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["37","37"],["72","72"],["36","36"],["38","38"]],"answer":2,"explanation":["Total = 31 + 6 − 1 = 36; the student is counted only once.","மொத்தம் = 31 + 6 − 1 = 36; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":431,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 26 students, a student is in position 14 from the front. Find the position from the back.","26 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 14 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["13","13"],["18","18"],["26","26"],["16","16"]],"answer":0,"explanation":["Position from back = 26 − 14 + 1 = 13.","பின்னிருந்து இடம் = 26 − 14 + 1 = 13."]},{"id":432,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 13 m north, 13 m east, 8 m south and 13 m west. How far are you from the start, in metres?","13 மீ வடக்கு, 13 மீ கிழக்கு, 8 மீ தெற்கு, 13 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["7","7"],["4","4"],["6","6"],["5","5"]],"answer":3,"explanation":["East and west cancel. Net northward distance = 13 − 8 = 5 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 13 − 8 = 5 மீ."]},{"id":433,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 18 km east and then 24 km north. Find the straight-line distance from the start in km.","18 கி.மீ கிழக்கிலும் பின்னர் 24 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["29","29"],["30","30"],["33","33"],["35","35"]],"answer":1,"explanation":["Pythagoras: √(18² + 24²) = 30 km.","பிதாகரஸ் தேற்றம்: √(18² + 24²) = 30 கி.மீ."]},{"id":434,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 5 → 30, then 18 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 5 → 30 எனில் 18 → ?"],"options":[["341","341"],["352","352"],["347","347"],["342","342"]],"answer":3,"explanation":["18 × (18 + 1) = 342.","18 × (18 + 1) = 342."]},{"id":435,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 5 : 125 :: 10 : ?","மும்மடி விதியைப் பயன்படுத்துக: 5 : 125 :: 10 : ?"],"options":[["1000","1000"],["1003","1003"],["1002","1002"],["1010","1010"]],"answer":0,"explanation":["5³ = 125, so 10³ = 1000.","5³ = 125; எனவே 10³ = 1000."]},{"id":436,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 3 places forward in the alphabet (wrap Z to A). Code RAIN.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 3 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). RAIN இன் குறியீடு என்ன?"],"options":[["VEMR","VEMR"],["WFNS","WFNS"],["TCKP","TCKP"],["UDLQ","UDLQ"]],"answer":3,"explanation":["Each letter advances by 3: R → U, A → D, I → L, N → Q","ஒவ்வோர் எழுத்தும் 3 இடங்கள் முன்னேறும்: R → U, A → D, I → L, N → Q"]},{"id":437,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 12 and 17.","12 மற்றும் 17 இன் மீ.பொ.ம. காண்க."],"options":[["204","204"],["205","205"],["408","408"],["207","207"]],"answer":0,"explanation":["LCM = product ÷ HCF = 204 ÷ 1 = 204.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 204 ÷ 1 = 204."]},{"id":438,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹1000 is sold for ₹1200. Find the profit percentage.","₹1000 க்கு வாங்கிய பொருள் ₹1200 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["30","30"],["25","25"],["40","40"],["20","20"]],"answer":3,"explanation":["Profit = ₹200. Profit% = 200 × 100 / 1000 = 20%.","இலாபம் = ₹200. இலாப% = 200 × 100 / 1000 = 20%."]},{"id":439,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 77° and 54°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 77°, 54°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["49","49"],["48","48"],["51","51"],["54","54"]],"answer":0,"explanation":["180 − 77 − 54 = 49°.","180 − 77 − 54 = 49°."]},{"id":440,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 13°, in degrees.","13° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["177","177"],["167","167"],["168","168"],["172","172"]],"answer":1,"explanation":["Supplementary angles sum to 180°. 180 − 13 = 167°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 13 = 167°."]},{"id":441,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 12/15 + 4/15.","கூட்டிச் சுருக்குக: 12/15 + 4/15."],"options":[["6/5","6/5"],["16/15","16/15"],["17/15","17/15"],["19/15","19/15"]],"answer":1,"explanation":["(12 + 4)/15 = 16/15 = 16/15.","(12 + 4)/15 = 16/15 = 16/15."]},{"id":442,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 12 red and 12 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 12 சிவப்பு, 12 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["1/2","1/2"],["7/13","7/13"],["5/9","5/9"],["13/25","13/25"]],"answer":0,"explanation":["Favourable outcomes / total = 12/24 = 1/2.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 12/24 = 1/2."]},{"id":443,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 75% of 200.","200 இல் 75% காண்க."],"options":[["152","152"],["160","160"],["155","155"],["150","150"]],"answer":3,"explanation":["200 × 75 / 100 = 150.","200 × 75 / 100 = 150."]},{"id":444,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹700. Find the price after a 5% discount, in rupees.","குறித்த விலை ₹700. 5% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["1330","1330"],["666","666"],["667","667"],["665","665"]],"answer":3,"explanation":["Discount = ₹35. Pay 700 − 35 = ₹665.","தள்ளுபடி = ₹35. செலுத்துவது 700 − 35 = ₹665."]},{"id":445,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The conversion of a liquid into vapour at its surface.","கண்டறிக: திரவம் அதன் பரப்பில் ஆவியாக மாறுதல்."],"options":[["Convection","வெப்பச் சலனம்"],["Melting","உருகுதல்"],["Evaporation","ஆவியாக்குதல்"],["Pascal","பாஸ்கல்"]],"answer":2,"explanation":["Evaporation: The conversion of a liquid into vapour at its surface.","ஆவியாக்குதல்: திரவம் அதன் பரப்பில் ஆவியாக மாறுதல்."]},{"id":446,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The change of a gas or vapour into a liquid.","கண்டறிக: வாயு அல்லது ஆவி திரவமாக மாறுதல்."],"options":[["Iodine","அயோடின்"],["Sublimation","பதங்கமாதல்"],["Condensation","ஆவி சுருங்குதல்"],["Platelets","இரத்தத் தட்டுகள்"]],"answer":2,"explanation":["Condensation: The change of a gas or vapour into a liquid.","ஆவி சுருங்குதல்: வாயு அல்லது ஆவி திரவமாக மாறுதல்."]},{"id":447,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Direct change from solid to gas without a liquid stage.","கண்டறிக: திரவ நிலையை அடையாமல் திடம் நேரடியாக வாயுவாக மாறுதல்."],"options":[["Vitamin A","வைட்டமின் A"],["Ohm","ஓம்"],["Vacuole","நுண்குமிழ்"],["Sublimation","பதங்கமாதல்"]],"answer":3,"explanation":["Sublimation: Direct change from solid to gas without a liquid stage.","பதங்கமாதல்: திரவ நிலையை அடையாமல் திடம் நேரடியாக வாயுவாக மாறுதல்."]},{"id":448,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The Mauryan emperor associated with the Kalinga War.","கண்டறிக: கலிங்கப் போருடன் தொடர்புடைய மௌரியப் பேரரசர்."],"options":[["Tributary","துணையாறு"],["Ashoka","அசோகர்"],["Rajendra I","முதலாம் இராஜேந்திரன்"],["Longitude","தீர்க்கம்"]],"answer":1,"explanation":["Ashoka: The Mauryan emperor associated with the Kalinga War.","அசோகர்: கலிங்கப் போருடன் தொடர்புடைய மௌரியப் பேரரசர்."]},{"id":449,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The Chola ruler who built the Brihadisvara Temple at Thanjavur.","கண்டறிக: தஞ்சைப் பெரிய கோயிலைக் கட்டிய சோழ மன்னர்."],"options":[["Prime Meridian","முதன்மை தீர்க்கக்கோடு"],["Rajaraja I","முதலாம் இராஜராஜன்"],["Plateau","பீடபூமி"],["Quit India Movement","வெள்ளையனே வெளியேறு இயக்கம்"]],"answer":1,"explanation":["Rajaraja I: The Chola ruler who built the Brihadisvara Temple at Thanjavur.","முதலாம் இராஜராஜன்: தஞ்சைப் பெரிய கோயிலைக் கட்டிய சோழ மன்னர்."]},{"id":450,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in SEED.","A = 1, B = 2, …, Z = 26 எனில், SEED என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["36","36"],["66","66"],["34","34"],["33","33"]],"answer":3,"explanation":["19 + 5 + 5 + 4 = 33.","19 + 5 + 5 + 4 = 33."]},{"id":451,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Wednesday. What day will it be after 10 days?","இன்று புதன். 10 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Tuesday","செவ்வாய்"],["Saturday","சனி"],["Monday","திங்கள்"],["Sunday","ஞாயிறு"]],"answer":1,"explanation":["10 ÷ 7 leaves remainder 3. Move 3 days from Wednesday: Saturday.","10 ஐ 7 ஆல் வகுக்க மீதி 3. புதன் கிழமையிலிருந்து 3 நாட்கள் நகர்ந்தால் சனி."]},{"id":452,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 22 students shakes hands once with every other student. How many handshakes occur?","22 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["236","236"],["234","234"],["233","233"],["231","231"]],"answer":3,"explanation":["Each pair is counted once: 22 × 21 ÷ 2 = 231.","ஒவ்வொரு இணையும் ஒருமுறை: 22 × 21 ÷ 2 = 231."]},{"id":453,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 37 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 37 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["114","114"],["113","113"],["112","112"],["117","117"]],"answer":2,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 36 = 112.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 36 = 112."]},{"id":454,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 4, 7, 11, 16, 22, ?","நிறைவு செய்க: 4, 7, 11, 16, 22, ?"],"options":[["29","29"],["28","28"],["30","30"],["58","58"]],"answer":0,"explanation":["Differences increase by 1: 3, 4, 5, 6, 7. Next = 29.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 3, 4, 5, 6, 7. அடுத்த எண் 29."]},{"id":455,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 4, 10, 14, 24, 38, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 4, 10, 14, 24, 38, ?"],"options":[["64","64"],["62","62"],["124","124"],["61","61"]],"answer":1,"explanation":["24 + 38 = 62.","24 + 38 = 62."]},{"id":456,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 20, 24, 28, 32, 36, …","அடுத்த எண்ணைக் காண்க: 20, 24, 28, 32, 36, …"],"options":[["40","40"],["43","43"],["39","39"],["80","80"]],"answer":0,"explanation":["Add 4 each time. 36 + 4 = 40.","ஒவ்வொரு முறையும் 4 கூட்டுக. 36 + 4 = 40."]},{"id":457,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 25, 50, 100, 200, ?","தொடரை நிறைவு செய்க: 25, 50, 100, 200, ?"],"options":[["410","410"],["399","399"],["400","400"],["800","800"]],"answer":2,"explanation":["Double each term: 200 × 2 = 400.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 200 × 2 = 400."]},{"id":458,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 21, 45, 93, 189, ?","அடுத்த உறுப்பைக் காண்க: 21, 45, 93, 189, ?"],"options":[["381","381"],["380","380"],["391","391"],["386","386"]],"answer":0,"explanation":["Multiply by 2, then add 3: 189 × 2 + 3 = 381.","2 ஆல் பெருக்கி 3 கூட்டுக: 189 × 2 + 3 = 381."]},{"id":459,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 21, 23, ?, 27, 29","விடுபட்ட எண்ணைக் காண்க: 21, 23, ?, 27, 29"],"options":[["50","50"],["25","25"],["30","30"],["24","24"]],"answer":1,"explanation":["The common difference is 2. 23 + 2 = 25.","பொது வித்தியாசம் 2. 23 + 2 = 25."]},{"id":460,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 484, 529, 576, 625, ?","தொடர்க: 484, 529, 576, 625, ?"],"options":[["679","679"],["1352","1352"],["676","676"],["677","677"]],"answer":2,"explanation":["These are squares of 22, 23, 24, 25. Next: 26² = 676.","இவை 22, 23, 24, 25 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 26² = 676."]},{"id":461,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 8 from the front and position 4 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 8 ஆவது, பின்னிருந்து 4 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["11","11"],["16","16"],["10","10"],["13","13"]],"answer":0,"explanation":["Total = 8 + 4 − 1 = 11; the student is counted only once.","மொத்தம் = 8 + 4 − 1 = 11; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":462,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹1700 at 9% per year for 5 years.","₹1700 க்கு ஆண்டுக்கு 9% வீதம் 5 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["765","765"],["775","775"],["770","770"],["768","768"]],"answer":0,"explanation":["PRT/100 = 1700 × 9 × 5 / 100 = ₹765.","PRT/100 = 1700 × 9 × 5 / 100 = ₹765."]},{"id":463,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 10x + 31 = 141.","x காண்க: 10x + 31 = 141."],"options":[["22","22"],["14","14"],["11","11"],["21","21"]],"answer":2,"explanation":["x = (141 − 31) ÷ 10 = 11.","x = (141 − 31) ÷ 10 = 11."]},{"id":464,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 35 cm long and 14 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 35 செ.மீ, அகலம் 14 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["492","492"],["495","495"],["489","489"],["490","490"]],"answer":3,"explanation":["Area = length × width = 35 × 14 = 490 cm².","பரப்பளவு = நீளம் × அகலம் = 35 × 14 = 490 ச.செ.மீ."]},{"id":465,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 32 m and 8 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 32 மீ மற்றும் 8 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["79","79"],["90","90"],["83","83"],["80","80"]],"answer":3,"explanation":["Perimeter = 2(32 + 8) = 80 m.","சுற்றளவு = 2(32 + 8) = 80 மீ."]},{"id":466,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 18 cm and height 11 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 18 செ.மீ, உயரம் 11 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["104","104"],["102","102"],["109","109"],["99","99"]],"answer":3,"explanation":["Area = ½ × 18 × 11 = 99 cm².","பரப்பளவு = ½ × 18 × 11 = 99 ச.செ.மீ."]},{"id":467,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 11 cm × 14 cm × 8 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 11 செ.மீ × 14 செ.மீ × 8 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["1232","1232"],["1237","1237"],["1231","1231"],["1234","1234"]],"answer":0,"explanation":["Volume = length × breadth × height = 11 × 14 × 8 = 1232 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 11 × 14 × 8 = 1232 க.செ.மீ."]},{"id":468,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 5, 17, 29, 41, 53.","5, 17, 29, 41, 53 ஆகியவற்றின் சராசரி காண்க."],"options":[["31","31"],["29","29"],["34","34"],["30","30"]],"answer":1,"explanation":["Sum ÷ count = 145 ÷ 5 = 29.","கூடுதல் ÷ எண்ணிக்கை = 145 ÷ 5 = 29."]},{"id":469,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 275 km in 5 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 5 மணி நேரத்தில் 275 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["55","55"],["56","56"],["58","58"],["54","54"]],"answer":0,"explanation":["Speed = distance ÷ time = 275 ÷ 5 = 55 km/h.","வேகம் = தொலைவு ÷ நேரம் = 275 ÷ 5 = 55 கி.மீ/மணி."]},{"id":470,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The change of a solid into a liquid.","கண்டறிக: திடப்பொருள் திரவமாக மாறுதல்."],"options":[["Vitamin D","வைட்டமின் D"],["Joule","ஜூல்"],["Melting","உருகுதல்"],["Stomata","இலைத்துளைகள்"]],"answer":2,"explanation":["Melting: The change of a solid into a liquid.","உருகுதல்: திடப்பொருள் திரவமாக மாறுதல்."]},{"id":471,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The change of a liquid into a solid.","கண்டறிக: திரவம் திடப்பொருளாக மாறுதல்."],"options":[["Chloroplast","பசுங்கணிகம்"],["Freezing","உறைதல்"],["Veins","சிரைகள்"],["Cell membrane","செல் சவ்வு"]],"answer":1,"explanation":["Freezing: The change of a liquid into a solid.","உறைதல்: திரவம் திடப்பொருளாக மாறுதல்."]},{"id":472,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The substance dissolved in a solvent to form a solution.","கண்டறிக: கரைப்பானில் கரைந்து கரைசலை உருவாக்கும் பொருள்."],"options":[["Hertz","ஹெர்ட்ஸ்"],["Solute","கரைபொருள்"],["Arteries","தமனிகள்"],["Sublimation","பதங்கமாதல்"]],"answer":1,"explanation":["Solute: The substance dissolved in a solvent to form a solution.","கரைபொருள்: கரைப்பானில் கரைந்து கரைசலை உருவாக்கும் பொருள்."]},{"id":473,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The Chola ruler who founded Gangaikonda Cholapuram.","கண்டறிக: கங்கைகொண்ட சோழபுரத்தை நிறுவிய சோழ மன்னர்."],"options":[["Climate","காலநிலை"],["Metamorphic rock","உருமாறிய பாறை"],["Rajendra I","முதலாம் இராஜேந்திரன்"],["Deposition","படிதல்"]],"answer":2,"explanation":["Rajendra I: The Chola ruler who founded Gangaikonda Cholapuram.","முதலாம் இராஜேந்திரன்: கங்கைகொண்ட சோழபுரத்தை நிறுவிய சோழ மன்னர்."]},{"id":474,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The leader who led the Dandi Salt March in 1930.","கண்டறிக: 1930 இல் தண்டி உப்பு யாத்திரையை வழிநடத்திய தலைவர்."],"options":[["Deposition","படிதல்"],["Mahatma Gandhi","மகாத்மா காந்தி"],["Ashoka","அசோகர்"],["Strait","நீர்ச்சந்தி"]],"answer":1,"explanation":["Mahatma Gandhi: The leader who led the Dandi Salt March in 1930.","மகாத்மா காந்தி: 1930 இல் தண்டி உப்பு யாத்திரையை வழிநடத்திய தலைவர்."]},{"id":475,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 40 students, a student is in position 7 from the front. Find the position from the back.","40 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 7 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["36","36"],["34","34"],["33","33"],["44","44"]],"answer":1,"explanation":["Position from back = 40 − 7 + 1 = 34.","பின்னிருந்து இடம் = 40 − 7 + 1 = 34."]},{"id":476,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 27 m north, 10 m east, 8 m south and 10 m west. How far are you from the start, in metres?","27 மீ வடக்கு, 10 மீ கிழக்கு, 8 மீ தெற்கு, 10 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["29","29"],["20","20"],["19","19"],["22","22"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 27 − 8 = 19 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 27 − 8 = 19 மீ."]},{"id":477,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 6 km east and then 8 km north. Find the straight-line distance from the start in km.","6 கி.மீ கிழக்கிலும் பின்னர் 8 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["10","10"],["12","12"],["15","15"],["20","20"]],"answer":0,"explanation":["Pythagoras: √(6² + 8²) = 10 km.","பிதாகரஸ் தேற்றம்: √(6² + 8²) = 10 கி.மீ."]},{"id":478,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 4 → 20, then 19 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 4 → 20 எனில் 19 → ?"],"options":[["380","380"],["385","385"],["381","381"],["379","379"]],"answer":0,"explanation":["19 × (19 + 1) = 380.","19 × (19 + 1) = 380."]},{"id":479,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 4 : 64 :: 17 : ?","மும்மடி விதியைப் பயன்படுத்துக: 4 : 64 :: 17 : ?"],"options":[["4913","4913"],["4923","4923"],["4918","4918"],["4916","4916"]],"answer":0,"explanation":["4³ = 64, so 17³ = 4913.","4³ = 64; எனவே 17³ = 4913."]},{"id":480,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 2 places forward in the alphabet (wrap Z to A). Code PLAY.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 2 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). PLAY இன் குறியீடு என்ன?"],"options":[["SODB","SODB"],["RNCA","RNCA"],["QMBZ","QMBZ"],["TPEC","TPEC"]],"answer":1,"explanation":["Each letter advances by 2: P → R, L → N, A → C, Y → A","ஒவ்வோர் எழுத்தும் 2 இடங்கள் முன்னேறும்: P → R, L → N, A → C, Y → A"]},{"id":481,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in ROAD.","A = 1, B = 2, …, Z = 26 எனில், ROAD என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["41","41"],["38","38"],["48","48"],["76","76"]],"answer":1,"explanation":["18 + 15 + 1 + 4 = 38.","18 + 15 + 1 + 4 = 38."]},{"id":482,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Wednesday. What day will it be after 69 days?","இன்று புதன். 69 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Friday","வெள்ளி"],["Thursday","வியாழன்"],["Wednesday","புதன்"],["Tuesday","செவ்வாய்"]],"answer":3,"explanation":["69 ÷ 7 leaves remainder 6. Move 6 days from Wednesday: Tuesday.","69 ஐ 7 ஆல் வகுக்க மீதி 6. புதன் கிழமையிலிருந்து 6 நாட்கள் நகர்ந்தால் செவ்வாய்."]},{"id":483,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 5 students shakes hands once with every other student. How many handshakes occur?","5 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["12","12"],["20","20"],["10","10"],["13","13"]],"answer":2,"explanation":["Each pair is counted once: 5 × 4 ÷ 2 = 10.","ஒவ்வொரு இணையும் ஒருமுறை: 5 × 4 ÷ 2 = 10."]},{"id":484,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 5 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 5 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["32","32"],["16","16"],["17","17"],["21","21"]],"answer":1,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 4 = 16.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 4 = 16."]},{"id":485,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 3, 5, 8, 12, 17, ?","நிறைவு செய்க: 3, 5, 8, 12, 17, ?"],"options":[["28","28"],["23","23"],["25","25"],["26","26"]],"answer":1,"explanation":["Differences increase by 1: 2, 3, 4, 5, 6. Next = 23.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 2, 3, 4, 5, 6. அடுத்த எண் 23."]},{"id":486,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 28, 33, 61, 94, 155, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 28, 33, 61, 94, 155, ?"],"options":[["252","252"],["251","251"],["249","249"],["498","498"]],"answer":2,"explanation":["94 + 155 = 249.","94 + 155 = 249."]},{"id":487,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 665 in the ratio 7 : 12. Find the smaller share.","665 ஐ 7 : 12 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["245","245"],["255","255"],["250","250"],["490","490"]],"answer":0,"explanation":["Smaller share = 665 × 7/(7+12) = 245.","சிறிய பங்கு = 665 × 7/(7+12) = 245."]},{"id":488,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 28 and 33.","28 மற்றும் 33 இன் மீ.பொ.வ. காண்க."],"options":[["1","1"],["2","2"],["6","6"],["11","11"]],"answer":0,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":489,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 40 and 6.","40 மற்றும் 6 இன் மீ.பொ.ம. காண்க."],"options":[["120","120"],["125","125"],["121","121"],["130","130"]],"answer":0,"explanation":["LCM = product ÷ HCF = 240 ÷ 2 = 120.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 240 ÷ 2 = 120."]},{"id":490,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹3800 is sold for ₹4750. Find the profit percentage.","₹3800 க்கு வாங்கிய பொருள் ₹4750 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["30","30"],["26","26"],["28","28"],["25","25"]],"answer":3,"explanation":["Profit = ₹950. Profit% = 950 × 100 / 3800 = 25%.","இலாபம் = ₹950. இலாப% = 950 × 100 / 3800 = 25%."]},{"id":491,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 49° and 62°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 49°, 62°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["72","72"],["71","71"],["69","69"],["74","74"]],"answer":2,"explanation":["180 − 49 − 62 = 69°.","180 − 49 − 62 = 69°."]},{"id":492,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 26°, in degrees.","26° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["155","155"],["154","154"],["156","156"],["159","159"]],"answer":1,"explanation":["Supplementary angles sum to 180°. 180 − 26 = 154°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 26 = 154°."]},{"id":493,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/11 + 1/11.","கூட்டிச் சுருக்குக: 5/11 + 1/11."],"options":[["6/11","6/11"],["8/11","8/11"],["7/11","7/11"],["9/11","9/11"]],"answer":0,"explanation":["(5 + 1)/11 = 6/11 = 6/11.","(5 + 1)/11 = 6/11 = 6/11."]},{"id":494,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 8 red and 10 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 8 சிவப்பு, 10 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["1/2","1/2"],["4/9","4/9"],["9/19","9/19"],["11/21","11/21"]],"answer":1,"explanation":["Favourable outcomes / total = 8/18 = 4/9.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 8/18 = 4/9."]},{"id":495,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The substance in which a solute dissolves.","கண்டறிக: கரைபொருள் கரையும் பொருள்."],"options":[["Joule","ஜூல்"],["Kelvin","கெல்வின்"],["Solvent","கரைப்பான்"],["Iron","இரும்பு"]],"answer":2,"explanation":["Solvent: The substance in which a solute dissolves.","கரைப்பான்: கரைபொருள் கரையும் பொருள்."]},{"id":496,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Separating an insoluble solid from a liquid using a porous barrier.","கண்டறிக: நுண்துளைத் தடுப்பால் கரையாத திடப்பொருளை திரவத்திலிருந்து பிரித்தல்."],"options":[["Filtration","வடிகட்டுதல்"],["Chlorophyll","பச்சையம்"],["Distillation","காய்ச்சி வடித்தல்"],["Phloem","புளோயம்"]],"answer":0,"explanation":["Filtration: Separating an insoluble solid from a liquid using a porous barrier.","வடிகட்டுதல்: நுண்துளைத் தடுப்பால் கரையாத திடப்பொருளை திரவத்திலிருந்து பிரித்தல்."]},{"id":497,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Separation using vaporisation followed by condensation.","கண்டறிக: ஆவியாக்குதலுக்குப் பின் ஆவி சுருங்குதலைப் பயன்படுத்திப் பிரித்தல்."],"options":[["Reflection","எதிரொளிப்பு"],["Distillation","காய்ச்சி வடித்தல்"],["Newton","நியூட்டன்"],["Ampere","ஆம்பியர்"]],"answer":1,"explanation":["Distillation: Separation using vaporisation followed by condensation.","காய்ச்சி வடித்தல்: ஆவியாக்குதலுக்குப் பின் ஆவி சுருங்குதலைப் பயன்படுத்திப் பிரித்தல்."]},{"id":498,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The freedom fighter associated with the Swadeshi Steam Navigation Company.","கண்டறிக: சுதேசி நீராவிக் கப்பல் நிறுவனத்துடன் தொடர்புடைய விடுதலைப் போராட்ட வீரர்."],"options":[["Peninsula","தீபகற்பம்"],["Deposition","படிதல்"],["Sedimentary rock","படிவுப்பாறை"],["V. O. Chidambaranar","வ. உ. சிதம்பரனார்"]],"answer":3,"explanation":["V. O. Chidambaranar: The freedom fighter associated with the Swadeshi Steam Navigation Company.","வ. உ. சிதம்பரனார்: சுதேசி நீராவிக் கப்பல் நிறுவனத்துடன் தொடர்புடைய விடுதலைப் போராட்ட வீரர்."]},{"id":499,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The leader popularly called Netaji.","கண்டறிக: நேதாஜி எனப் போற்றப்படும் தலைவர்."],"options":[["Subhas Chandra Bose","சுபாஷ் சந்திர போஸ்"],["Arctic Ocean","ஆர்க்டிக் பெருங்கடல்"],["Prime Meridian","முதன்மை தீர்க்கக்கோடு"],["Wind vane","காற்றுத்திசை காட்டி"]],"answer":0,"explanation":["Subhas Chandra Bose: The leader popularly called Netaji.","சுபாஷ் சந்திர போஸ்: நேதாஜி எனப் போற்றப்படும் தலைவர்."]},{"id":500,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 20, 25, 30, 35, 40, …","அடுத்த எண்ணைக் காண்க: 20, 25, 30, 35, 40, …"],"options":[["45","45"],["44","44"],["48","48"],["90","90"]],"answer":0,"explanation":["Add 5 each time. 40 + 5 = 45.","ஒவ்வொரு முறையும் 5 கூட்டுக. 40 + 5 = 45."]},{"id":501,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 31, 62, 124, 248, ?","தொடரை நிறைவு செய்க: 31, 62, 124, 248, ?"],"options":[["501","501"],["498","498"],["496","496"],["497","497"]],"answer":2,"explanation":["Double each term: 248 × 2 = 496.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 248 × 2 = 496."]},{"id":502,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 10, 27, 61, 129, ?","அடுத்த உறுப்பைக் காண்க: 10, 27, 61, 129, ?"],"options":[["265","265"],["270","270"],["264","264"],["275","275"]],"answer":0,"explanation":["Multiply by 2, then add 7: 129 × 2 + 7 = 265.","2 ஆல் பெருக்கி 7 கூட்டுக: 129 × 2 + 7 = 265."]},{"id":503,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 33, 42, ?, 60, 69","விடுபட்ட எண்ணைக் காண்க: 33, 42, ?, 60, 69"],"options":[["56","56"],["51","51"],["54","54"],["52","52"]],"answer":1,"explanation":["The common difference is 9. 42 + 9 = 51.","பொது வித்தியாசம் 9. 42 + 9 = 51."]},{"id":504,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 784, 841, 900, 961, ?","தொடர்க: 784, 841, 900, 961, ?"],"options":[["1027","1027"],["1023","1023"],["1024","1024"],["1025","1025"]],"answer":2,"explanation":["These are squares of 28, 29, 30, 31. Next: 32² = 1024.","இவை 28, 29, 30, 31 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 32² = 1024."]},{"id":505,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 12 from the front and position 19 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 12 ஆவது, பின்னிருந்து 19 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["30","30"],["32","32"],["40","40"],["60","60"]],"answer":0,"explanation":["Total = 12 + 19 − 1 = 30; the student is counted only once.","மொத்தம் = 12 + 19 − 1 = 30; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":506,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 35 students, a student is in position 22 from the front. Find the position from the back.","35 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 22 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["24","24"],["14","14"],["13","13"],["15","15"]],"answer":1,"explanation":["Position from back = 35 − 22 + 1 = 14.","பின்னிருந்து இடம் = 35 − 22 + 1 = 14."]},{"id":507,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 40 m north, 18 m east, 6 m south and 18 m west. How far are you from the start, in metres?","40 மீ வடக்கு, 18 மீ கிழக்கு, 6 மீ தெற்கு, 18 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["39","39"],["35","35"],["34","34"],["33","33"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 40 − 6 = 34 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 40 − 6 = 34 மீ."]},{"id":508,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 24 km east and then 32 km north. Find the straight-line distance from the start in km.","24 கி.மீ கிழக்கிலும் பின்னர் 32 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["40","40"],["41","41"],["45","45"],["42","42"]],"answer":0,"explanation":["Pythagoras: √(24² + 32²) = 40 km.","பிதாகரஸ் தேற்றம்: √(24² + 32²) = 40 கி.மீ."]},{"id":509,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 3 → 12, then 27 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 3 → 12 எனில் 27 → ?"],"options":[["759","759"],["756","756"],["766","766"],["761","761"]],"answer":1,"explanation":["27 × (27 + 1) = 756.","27 × (27 + 1) = 756."]},{"id":510,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 6 : 216 :: 16 : ?","மும்மடி விதியைப் பயன்படுத்துக: 6 : 216 :: 16 : ?"],"options":[["4095","4095"],["4096","4096"],["8192","8192"],["4098","4098"]],"answer":1,"explanation":["6³ = 216, so 16³ = 4096.","6³ = 216; எனவே 16³ = 4096."]},{"id":511,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 4 places forward in the alphabet (wrap Z to A). Code BOOK.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 4 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). BOOK இன் குறியீடு என்ன?"],"options":[["HUUQ","HUUQ"],["GTTP","GTTP"],["ERRN","ERRN"],["FSSO","FSSO"]],"answer":3,"explanation":["Each letter advances by 4: B → F, O → S, O → S, K → O","ஒவ்வோர் எழுத்தும் 4 இடங்கள் முன்னேறும்: B → F, O → S, O → S, K → O"]},{"id":512,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 75% of 460.","460 இல் 75% காண்க."],"options":[["690","690"],["348","348"],["345","345"],["350","350"]],"answer":2,"explanation":["460 × 75 / 100 = 345.","460 × 75 / 100 = 345."]},{"id":513,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹1200. Find the price after a 20% discount, in rupees.","குறித்த விலை ₹1200. 20% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["970","970"],["959","959"],["960","960"],["961","961"]],"answer":2,"explanation":["Discount = ₹240. Pay 1200 − 240 = ₹960.","தள்ளுபடி = ₹240. செலுத்துவது 1200 − 240 = ₹960."]},{"id":514,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2200 at 3% per year for 5 years.","₹2200 க்கு ஆண்டுக்கு 3% வீதம் 5 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["330","330"],["331","331"],["332","332"],["340","340"]],"answer":0,"explanation":["PRT/100 = 2200 × 3 × 5 / 100 = ₹330.","PRT/100 = 2200 × 3 × 5 / 100 = ₹330."]},{"id":515,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 14x + 40 = 124.","x காண்க: 14x + 40 = 124."],"options":[["16","16"],["5","5"],["11","11"],["6","6"]],"answer":3,"explanation":["x = (124 − 40) ÷ 14 = 6.","x = (124 − 40) ÷ 14 = 6."]},{"id":516,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 7 cm long and 14 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 7 செ.மீ, அகலம் 14 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["103","103"],["98","98"],["108","108"],["100","100"]],"answer":1,"explanation":["Area = length × width = 7 × 14 = 98 cm².","பரப்பளவு = நீளம் × அகலம் = 7 × 14 = 98 ச.செ.மீ."]},{"id":517,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 39 m and 16 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 39 மீ மற்றும் 16 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["110","110"],["109","109"],["120","120"],["115","115"]],"answer":0,"explanation":["Perimeter = 2(39 + 16) = 110 m.","சுற்றளவு = 2(39 + 16) = 110 மீ."]},{"id":518,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 34 cm and height 6 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 34 செ.மீ, உயரம் 6 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["102","102"],["107","107"],["104","104"],["105","105"]],"answer":0,"explanation":["Area = ½ × 34 × 6 = 102 cm².","பரப்பளவு = ½ × 34 × 6 = 102 ச.செ.மீ."]},{"id":519,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 19 cm × 16 cm × 3 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 19 செ.மீ × 16 செ.மீ × 3 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["914","914"],["915","915"],["912","912"],["917","917"]],"answer":2,"explanation":["Volume = length × breadth × height = 19 × 16 × 3 = 912 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 19 × 16 × 3 = 912 க.செ.மீ."]},{"id":520,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: A reaction between an acid and a base that forms salt and water.","கண்டறிக: அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்."],"options":[["Cell wall","செல்சுவர்"],["Neutralisation","நடுநிலையாக்கல்"],["Convection","வெப்பச் சலனம்"],["Refraction","ஒளிவிலகல்"]],"answer":1,"explanation":["Neutralisation: A reaction between an acid and a base that forms salt and water.","நடுநிலையாக்கல்: அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்."]},{"id":521,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: Corrosion of iron in the presence of oxygen and moisture.","கண்டறிக: ஆக்சிஜன் மற்றும் ஈரப்பதத்தின் முன்னிலையில் இரும்பு அரித்தல்."],"options":[["Root hairs","வேர்த்தூவிகள்"],["Veins","சிரைகள்"],["Rusting","துருப்பிடித்தல்"],["Phloem","புளோயம்"]],"answer":2,"explanation":["Rusting: Corrosion of iron in the presence of oxygen and moisture.","துருப்பிடித்தல்: ஆக்சிஜன் மற்றும் ஈரப்பதத்தின் முன்னிலையில் இரும்பு அரித்தல்."]},{"id":522,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Identify the term: The gas that makes up the largest fraction of dry air.","கண்டறிக: உலர் காற்றில் மிக அதிகப் பங்கு வகிக்கும் வாயு."],"options":[["Iodine","அயோடின்"],["Ribosome","ரைபோசோம்"],["Vitamin A","வைட்டமின் A"],["Nitrogen","நைட்ரஜன்"]],"answer":3,"explanation":["Nitrogen: The gas that makes up the largest fraction of dry air.","நைட்ரஜன்: உலர் காற்றில் மிக அதிகப் பங்கு வகிக்கும் வாயு."]},{"id":523,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The place in Amritsar where a massacre occurred in 1919.","கண்டறிக: 1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்."],"options":[["Island","தீவு"],["Jallianwala Bagh","ஜாலியன்வாலா பாக்"],["Pacific Ocean","பசிபிக் பெருங்கடல்"],["Anemometer","காற்று வேகமானி"]],"answer":1,"explanation":["Jallianwala Bagh: The place in Amritsar where a massacre occurred in 1919.","ஜாலியன்வாலா பாக்: 1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்."]},{"id":524,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Identify the term: The mass movement launched under Gandhi’s leadership in August 1942.","கண்டறிக: 1942 ஆகஸ்டில் காந்தியின் தலைமையில் தொடங்கப்பட்ட மக்கள் இயக்கம்."],"options":[["Arctic Ocean","ஆர்க்டிக் பெருங்கடல்"],["Quit India Movement","வெள்ளையனே வெளியேறு இயக்கம்"],["Strait","நீர்ச்சந்தி"],["Plateau","பீடபூமி"]],"answer":1,"explanation":["Quit India Movement: The mass movement launched under Gandhi’s leadership in August 1942.","வெள்ளையனே வெளியேறு இயக்கம்: 1942 ஆகஸ்டில் காந்தியின் தலைமையில் தொடங்கப்பட்ட மக்கள் இயக்கம்."]},{"id":525,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in PLAY.","A = 1, B = 2, …, Z = 26 எனில், PLAY என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["54","54"],["64","64"],["56","56"],["59","59"]],"answer":0,"explanation":["16 + 12 + 1 + 25 = 54.","16 + 12 + 1 + 25 = 54."]},{"id":526,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Sunday. What day will it be after 10 days?","இன்று ஞாயிறு. 10 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Friday","வெள்ளி"],["Wednesday","புதன்"],["Thursday","வியாழன்"],["Saturday","சனி"]],"answer":1,"explanation":["10 ÷ 7 leaves remainder 3. Move 3 days from Sunday: Wednesday.","10 ஐ 7 ஆல் வகுக்க மீதி 3. ஞாயிறு கிழமையிலிருந்து 3 நாட்கள் நகர்ந்தால் புதன்."]},{"id":527,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 5 students shakes hands once with every other student. How many handshakes occur?","5 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["20","20"],["10","10"],["13","13"],["11","11"]],"answer":1,"explanation":["Each pair is counted once: 5 × 4 ÷ 2 = 10.","ஒவ்வொரு இணையும் ஒருமுறை: 5 × 4 ÷ 2 = 10."]},{"id":528,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 18 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 18 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["57","57"],["55","55"],["54","54"],["60","60"]],"answer":1,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 17 = 55.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 17 = 55."]},{"id":529,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 10, 14, 19, 25, 32, ?","நிறைவு செய்க: 10, 14, 19, 25, 32, ?"],"options":[["41","41"],["40","40"],["42","42"],["50","50"]],"answer":1,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 40.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 40."]},{"id":530,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 30, 34, 64, 98, 162, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 30, 34, 64, 98, 162, ?"],"options":[["260","260"],["265","265"],["270","270"],["259","259"]],"answer":0,"explanation":["98 + 162 = 260.","98 + 162 = 260."]},{"id":531,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 31, 33, 35, 37, 39, …","அடுத்த எண்ணைக் காண்க: 31, 33, 35, 37, 39, …"],"options":[["42","42"],["41","41"],["44","44"],["43","43"]],"answer":1,"explanation":["Add 2 each time. 39 + 2 = 41.","ஒவ்வொரு முறையும் 2 கூட்டுக. 39 + 2 = 41."]},{"id":532,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 10, 20, 40, 80, ?","தொடரை நிறைவு செய்க: 10, 20, 40, 80, ?"],"options":[["165","165"],["159","159"],["160","160"],["170","170"]],"answer":2,"explanation":["Double each term: 80 × 2 = 160.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 80 × 2 = 160."]},{"id":533,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 24, 54, 114, 234, ?","அடுத்த உறுப்பைக் காண்க: 24, 54, 114, 234, ?"],"options":[["474","474"],["948","948"],["479","479"],["473","473"]],"answer":0,"explanation":["Multiply by 2, then add 6: 234 × 2 + 6 = 474.","2 ஆல் பெருக்கி 6 கூட்டுக: 234 × 2 + 6 = 474."]},{"id":534,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 7, 15, ?, 31, 39","விடுபட்ட எண்ணைக் காண்க: 7, 15, ?, 31, 39"],"options":[["25","25"],["24","24"],["23","23"],["26","26"]],"answer":2,"explanation":["The common difference is 8. 15 + 8 = 23.","பொது வித்தியாசம் 8. 15 + 8 = 23."]},{"id":535,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 225, 256, 289, 324, ?","தொடர்க: 225, 256, 289, 324, ?"],"options":[["361","361"],["363","363"],["371","371"],["364","364"]],"answer":0,"explanation":["These are squares of 15, 16, 17, 18. Next: 19² = 361.","இவை 15, 16, 17, 18 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 19² = 361."]},{"id":536,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 13 from the front and position 16 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 13 ஆவது, பின்னிருந்து 16 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["56","56"],["30","30"],["28","28"],["27","27"]],"answer":2,"explanation":["Total = 13 + 16 − 1 = 28; the student is counted only once.","மொத்தம் = 13 + 16 − 1 = 28; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":537,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 18, 31, 44, 57, 70.","18, 31, 44, 57, 70 ஆகியவற்றின் சராசரி காண்க."],"options":[["44","44"],["49","49"],["45","45"],["88","88"]],"answer":0,"explanation":["Sum ÷ count = 220 ÷ 5 = 44.","கூடுதல் ÷ எண்ணிக்கை = 220 ÷ 5 = 44."]},{"id":538,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 540 km in 12 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 12 மணி நேரத்தில் 540 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["47","47"],["45","45"],["90","90"],["50","50"]],"answer":1,"explanation":["Speed = distance ÷ time = 540 ÷ 12 = 45 km/h.","வேகம் = தொலைவு ÷ நேரம் = 540 ÷ 12 = 45 கி.மீ/மணி."]},{"id":539,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 88 in the ratio 3 : 8. Find the smaller share.","88 ஐ 3 : 8 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["26","26"],["29","29"],["34","34"],["24","24"]],"answer":3,"explanation":["Smaller share = 88 × 3/(3+8) = 24.","சிறிய பங்கு = 88 × 3/(3+8) = 24."]},{"id":540,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 10 and 19.","10 மற்றும் 19 இன் மீ.பொ.வ. காண்க."],"options":[["1","1"],["4","4"],["2","2"],["11","11"]],"answer":0,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":541,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 15 and 4.","15 மற்றும் 4 இன் மீ.பொ.ம. காண்க."],"options":[["62","62"],["65","65"],["60","60"],["120","120"]],"answer":2,"explanation":["LCM = product ÷ HCF = 60 ÷ 1 = 60.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 60 ÷ 1 = 60."]},{"id":542,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹2200 is sold for ₹2640. Find the profit percentage.","₹2200 க்கு வாங்கிய பொருள் ₹2640 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["30","30"],["21","21"],["19","19"],["20","20"]],"answer":3,"explanation":["Profit = ₹440. Profit% = 440 × 100 / 2200 = 20%.","இலாபம் = ₹440. இலாப% = 440 × 100 / 2200 = 20%."]},{"id":543,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 58° and 27°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 58°, 27°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["97","97"],["98","98"],["95","95"],["94","94"]],"answer":2,"explanation":["180 − 58 − 27 = 95°.","180 − 58 − 27 = 95°."]},{"id":544,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 41°, in degrees.","41° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["149","149"],["142","142"],["139","139"],["140","140"]],"answer":2,"explanation":["Supplementary angles sum to 180°. 180 − 41 = 139°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 41 = 139°."]},{"id":545,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Chlorophyll”?","“பச்சையம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The conversion of a liquid into vapour at its surface","திரவம் அதன் பரப்பில் ஆவியாக மாறுதல்"],["The mineral required to make thyroid hormones","தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது"],["The green pigment that absorbs light for photosynthesis","ஒளிச்சேர்க்கைக்காக ஒளியை உறிஞ்சும் பச்சை நிறமி"],["The vitamin whose deficiency causes scurvy","குறைபாட்டால் ஸ்கர்வி நோயை ஏற்படுத்தும் வைட்டமின்"]],"answer":2,"explanation":["Chlorophyll: The green pigment that absorbs light for photosynthesis.","பச்சையம்: ஒளிச்சேர்க்கைக்காக ஒளியை உறிஞ்சும் பச்சை நிறமி."]},{"id":546,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Stomata”?","“இலைத்துளைகள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The SI unit of power","திறனின் SI அலகு"],["The SI unit of frequency","அதிர்வெண்ணின் SI அலகு"],["Tiny pores on leaves that allow gas exchange","இலைகளில் வாயுப் பரிமாற்றத்திற்கு உதவும் சிறிய துளைகள்"],["The SI unit of electric potential difference","மின்னழுத்த வேறுபாட்டின் SI அலகு"]],"answer":2,"explanation":["Stomata: Tiny pores on leaves that allow gas exchange.","இலைத்துளைகள்: இலைகளில் வாயுப் பரிமாற்றத்திற்கு உதவும் சிறிய துளைகள்."]},{"id":547,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Xylem”?","“சைலம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The main site of absorption of digested nutrients in humans","மனிதரில் செரிக்கப்பட்ட ஊட்டச்சத்துகள் உறிஞ்சப்படும் முக்கிய இடம்"],["Fusion of male and female gametes","ஆண் மற்றும் பெண் இனச்செல்களின் இணைவு"],["Plant tissue that transports water and minerals from roots","வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு"],["Transfer of pollen from anther to stigma","மகரந்தப்பையிலிருந்து சூலகமுடிக்கு மகரந்தம் மாற்றப்படுதல்"]],"answer":2,"explanation":["Xylem: Plant tissue that transports water and minerals from roots.","சைலம்: வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு."]},{"id":548,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Asia”?","“ஆசியா” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["An instrument used to measure atmospheric pressure","வளிமண்டல அழுத்தத்தை அளக்கப் பயன்படும் கருவி"],["The latitude circle at about 23.5° south","சுமார் 23.5° தென் அட்சத்தில் அமைந்துள்ள வட்டம்"],["The largest continent by land area","நிலப்பரப்பில் மிகப்பெரிய கண்டம்"],["An elevated region with a relatively flat top","ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி"]],"answer":2,"explanation":["Asia: The largest continent by land area.","ஆசியா: நிலப்பரப்பில் மிகப்பெரிய கண்டம்."]},{"id":549,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Australia”?","“ஆஸ்திரேலியா” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The Mauryan emperor associated with the Kalinga War","கலிங்கப் போருடன் தொடர்புடைய மௌரியப் பேரரசர்"],["Angular distance east or west of the Prime Meridian","முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு"],["The smallest of the seven continents","ஏழு கண்டங்களில் மிகச்சிறிய கண்டம்"],["The largest ocean on Earth","புவியின் மிகப்பெரிய பெருங்கடல்"]],"answer":2,"explanation":["Australia: The smallest of the seven continents.","ஆஸ்திரேலியா: ஏழு கண்டங்களில் மிகச்சிறிய கண்டம்."]},{"id":550,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 44 students, a student is in position 16 from the front. Find the position from the back.","44 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 16 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["30","30"],["34","34"],["58","58"],["29","29"]],"answer":3,"explanation":["Position from back = 44 − 16 + 1 = 29.","பின்னிருந்து இடம் = 44 − 16 + 1 = 29."]},{"id":551,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 31 m north, 10 m east, 5 m south and 10 m west. How far are you from the start, in metres?","31 மீ வடக்கு, 10 மீ கிழக்கு, 5 மீ தெற்கு, 10 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["31","31"],["36","36"],["28","28"],["26","26"]],"answer":3,"explanation":["East and west cancel. Net northward distance = 31 − 5 = 26 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 31 − 5 = 26 மீ."]},{"id":552,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 12 km east and then 16 km north. Find the straight-line distance from the start in km.","12 கி.மீ கிழக்கிலும் பின்னர் 16 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["30","30"],["22","22"],["20","20"],["25","25"]],"answer":2,"explanation":["Pythagoras: √(12² + 16²) = 20 km.","பிதாகரஸ் தேற்றம்: √(12² + 16²) = 20 கி.மீ."]},{"id":553,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 8 → 72, then 28 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 8 → 72 எனில் 28 → ?"],"options":[["812","812"],["813","813"],["822","822"],["811","811"]],"answer":0,"explanation":["28 × (28 + 1) = 812.","28 × (28 + 1) = 812."]},{"id":554,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 3 : 27 :: 16 : ?","மும்மடி விதியைப் பயன்படுத்துக: 3 : 27 :: 16 : ?"],"options":[["4096","4096"],["4097","4097"],["4106","4106"],["8192","8192"]],"answer":0,"explanation":["3³ = 27, so 16³ = 4096.","3³ = 27; எனவே 16³ = 4096."]},{"id":555,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 7 places forward in the alphabet (wrap Z to A). Code GAME.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 7 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). GAME இன் குறியீடு என்ன?"],"options":[["OIUM","OIUM"],["MGSK","MGSK"],["NHTL","NHTL"],["PJVN","PJVN"]],"answer":2,"explanation":["Each letter advances by 7: G → N, A → H, M → T, E → L","ஒவ்வோர் எழுத்தும் 7 இடங்கள் முன்னேறும்: G → N, A → H, M → T, E → L"]},{"id":556,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in SEED.","A = 1, B = 2, …, Z = 26 எனில், SEED என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["32","32"],["33","33"],["35","35"],["43","43"]],"answer":1,"explanation":["19 + 5 + 5 + 4 = 33.","19 + 5 + 5 + 4 = 33."]},{"id":557,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Sunday. What day will it be after 14 days?","இன்று ஞாயிறு. 14 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Monday","திங்கள்"],["Sunday","ஞாயிறு"],["Tuesday","செவ்வாய்"],["Wednesday","புதன்"]],"answer":1,"explanation":["14 ÷ 7 leaves remainder 0. Move 0 days from Sunday: Sunday.","14 ஐ 7 ஆல் வகுக்க மீதி 0. ஞாயிறு கிழமையிலிருந்து 0 நாட்கள் நகர்ந்தால் ஞாயிறு."]},{"id":558,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 24 students shakes hands once with every other student. How many handshakes occur?","24 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["277","277"],["276","276"],["279","279"],["275","275"]],"answer":1,"explanation":["Each pair is counted once: 24 × 23 ÷ 2 = 276.","ஒவ்வொரு இணையும் ஒருமுறை: 24 × 23 ÷ 2 = 276."]},{"id":559,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 32 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 32 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["107","107"],["100","100"],["97","97"],["98","98"]],"answer":2,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 31 = 97.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 31 = 97."]},{"id":560,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 5, 8, 12, 17, 23, ?","நிறைவு செய்க: 5, 8, 12, 17, 23, ?"],"options":[["60","60"],["33","33"],["29","29"],["30","30"]],"answer":3,"explanation":["Differences increase by 1: 3, 4, 5, 6, 7. Next = 30.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 3, 4, 5, 6, 7. அடுத்த எண் 30."]},{"id":561,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 24, 26, 50, 76, 126, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 24, 26, 50, 76, 126, ?"],"options":[["404","404"],["203","203"],["207","207"],["202","202"]],"answer":3,"explanation":["76 + 126 = 202.","76 + 126 = 202."]},{"id":562,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 3/7 + 5/7.","கூட்டிச் சுருக்குக: 3/7 + 5/7."],"options":[["9/7","9/7"],["10/7","10/7"],["11/7","11/7"],["8/7","8/7"]],"answer":3,"explanation":["(3 + 5)/7 = 8/7 = 8/7.","(3 + 5)/7 = 8/7 = 8/7."]},{"id":563,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 4 red and 6 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 4 சிவப்பு, 6 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["7/13","7/13"],["1/2","1/2"],["2/5","2/5"],["5/11","5/11"]],"answer":2,"explanation":["Favourable outcomes / total = 4/10 = 2/5.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 4/10 = 2/5."]},{"id":564,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 10% of 740.","740 இல் 10% காண்க."],"options":[["76","76"],["74","74"],["79","79"],["84","84"]],"answer":1,"explanation":["740 × 10 / 100 = 74.","740 × 10 / 100 = 74."]},{"id":565,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹3800. Find the price after a 25% discount, in rupees.","குறித்த விலை ₹3800. 25% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["5700","5700"],["2850","2850"],["2853","2853"],["2860","2860"]],"answer":1,"explanation":["Discount = ₹950. Pay 3800 − 950 = ₹2850.","தள்ளுபடி = ₹950. செலுத்துவது 3800 − 950 = ₹2850."]},{"id":566,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹3400 at 10% per year for 5 years.","₹3400 க்கு ஆண்டுக்கு 10% வீதம் 5 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["1710","1710"],["1700","1700"],["1701","1701"],["1703","1703"]],"answer":1,"explanation":["PRT/100 = 3400 × 10 × 5 / 100 = ₹1700.","PRT/100 = 3400 × 10 × 5 / 100 = ₹1700."]},{"id":567,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 9x + 13 = 121.","x காண்க: 9x + 13 = 121."],"options":[["14","14"],["24","24"],["22","22"],["12","12"]],"answer":3,"explanation":["x = (121 − 13) ÷ 9 = 12.","x = (121 − 13) ÷ 9 = 12."]},{"id":568,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 23 cm long and 17 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 23 செ.மீ, அகலம் 17 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["390","390"],["401","401"],["391","391"],["782","782"]],"answer":2,"explanation":["Area = length × width = 23 × 17 = 391 cm².","பரப்பளவு = நீளம் × அகலம் = 23 × 17 = 391 ச.செ.மீ."]},{"id":569,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 14 m and 12 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 14 மீ மற்றும் 12 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["55","55"],["53","53"],["52","52"],["62","62"]],"answer":2,"explanation":["Perimeter = 2(14 + 12) = 52 m.","சுற்றளவு = 2(14 + 12) = 52 மீ."]},{"id":570,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Phloem”?","“புளோயம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Plant tissue that transports prepared food","தயாரிக்கப்பட்ட உணவை எடுத்துச் செல்லும் தாவரத் திசு"],["The SI unit of power","திறனின் SI அலகு"],["The mineral required to make thyroid hormones","தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது"],["The change of a gas or vapour into a liquid","வாயு அல்லது ஆவி திரவமாக மாறுதல்"]],"answer":0,"explanation":["Phloem: Plant tissue that transports prepared food.","புளோயம்: தயாரிக்கப்பட்ட உணவை எடுத்துச் செல்லும் தாவரத் திசு."]},{"id":571,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Root hairs”?","“வேர்த்தூவிகள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Root extensions that increase the surface area for absorption","உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்"],["The mineral essential for haemoglobin formation","ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது"],["The SI unit of electric potential difference","மின்னழுத்த வேறுபாட்டின் SI அலகு"],["The gas that makes up the largest fraction of dry air","உலர் காற்றில் மிக அதிகப் பங்கு வகிக்கும் வாயு"]],"answer":0,"explanation":["Root hairs: Root extensions that increase the surface area for absorption.","வேர்த்தூவிகள்: உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்."]},{"id":572,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Transpiration”?","“நீராவிப்போக்கு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The SI unit of force","விசையின் SI அலகு"],["The selectively permeable boundary of a cell","தேர்ந்தெடுத்துப் பொருட்களை அனுமதிக்கும் செல்லின் எல்லை"],["Loss of water as vapour from aerial parts of plants","தாவரத்தின் தரைக்கு மேலுள்ள பகுதிகளிலிருந்து நீர் ஆவியாக வெளியேறுதல்"],["A fluid-filled cell compartment used for storage","சேமிப்பிற்கு உதவும் திரவம் நிரம்பிய செல் பகுதி"]],"answer":2,"explanation":["Transpiration: Loss of water as vapour from aerial parts of plants.","நீராவிப்போக்கு: தாவரத்தின் தரைக்கு மேலுள்ள பகுதிகளிலிருந்து நீர் ஆவியாக வெளியேறுதல்."]},{"id":573,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Pacific Ocean”?","“பசிபிக் பெருங்கடல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The place in Amritsar where a massacre occurred in 1919","1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்"],["Land surrounded by water on three sides","மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்"],["An instrument used to show wind direction","காற்று வீசும் திசையைக் காட்டும் கருவி"],["The largest ocean on Earth","புவியின் மிகப்பெரிய பெருங்கடல்"]],"answer":3,"explanation":["Pacific Ocean: The largest ocean on Earth.","பசிபிக் பெருங்கடல்: புவியின் மிகப்பெரிய பெருங்கடல்."]},{"id":574,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Arctic Ocean”?","“ஆர்க்டிக் பெருங்கடல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The smallest of the seven continents","ஏழு கண்டங்களில் மிகச்சிறிய கண்டம்"],["The long-term pattern of weather in a region","ஒரு பகுதியில் நீண்ட காலமாக நிலவும் வானிலையின் அமைப்பு"],["The smallest of the five oceans","ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்"],["Earth’s movement around its own axis","புவி தனது அச்சில் சுழலும் இயக்கம்"]],"answer":2,"explanation":["Arctic Ocean: The smallest of the five oceans.","ஆர்க்டிக் பெருங்கடல்: ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்."]},{"id":575,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 33, 36, 39, 42, 45, …","அடுத்த எண்ணைக் காண்க: 33, 36, 39, 42, 45, …"],"options":[["48","48"],["47","47"],["96","96"],["50","50"]],"answer":0,"explanation":["Add 3 each time. 45 + 3 = 48.","ஒவ்வொரு முறையும் 3 கூட்டுக. 45 + 3 = 48."]},{"id":576,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 14, 28, 56, 112, ?","தொடரை நிறைவு செய்க: 14, 28, 56, 112, ?"],"options":[["223","223"],["448","448"],["224","224"],["225","225"]],"answer":2,"explanation":["Double each term: 112 × 2 = 224.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 112 × 2 = 224."]},{"id":577,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 33, 68, 138, 278, ?","அடுத்த உறுப்பைக் காண்க: 33, 68, 138, 278, ?"],"options":[["1116","1116"],["563","563"],["558","558"],["559","559"]],"answer":2,"explanation":["Multiply by 2, then add 2: 278 × 2 + 2 = 558.","2 ஆல் பெருக்கி 2 கூட்டுக: 278 × 2 + 2 = 558."]},{"id":578,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 22, 25, ?, 31, 34","விடுபட்ட எண்ணைக் காண்க: 22, 25, ?, 31, 34"],"options":[["38","38"],["28","28"],["33","33"],["29","29"]],"answer":1,"explanation":["The common difference is 3. 25 + 3 = 28.","பொது வித்தியாசம் 3. 25 + 3 = 28."]},{"id":579,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 100, 121, 144, 169, ?","தொடர்க: 100, 121, 144, 169, ?"],"options":[["197","197"],["196","196"],["199","199"],["198","198"]],"answer":1,"explanation":["These are squares of 10, 11, 12, 13. Next: 14² = 196.","இவை 10, 11, 12, 13 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 14² = 196."]},{"id":580,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 24 from the front and position 7 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 24 ஆவது, பின்னிருந்து 7 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["32","32"],["40","40"],["31","31"],["30","30"]],"answer":3,"explanation":["Total = 24 + 7 − 1 = 30; the student is counted only once.","மொத்தம் = 24 + 7 − 1 = 30; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":581,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 56 students, a student is in position 22 from the front. Find the position from the back.","56 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 22 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["45","45"],["35","35"],["36","36"],["38","38"]],"answer":1,"explanation":["Position from back = 56 − 22 + 1 = 35.","பின்னிருந்து இடம் = 56 − 22 + 1 = 35."]},{"id":582,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 17 m north, 23 m east, 2 m south and 23 m west. How far are you from the start, in metres?","17 மீ வடக்கு, 23 மீ கிழக்கு, 2 மீ தெற்கு, 23 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["16","16"],["15","15"],["30","30"],["25","25"]],"answer":1,"explanation":["East and west cancel. Net northward distance = 17 − 2 = 15 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 17 − 2 = 15 மீ."]},{"id":583,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 24 km east and then 32 km north. Find the straight-line distance from the start in km.","24 கி.மீ கிழக்கிலும் பின்னர் 32 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["43","43"],["41","41"],["42","42"],["40","40"]],"answer":3,"explanation":["Pythagoras: √(24² + 32²) = 40 km.","பிதாகரஸ் தேற்றம்: √(24² + 32²) = 40 கி.மீ."]},{"id":584,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 11 → 132, then 21 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 11 → 132 எனில் 21 → ?"],"options":[["462","462"],["461","461"],["467","467"],["464","464"]],"answer":0,"explanation":["21 × (21 + 1) = 462.","21 × (21 + 1) = 462."]},{"id":585,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 7 : 343 :: 17 : ?","மும்மடி விதியைப் பயன்படுத்துக: 7 : 343 :: 17 : ?"],"options":[["4913","4913"],["4916","4916"],["4918","4918"],["4923","4923"]],"answer":0,"explanation":["7³ = 343, so 17³ = 4913.","7³ = 343; எனவே 17³ = 4913."]},{"id":586,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 3 places forward in the alphabet (wrap Z to A). Code READ.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 3 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). READ இன் குறியீடு என்ன?"],"options":[["WJFI","WJFI"],["VIEH","VIEH"],["TGCF","TGCF"],["UHDG","UHDG"]],"answer":3,"explanation":["Each letter advances by 3: R → U, E → H, A → D, D → G","ஒவ்வோர் எழுத்தும் 3 இடங்கள் முன்னேறும்: R → U, E → H, A → D, D → G"]},{"id":587,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 20 cm and height 6 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 20 செ.மீ, உயரம் 6 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["60","60"],["65","65"],["59","59"],["120","120"]],"answer":0,"explanation":["Area = ½ × 20 × 6 = 60 cm².","பரப்பளவு = ½ × 20 × 6 = 60 ச.செ.மீ."]},{"id":588,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 15 cm × 6 cm × 18 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 15 செ.மீ × 6 செ.மீ × 18 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["1623","1623"],["1630","1630"],["1621","1621"],["1620","1620"]],"answer":3,"explanation":["Volume = length × breadth × height = 15 × 6 × 18 = 1620 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 15 × 6 × 18 = 1620 க.செ.மீ."]},{"id":589,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 35, 46, 57, 68, 79.","35, 46, 57, 68, 79 ஆகியவற்றின் சராசரி காண்க."],"options":[["58","58"],["60","60"],["57","57"],["62","62"]],"answer":2,"explanation":["Sum ÷ count = 285 ÷ 5 = 57.","கூடுதல் ÷ எண்ணிக்கை = 285 ÷ 5 = 57."]},{"id":590,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 245 km in 5 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 5 மணி நேரத்தில் 245 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["52","52"],["50","50"],["49","49"],["59","59"]],"answer":2,"explanation":["Speed = distance ÷ time = 245 ÷ 5 = 49 km/h.","வேகம் = தொலைவு ÷ நேரம் = 245 ÷ 5 = 49 கி.மீ/மணி."]},{"id":591,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 608 in the ratio 8 : 11. Find the smaller share.","608 ஐ 8 : 11 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["256","256"],["255","255"],["259","259"],["512","512"]],"answer":0,"explanation":["Smaller share = 608 × 8/(8+11) = 256.","சிறிய பங்கு = 608 × 8/(8+11) = 256."]},{"id":592,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 13 and 24.","13 மற்றும் 24 இன் மீ.பொ.வ. காண்க."],"options":[["2","2"],["1","1"],["3","3"],["6","6"]],"answer":1,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":593,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 32 and 14.","32 மற்றும் 14 இன் மீ.பொ.ம. காண்க."],"options":[["227","227"],["448","448"],["224","224"],["234","234"]],"answer":2,"explanation":["LCM = product ÷ HCF = 448 ÷ 2 = 224.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 448 ÷ 2 = 224."]},{"id":594,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹2200 is sold for ₹2640. Find the profit percentage.","₹2200 க்கு வாங்கிய பொருள் ₹2640 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["30","30"],["23","23"],["21","21"],["20","20"]],"answer":3,"explanation":["Profit = ₹440. Profit% = 440 × 100 / 2200 = 20%.","இலாபம் = ₹440. இலாப% = 440 × 100 / 2200 = 20%."]},{"id":595,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Germination”?","“முளைத்தல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Blood vessels that carry blood away from the heart","இதயத்திலிருந்து இரத்தத்தை வெளியே எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"],["The mineral required to make thyroid hormones","தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது"],["Heat transfer that can occur through a vacuum","வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்"],["The development of a seed into a seedling","விதை ஒரு நாற்றாக வளரத் தொடங்கும் நிகழ்வு"]],"answer":3,"explanation":["Germination: The development of a seed into a seedling.","முளைத்தல்: விதை ஒரு நாற்றாக வளரத் தொடங்கும் நிகழ்வு."]},{"id":596,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Pollination”?","“மகரந்தச் சேர்க்கை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Transfer of pollen from anther to stigma","மகரந்தப்பையிலிருந்து சூலகமுடிக்கு மகரந்தம் மாற்றப்படுதல்"],["The SI unit of pressure","அழுத்தத்தின் SI அலகு"],["Heat transfer that can occur through a vacuum","வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்"],["The change of a solid into a liquid","திடப்பொருள் திரவமாக மாறுதல்"]],"answer":0,"explanation":["Pollination: Transfer of pollen from anther to stigma.","மகரந்தச் சேர்க்கை: மகரந்தப்பையிலிருந்து சூலகமுடிக்கு மகரந்தம் மாற்றப்படுதல்."]},{"id":597,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Fertilisation”?","“கருவுறுதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The cellular structure responsible for protein synthesis","புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு"],["Plant tissue that transports prepared food","தயாரிக்கப்பட்ட உணவை எடுத்துச் செல்லும் தாவரத் திசு"],["Plant tissue that transports water and minerals from roots","வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு"],["Fusion of male and female gametes","ஆண் மற்றும் பெண் இனச்செல்களின் இணைவு"]],"answer":3,"explanation":["Fertilisation: Fusion of male and female gametes.","கருவுறுதல்: ஆண் மற்றும் பெண் இனச்செல்களின் இணைவு."]},{"id":598,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Equator”?","“நிலநடுக்கோடு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Land surrounded by water on three sides","மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்"],["The reference meridian at 0° longitude","0° தீர்க்கத்தில் அமைந்துள்ள ஆதாரத் தீர்க்கக்கோடு"],["An instrument used to measure atmospheric pressure","வளிமண்டல அழுத்தத்தை அளக்கப் பயன்படும் கருவி"],["The imaginary circle at 0° latitude","0° அட்சத்தில் அமைந்துள்ள கற்பனை வட்டம்"]],"answer":3,"explanation":["Equator: The imaginary circle at 0° latitude.","நிலநடுக்கோடு: 0° அட்சத்தில் அமைந்துள்ள கற்பனை வட்டம்."]},{"id":599,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Prime Meridian”?","“முதன்மை தீர்க்கக்கோடு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["An instrument used to measure rainfall","மழையளவை அளக்கப் பயன்படும் கருவி"],["The reference meridian at 0° longitude","0° தீர்க்கத்தில் அமைந்துள்ள ஆதாரத் தீர்க்கக்கோடு"],["Earth’s movement around its own axis","புவி தனது அச்சில் சுழலும் இயக்கம்"],["Land surrounded by water on all sides","அனைத்துப் பக்கங்களிலும் நீரால் சூழப்பட்ட நிலம்"]],"answer":1,"explanation":["Prime Meridian: The reference meridian at 0° longitude.","முதன்மை தீர்க்கக்கோடு: 0° தீர்க்கத்தில் அமைந்துள்ள ஆதாரத் தீர்க்கக்கோடு."]},{"id":600,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in WIND.","A = 1, B = 2, …, Z = 26 எனில், WIND என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["51","51"],["49","49"],["60","60"],["50","50"]],"answer":3,"explanation":["23 + 9 + 14 + 4 = 50.","23 + 9 + 14 + 4 = 50."]},{"id":601,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Sunday. What day will it be after 20 days?","இன்று ஞாயிறு. 20 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Saturday","சனி"],["Tuesday","செவ்வாய்"],["Monday","திங்கள்"],["Sunday","ஞாயிறு"]],"answer":0,"explanation":["20 ÷ 7 leaves remainder 6. Move 6 days from Sunday: Saturday.","20 ஐ 7 ஆல் வகுக்க மீதி 6. ஞாயிறு கிழமையிலிருந்து 6 நாட்கள் நகர்ந்தால் சனி."]},{"id":602,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 20 students shakes hands once with every other student. How many handshakes occur?","20 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["190","190"],["189","189"],["380","380"],["193","193"]],"answer":0,"explanation":["Each pair is counted once: 20 × 19 ÷ 2 = 190.","ஒவ்வொரு இணையும் ஒருமுறை: 20 × 19 ÷ 2 = 190."]},{"id":603,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 27 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 27 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["85","85"],["82","82"],["81","81"],["83","83"]],"answer":1,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 26 = 82.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 26 = 82."]},{"id":604,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 6, 10, 15, 21, 28, ?","நிறைவு செய்க: 6, 10, 15, 21, 28, ?"],"options":[["36","36"],["35","35"],["37","37"],["41","41"]],"answer":0,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 36.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 36."]},{"id":605,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 27, 34, 61, 95, 156, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 27, 34, 61, 95, 156, ?"],"options":[["251","251"],["253","253"],["256","256"],["252","252"]],"answer":0,"explanation":["95 + 156 = 251.","95 + 156 = 251."]},{"id":606,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 19, 27, 35, 43, 51, …","அடுத்த எண்ணைக் காண்க: 19, 27, 35, 43, 51, …"],"options":[["69","69"],["118","118"],["60","60"],["59","59"]],"answer":3,"explanation":["Add 8 each time. 51 + 8 = 59.","ஒவ்வொரு முறையும் 8 கூட்டுக. 51 + 8 = 59."]},{"id":607,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 22, 44, 88, 176, ?","தொடரை நிறைவு செய்க: 22, 44, 88, 176, ?"],"options":[["351","351"],["357","357"],["352","352"],["704","704"]],"answer":2,"explanation":["Double each term: 176 × 2 = 352.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 176 × 2 = 352."]},{"id":608,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 33, 72, 150, 306, ?","அடுத்த உறுப்பைக் காண்க: 33, 72, 150, 306, ?"],"options":[["623","623"],["618","618"],["628","628"],["621","621"]],"answer":1,"explanation":["Multiply by 2, then add 6: 306 × 2 + 6 = 618.","2 ஆல் பெருக்கி 6 கூட்டுக: 306 × 2 + 6 = 618."]},{"id":609,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 15, 24, ?, 42, 51","விடுபட்ட எண்ணைக் காண்க: 15, 24, ?, 42, 51"],"options":[["43","43"],["66","66"],["34","34"],["33","33"]],"answer":3,"explanation":["The common difference is 9. 24 + 9 = 33.","பொது வித்தியாசம் 9. 24 + 9 = 33."]},{"id":610,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 9, 16, 25, 36, ?","தொடர்க: 9, 16, 25, 36, ?"],"options":[["49","49"],["48","48"],["50","50"],["98","98"]],"answer":0,"explanation":["These are squares of 3, 4, 5, 6. Next: 7² = 49.","இவை 3, 4, 5, 6 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 7² = 49."]},{"id":611,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 27 from the front and position 23 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 27 ஆவது, பின்னிருந்து 23 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["54","54"],["98","98"],["49","49"],["59","59"]],"answer":2,"explanation":["Total = 27 + 23 − 1 = 49; the student is counted only once.","மொத்தம் = 27 + 23 − 1 = 49; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":612,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 29° and 66°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 29°, 66°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["85","85"],["87","87"],["86","86"],["170","170"]],"answer":0,"explanation":["180 − 29 − 66 = 85°.","180 − 29 − 66 = 85°."]},{"id":613,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 37°, in degrees.","37° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["144","144"],["143","143"],["153","153"],["145","145"]],"answer":1,"explanation":["Supplementary angles sum to 180°. 180 − 37 = 143°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 37 = 143°."]},{"id":614,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 10/16 + 14/16.","கூட்டிச் சுருக்குக: 10/16 + 14/16."],"options":[["25/16","25/16"],["13/8","13/8"],["3/2","3/2"],["27/16","27/16"]],"answer":2,"explanation":["(10 + 14)/16 = 24/16 = 3/2.","(10 + 14)/16 = 24/16 = 3/2."]},{"id":615,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 9 red and 4 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 9 சிவப்பு, 4 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["3/4","3/4"],["11/15","11/15"],["9/13","9/13"],["5/7","5/7"]],"answer":2,"explanation":["Favourable outcomes / total = 9/13 = 9/13.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 9/13 = 9/13."]},{"id":616,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 25% of 440.","440 இல் 25% காண்க."],"options":[["110","110"],["112","112"],["120","120"],["113","113"]],"answer":0,"explanation":["440 × 25 / 100 = 110.","440 × 25 / 100 = 110."]},{"id":617,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹2600. Find the price after a 10% discount, in rupees.","குறித்த விலை ₹2600. 10% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["2340","2340"],["2345","2345"],["2339","2339"],["2343","2343"]],"answer":0,"explanation":["Discount = ₹260. Pay 2600 − 260 = ₹2340.","தள்ளுபடி = ₹260. செலுத்துவது 2600 − 260 = ₹2340."]},{"id":618,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹1800 at 3% per year for 3 years.","₹1800 க்கு ஆண்டுக்கு 3% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["163","163"],["162","162"],["161","161"],["165","165"]],"answer":1,"explanation":["PRT/100 = 1800 × 3 × 3 / 100 = ₹162.","PRT/100 = 1800 × 3 × 3 / 100 = ₹162."]},{"id":619,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 8x + 12 = 76.","x காண்க: 8x + 12 = 76."],"options":[["7","7"],["16","16"],["8","8"],["10","10"]],"answer":2,"explanation":["x = (76 − 12) ÷ 8 = 8.","x = (76 − 12) ÷ 8 = 8."]},{"id":620,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Ovary of a flower”?","“மலரின் சூலகப்பை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The green pigment that absorbs light for photosynthesis","ஒளிச்சேர்க்கைக்காக ஒளியை உறிஞ்சும் பச்சை நிறமி"],["Tiny air sacs in lungs where gas exchange occurs","நுரையீரலில் வாயுப் பரிமாற்றம் நடைபெறும் சிறிய காற்றுப் பைகள்"],["The vitamin whose deficiency can cause night blindness","குறைபாட்டால் மாலைக்கண் நோய் ஏற்படக்கூடிய வைட்டமின்"],["The floral part that usually develops into a fruit after fertilisation","கருவுறுதலுக்குப் பிறகு பொதுவாக கனியாக வளரும் மலரின் பகுதி"]],"answer":3,"explanation":["Ovary of a flower: The floral part that usually develops into a fruit after fertilisation.","மலரின் சூலகப்பை: கருவுறுதலுக்குப் பிறகு பொதுவாக கனியாக வளரும் மலரின் பகுதி."]},{"id":621,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Mitochondrion”?","“மைட்டோகாண்ட்ரியா” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The organelle where most aerobic cellular respiration takes place","பெரும்பாலான ஆக்சிஜன் சார்ந்த செல் சுவாசம் நடைபெறும் செல் நுண்ணுறுப்பு"],["Separating an insoluble solid from a liquid using a porous barrier","நுண்துளைத் தடுப்பால் கரையாத திடப்பொருளை திரவத்திலிருந்து பிரித்தல்"],["Blood cells chiefly involved in defence against infection","நோய்த்தொற்றுக்கு எதிரான பாதுகாப்பில் முதன்மையாக ஈடுபடும் இரத்த அணுக்கள்"],["Heat transfer through the bulk movement of a fluid","ஒரு பாய்மத்தின் ஒட்டுமொத்த இயக்கத்தால் வெப்பம் கடத்தப்படுதல்"]],"answer":0,"explanation":["Mitochondrion: The organelle where most aerobic cellular respiration takes place.","மைட்டோகாண்ட்ரியா: பெரும்பாலான ஆக்சிஜன் சார்ந்த செல் சுவாசம் நடைபெறும் செல் நுண்ணுறுப்பு."]},{"id":622,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Ribosome”?","“ரைபோசோம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The cellular structure responsible for protein synthesis","புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு"],["The organelle in green plant cells where photosynthesis occurs","பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு"],["The SI unit of electric potential difference","மின்னழுத்த வேறுபாட்டின் SI அலகு"],["Root extensions that increase the surface area for absorption","உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்"]],"answer":0,"explanation":["Ribosome: The cellular structure responsible for protein synthesis.","ரைபோசோம்: புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு."]},{"id":623,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Tropic of Cancer”?","“கடகரேகை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Wearing away and removal of material by moving agents such as water","நீர் போன்ற நகரும் காரணிகளால் பொருட்கள் தேய்ந்து அகற்றப்படுதல்"],["Rock formed from accumulated sediments","சேர்ந்த படிவுகளிலிருந்து உருவாகும் பாறை"],["The Mauryan emperor associated with the Kalinga War","கலிங்கப் போருடன் தொடர்புடைய மௌரியப் பேரரசர்"],["The latitude circle at about 23.5° north","சுமார் 23.5° வட அட்சத்தில் அமைந்துள்ள வட்டம்"]],"answer":3,"explanation":["Tropic of Cancer: The latitude circle at about 23.5° north.","கடகரேகை: சுமார் 23.5° வட அட்சத்தில் அமைந்துள்ள வட்டம்."]},{"id":624,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Tropic of Capricorn”?","“மகரரேகை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["A depositional landform that may develop at a river mouth","ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்"],["The Chola ruler who built the Brihadisvara Temple at Thanjavur","தஞ்சைப் பெரிய கோயிலைக் கட்டிய சோழ மன்னர்"],["The largest ocean on Earth","புவியின் மிகப்பெரிய பெருங்கடல்"],["The latitude circle at about 23.5° south","சுமார் 23.5° தென் அட்சத்தில் அமைந்துள்ள வட்டம்"]],"answer":3,"explanation":["Tropic of Capricorn: The latitude circle at about 23.5° south.","மகரரேகை: சுமார் 23.5° தென் அட்சத்தில் அமைந்துள்ள வட்டம்."]},{"id":625,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 27 students, a student is in position 11 from the front. Find the position from the back.","27 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 11 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["20","20"],["27","27"],["18","18"],["17","17"]],"answer":3,"explanation":["Position from back = 27 − 11 + 1 = 17.","பின்னிருந்து இடம் = 27 − 11 + 1 = 17."]},{"id":626,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 14 m north, 4 m east, 6 m south and 4 m west. How far are you from the start, in metres?","14 மீ வடக்கு, 4 மீ கிழக்கு, 6 மீ தெற்கு, 4 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["7","7"],["13","13"],["10","10"],["8","8"]],"answer":3,"explanation":["East and west cancel. Net northward distance = 14 − 6 = 8 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 14 − 6 = 8 மீ."]},{"id":627,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 12 km east and then 16 km north. Find the straight-line distance from the start in km.","12 கி.மீ கிழக்கிலும் பின்னர் 16 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["40","40"],["20","20"],["30","30"],["19","19"]],"answer":1,"explanation":["Pythagoras: √(12² + 16²) = 20 km.","பிதாகரஸ் தேற்றம்: √(12² + 16²) = 20 கி.மீ."]},{"id":628,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 4 → 20, then 17 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 4 → 20 எனில் 17 → ?"],"options":[["307","307"],["306","306"],["316","316"],["309","309"]],"answer":1,"explanation":["17 × (17 + 1) = 306.","17 × (17 + 1) = 306."]},{"id":629,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 3 : 27 :: 10 : ?","மும்மடி விதியைப் பயன்படுத்துக: 3 : 27 :: 10 : ?"],"options":[["1000","1000"],["1002","1002"],["1005","1005"],["2000","2000"]],"answer":0,"explanation":["3³ = 27, so 10³ = 1000.","3³ = 27; எனவே 10³ = 1000."]},{"id":630,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 2 places forward in the alphabet (wrap Z to A). Code PARK.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 2 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). PARK இன் குறியீடு என்ன?"],"options":[["RCTM","RCTM"],["QBSL","QBSL"],["TEVO","TEVO"],["SDUN","SDUN"]],"answer":0,"explanation":["Each letter advances by 2: P → R, A → C, R → T, K → M","ஒவ்வோர் எழுத்தும் 2 இடங்கள் முன்னேறும்: P → R, A → C, R → T, K → M"]},{"id":631,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in ROAD.","A = 1, B = 2, …, Z = 26 எனில், ROAD என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["41","41"],["39","39"],["38","38"],["43","43"]],"answer":2,"explanation":["18 + 15 + 1 + 4 = 38.","18 + 15 + 1 + 4 = 38."]},{"id":632,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Thursday. What day will it be after 51 days?","இன்று வியாழன். 51 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Tuesday","செவ்வாய்"],["Sunday","ஞாயிறு"],["Saturday","சனி"],["Monday","திங்கள்"]],"answer":2,"explanation":["51 ÷ 7 leaves remainder 2. Move 2 days from Thursday: Saturday.","51 ஐ 7 ஆல் வகுக்க மீதி 2. வியாழன் கிழமையிலிருந்து 2 நாட்கள் நகர்ந்தால் சனி."]},{"id":633,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 24 students shakes hands once with every other student. How many handshakes occur?","24 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["552","552"],["276","276"],["286","286"],["278","278"]],"answer":1,"explanation":["Each pair is counted once: 24 × 23 ÷ 2 = 276.","ஒவ்வொரு இணையும் ஒருமுறை: 24 × 23 ÷ 2 = 276."]},{"id":634,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 9 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 9 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["38","38"],["27","27"],["31","31"],["28","28"]],"answer":3,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 8 = 28.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 8 = 28."]},{"id":635,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 4, 8, 13, 19, 26, ?","நிறைவு செய்க: 4, 8, 13, 19, 26, ?"],"options":[["35","35"],["68","68"],["34","34"],["36","36"]],"answer":2,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 34.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 34."]},{"id":636,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 12, 17, 29, 46, 75, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 12, 17, 29, 46, 75, ?"],"options":[["121","121"],["122","122"],["124","124"],["126","126"]],"answer":0,"explanation":["46 + 75 = 121.","46 + 75 = 121."]},{"id":637,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 32 cm long and 6 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 32 செ.மீ, அகலம் 6 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["195","195"],["197","197"],["192","192"],["193","193"]],"answer":2,"explanation":["Area = length × width = 32 × 6 = 192 cm².","பரப்பளவு = நீளம் × அகலம் = 32 × 6 = 192 ச.செ.மீ."]},{"id":638,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 25 m and 3 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 25 மீ மற்றும் 3 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["58","58"],["57","57"],["112","112"],["56","56"]],"answer":3,"explanation":["Perimeter = 2(25 + 3) = 56 m.","சுற்றளவு = 2(25 + 3) = 56 மீ."]},{"id":639,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 48 cm and height 8 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 48 செ.மீ, உயரம் 8 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["384","384"],["194","194"],["193","193"],["192","192"]],"answer":3,"explanation":["Area = ½ × 48 × 8 = 192 cm².","பரப்பளவு = ½ × 48 × 8 = 192 ச.செ.மீ."]},{"id":640,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 32 cm × 16 cm × 7 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 32 செ.மீ × 16 செ.மீ × 7 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["3584","3584"],["3586","3586"],["3587","3587"],["3594","3594"]],"answer":0,"explanation":["Volume = length × breadth × height = 32 × 16 × 7 = 3584 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 32 × 16 × 7 = 3584 க.செ.மீ."]},{"id":641,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 22, 33, 44, 55, 66.","22, 33, 44, 55, 66 ஆகியவற்றின் சராசரி காண்க."],"options":[["46","46"],["45","45"],["88","88"],["44","44"]],"answer":3,"explanation":["Sum ÷ count = 220 ÷ 5 = 44.","கூடுதல் ÷ எண்ணிக்கை = 220 ÷ 5 = 44."]},{"id":642,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 440 km in 11 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 11 மணி நேரத்தில் 440 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["39","39"],["80","80"],["40","40"],["50","50"]],"answer":2,"explanation":["Speed = distance ÷ time = 440 ÷ 11 = 40 km/h.","வேகம் = தொலைவு ÷ நேரம் = 440 ÷ 11 = 40 கி.மீ/மணி."]},{"id":643,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 435 in the ratio 6 : 9. Find the smaller share.","435 ஐ 6 : 9 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["184","184"],["174","174"],["176","176"],["177","177"]],"answer":1,"explanation":["Smaller share = 435 × 6/(6+9) = 174.","சிறிய பங்கு = 435 × 6/(6+9) = 174."]},{"id":644,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 38 and 46.","38 மற்றும் 46 இன் மீ.பொ.வ. காண்க."],"options":[["4","4"],["2","2"],["5","5"],["1","1"]],"answer":1,"explanation":["Common factors: 1, 2. Greatest = 2.","பொதுக் காரணிகள்: 1, 2. மிகப்பெரியது 2."]},{"id":645,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Cell membrane”?","“செல் சவ்வு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The rigid outer layer outside the membrane in a plant cell","தாவரச் செல்லில் செல் சவ்விற்கு வெளியே உள்ள உறுதியான அடுக்கு"],["The selectively permeable boundary of a cell","தேர்ந்தெடுத்துப் பொருட்களை அனுமதிக்கும் செல்லின் எல்லை"],["Plant tissue that transports water and minerals from roots","வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு"],["A reaction between an acid and a base that forms salt and water","அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்"]],"answer":1,"explanation":["Cell membrane: The selectively permeable boundary of a cell.","செல் சவ்வு: தேர்ந்தெடுத்துப் பொருட்களை அனுமதிக்கும் செல்லின் எல்லை."]},{"id":646,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Cell wall”?","“செல்சுவர்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The change of a liquid into a solid","திரவம் திடப்பொருளாக மாறுதல்"],["The change of a gas or vapour into a liquid","வாயு அல்லது ஆவி திரவமாக மாறுதல்"],["The rigid outer layer outside the membrane in a plant cell","தாவரச் செல்லில் செல் சவ்விற்கு வெளியே உள்ள உறுதியான அடுக்கு"],["The SI unit of frequency","அதிர்வெண்ணின் SI அலகு"]],"answer":2,"explanation":["Cell wall: The rigid outer layer outside the membrane in a plant cell.","செல்சுவர்: தாவரச் செல்லில் செல் சவ்விற்கு வெளியே உள்ள உறுதியான அடுக்கு."]},{"id":647,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Chloroplast”?","“பசுங்கணிகம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The SI unit of electric potential difference","மின்னழுத்த வேறுபாட்டின் SI அலகு"],["Blood components that help in clotting","இரத்தம் உறைதலுக்கு உதவும் இரத்தக் கூறுகள்"],["The organelle in green plant cells where photosynthesis occurs","பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு"],["Corrosion of iron in the presence of oxygen and moisture","ஆக்சிஜன் மற்றும் ஈரப்பதத்தின் முன்னிலையில் இரும்பு அரித்தல்"]],"answer":2,"explanation":["Chloroplast: The organelle in green plant cells where photosynthesis occurs.","பசுங்கணிகம்: பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு."]},{"id":648,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Latitude”?","“அட்சம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Angular distance north or south of the Equator","நிலநடுக்கோட்டிலிருந்து வடக்கு அல்லது தெற்காக அளவிடப்படும் கோணத் தொலைவு"],["A depositional landform that may develop at a river mouth","ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்"],["The Chola ruler who built the Brihadisvara Temple at Thanjavur","தஞ்சைப் பெரிய கோயிலைக் கட்டிய சோழ மன்னர்"],["Land surrounded by water on three sides","மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்"]],"answer":0,"explanation":["Latitude: Angular distance north or south of the Equator.","அட்சம்: நிலநடுக்கோட்டிலிருந்து வடக்கு அல்லது தெற்காக அளவிடப்படும் கோணத் தொலைவு."]},{"id":649,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Longitude”?","“தீர்க்கம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The smallest of the seven continents","ஏழு கண்டங்களில் மிகச்சிறிய கண்டம்"],["Wearing away and removal of material by moving agents such as water","நீர் போன்ற நகரும் காரணிகளால் பொருட்கள் தேய்ந்து அகற்றப்படுதல்"],["The latitude circle at about 23.5° south","சுமார் 23.5° தென் அட்சத்தில் அமைந்துள்ள வட்டம்"],["Angular distance east or west of the Prime Meridian","முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு"]],"answer":3,"explanation":["Longitude: Angular distance east or west of the Prime Meridian.","தீர்க்கம்: முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு."]},{"id":650,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 21, 27, 33, 39, 45, …","அடுத்த எண்ணைக் காண்க: 21, 27, 33, 39, 45, …"],"options":[["51","51"],["102","102"],["53","53"],["50","50"]],"answer":0,"explanation":["Add 6 each time. 45 + 6 = 51.","ஒவ்வொரு முறையும் 6 கூட்டுக. 45 + 6 = 51."]},{"id":651,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 9, 18, 36, 72, ?","தொடரை நிறைவு செய்க: 9, 18, 36, 72, ?"],"options":[["144","144"],["154","154"],["143","143"],["149","149"]],"answer":0,"explanation":["Double each term: 72 × 2 = 144.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 72 × 2 = 144."]},{"id":652,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 20, 48, 104, 216, ?","அடுத்த உறுப்பைக் காண்க: 20, 48, 104, 216, ?"],"options":[["440","440"],["445","445"],["880","880"],["450","450"]],"answer":0,"explanation":["Multiply by 2, then add 8: 216 × 2 + 8 = 440.","2 ஆல் பெருக்கி 8 கூட்டுக: 216 × 2 + 8 = 440."]},{"id":653,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 34, 42, ?, 58, 66","விடுபட்ட எண்ணைக் காண்க: 34, 42, ?, 58, 66"],"options":[["60","60"],["51","51"],["50","50"],["53","53"]],"answer":2,"explanation":["The common difference is 8. 42 + 8 = 50.","பொது வித்தியாசம் 8. 42 + 8 = 50."]},{"id":654,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 784, 841, 900, 961, ?","தொடர்க: 784, 841, 900, 961, ?"],"options":[["1024","1024"],["1023","1023"],["1027","1027"],["2048","2048"]],"answer":0,"explanation":["These are squares of 28, 29, 30, 31. Next: 32² = 1024.","இவை 28, 29, 30, 31 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 32² = 1024."]},{"id":655,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 17 from the front and position 19 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 17 ஆவது, பின்னிருந்து 19 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["38","38"],["40","40"],["35","35"],["36","36"]],"answer":2,"explanation":["Total = 17 + 19 − 1 = 35; the student is counted only once.","மொத்தம் = 17 + 19 − 1 = 35; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":656,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 28 students, a student is in position 6 from the front. Find the position from the back.","28 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 6 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["23","23"],["24","24"],["26","26"],["22","22"]],"answer":0,"explanation":["Position from back = 28 − 6 + 1 = 23.","பின்னிருந்து இடம் = 28 − 6 + 1 = 23."]},{"id":657,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 17 m north, 16 m east, 5 m south and 16 m west. How far are you from the start, in metres?","17 மீ வடக்கு, 16 மீ கிழக்கு, 5 மீ தெற்கு, 16 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["15","15"],["12","12"],["17","17"],["13","13"]],"answer":1,"explanation":["East and west cancel. Net northward distance = 17 − 5 = 12 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 17 − 5 = 12 மீ."]},{"id":658,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 18 km east and then 24 km north. Find the straight-line distance from the start in km.","18 கி.மீ கிழக்கிலும் பின்னர் 24 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["31","31"],["33","33"],["30","30"],["32","32"]],"answer":2,"explanation":["Pythagoras: √(18² + 24²) = 30 km.","பிதாகரஸ் தேற்றம்: √(18² + 24²) = 30 கி.மீ."]},{"id":659,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 11 → 132, then 22 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 11 → 132 எனில் 22 → ?"],"options":[["508","508"],["516","516"],["507","507"],["506","506"]],"answer":3,"explanation":["22 × (22 + 1) = 506.","22 × (22 + 1) = 506."]},{"id":660,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 9 : 729 :: 12 : ?","மும்மடி விதியைப் பயன்படுத்துக: 9 : 729 :: 12 : ?"],"options":[["1729","1729"],["1727","1727"],["1728","1728"],["3456","3456"]],"answer":2,"explanation":["9³ = 729, so 12³ = 1728.","9³ = 729; எனவே 12³ = 1728."]},{"id":661,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 5 places forward in the alphabet (wrap Z to A). Code MATH.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 5 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). MATH இன் குறியீடு என்ன?"],"options":[["THAO","THAO"],["QEXL","QEXL"],["SGZN","SGZN"],["RFYM","RFYM"]],"answer":3,"explanation":["Each letter advances by 5: M → R, A → F, T → Y, H → M","ஒவ்வோர் எழுத்தும் 5 இடங்கள் முன்னேறும்: M → R, A → F, T → Y, H → M"]},{"id":662,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 5 and 12.","5 மற்றும் 12 இன் மீ.பொ.ம. காண்க."],"options":[["65","65"],["62","62"],["60","60"],["59","59"]],"answer":2,"explanation":["LCM = product ÷ HCF = 60 ÷ 1 = 60.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 60 ÷ 1 = 60."]},{"id":663,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹3300 is sold for ₹3630. Find the profit percentage.","₹3300 க்கு வாங்கிய பொருள் ₹3630 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["10","10"],["15","15"],["12","12"],["13","13"]],"answer":0,"explanation":["Profit = ₹330. Profit% = 330 × 100 / 3300 = 10%.","இலாபம் = ₹330. இலாப% = 330 × 100 / 3300 = 10%."]},{"id":664,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 79° and 26°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 79°, 26°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["78","78"],["85","85"],["75","75"],["76","76"]],"answer":2,"explanation":["180 − 79 − 26 = 75°.","180 − 79 − 26 = 75°."]},{"id":665,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 30°, in degrees.","30° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["160","160"],["155","155"],["300","300"],["150","150"]],"answer":3,"explanation":["Supplementary angles sum to 180°. 180 − 30 = 150°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 30 = 150°."]},{"id":666,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 5/15 + 14/15.","கூட்டிச் சுருக்குக: 5/15 + 14/15."],"options":[["19/15","19/15"],["22/15","22/15"],["7/5","7/5"],["4/3","4/3"]],"answer":0,"explanation":["(5 + 14)/15 = 19/15 = 19/15.","(5 + 14)/15 = 19/15 = 19/15."]},{"id":667,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 11 red and 6 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 11 சிவப்பு, 6 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["2/3","2/3"],["13/19","13/19"],["7/10","7/10"],["11/17","11/17"]],"answer":3,"explanation":["Favourable outcomes / total = 11/17 = 11/17.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 11/17 = 11/17."]},{"id":668,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 75% of 780.","780 இல் 75% காண்க."],"options":[["588","588"],["586","586"],["585","585"],["1170","1170"]],"answer":2,"explanation":["780 × 75 / 100 = 585.","780 × 75 / 100 = 585."]},{"id":669,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹2400. Find the price after a 25% discount, in rupees.","குறித்த விலை ₹2400. 25% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["1805","1805"],["1801","1801"],["1799","1799"],["1800","1800"]],"answer":3,"explanation":["Discount = ₹600. Pay 2400 − 600 = ₹1800.","தள்ளுபடி = ₹600. செலுத்துவது 2400 − 600 = ₹1800."]},{"id":670,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Vacuole”?","“நுண்குமிழ்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Organs that filter blood and form urine","இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்"],["Separation using vaporisation followed by condensation","ஆவியாக்குதலுக்குப் பின் ஆவி சுருங்குதலைப் பயன்படுத்திப் பிரித்தல்"],["A fluid-filled cell compartment used for storage","சேமிப்பிற்கு உதவும் திரவம் நிரம்பிய செல் பகுதி"],["Heat transfer through the bulk movement of a fluid","ஒரு பாய்மத்தின் ஒட்டுமொத்த இயக்கத்தால் வெப்பம் கடத்தப்படுதல்"]],"answer":2,"explanation":["Vacuole: A fluid-filled cell compartment used for storage.","நுண்குமிழ்: சேமிப்பிற்கு உதவும் திரவம் நிரம்பிய செல் பகுதி."]},{"id":671,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Platelets”?","“இரத்தத் தட்டுகள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The SI unit of force","விசையின் SI அலகு"],["Root extensions that increase the surface area for absorption","உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்"],["Blood components that help in clotting","இரத்தம் உறைதலுக்கு உதவும் இரத்தக் கூறுகள்"],["Tiny pores on leaves that allow gas exchange","இலைகளில் வாயுப் பரிமாற்றத்திற்கு உதவும் சிறிய துளைகள்"]],"answer":2,"explanation":["Platelets: Blood components that help in clotting.","இரத்தத் தட்டுகள்: இரத்தம் உறைதலுக்கு உதவும் இரத்தக் கூறுகள்."]},{"id":672,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “White blood cells”?","“வெள்ளையணுக்கள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The change of a solid into a liquid","திடப்பொருள் திரவமாக மாறுதல்"],["Blood cells chiefly involved in defence against infection","நோய்த்தொற்றுக்கு எதிரான பாதுகாப்பில் முதன்மையாக ஈடுபடும் இரத்த அணுக்கள்"],["Tiny pores on leaves that allow gas exchange","இலைகளில் வாயுப் பரிமாற்றத்திற்கு உதவும் சிறிய துளைகள்"],["The green pigment that absorbs light for photosynthesis","ஒளிச்சேர்க்கைக்காக ஒளியை உறிஞ்சும் பச்சை நிறமி"]],"answer":1,"explanation":["White blood cells: Blood cells chiefly involved in defence against infection.","வெள்ளையணுக்கள்: நோய்த்தொற்றுக்கு எதிரான பாதுகாப்பில் முதன்மையாக ஈடுபடும் இரத்த அணுக்கள்."]},{"id":673,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Rotation”?","“தற்சுழற்சி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Earth’s movement around its own axis","புவி தனது அச்சில் சுழலும் இயக்கம்"],["An instrument used to measure wind speed","காற்றின் வேகத்தை அளக்கப் பயன்படும் கருவி"],["An elevated region with a relatively flat top","ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி"],["Rock altered by heat and pressure without complete melting","முழுமையாக உருகாமல் வெப்பம் மற்றும் அழுத்தத்தால் மாறிய பாறை"]],"answer":0,"explanation":["Rotation: Earth’s movement around its own axis.","தற்சுழற்சி: புவி தனது அச்சில் சுழலும் இயக்கம்."]},{"id":674,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Revolution”?","“சுற்றிவருதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["A depositional landform that may develop at a river mouth","ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்"],["The laying down of material carried by water, wind or ice","நீர், காற்று அல்லது பனியால் எடுத்துச் செல்லப்பட்ட பொருட்கள் படியுதல்"],["An instrument used to measure rainfall","மழையளவை அளக்கப் பயன்படும் கருவி"],["Earth’s movement around the Sun","புவி சூரியனைச் சுற்றி வரும் இயக்கம்"]],"answer":3,"explanation":["Revolution: Earth’s movement around the Sun.","சுற்றிவருதல்: புவி சூரியனைச் சுற்றி வரும் இயக்கம்."]},{"id":675,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in PLANT.","A = 1, B = 2, …, Z = 26 எனில், PLANT என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["73","73"],["64","64"],["63","63"],["68","68"]],"answer":2,"explanation":["16 + 12 + 1 + 14 + 20 = 63.","16 + 12 + 1 + 14 + 20 = 63."]},{"id":676,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Thursday. What day will it be after 18 days?","இன்று வியாழன். 18 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Wednesday","புதன்"],["Tuesday","செவ்வாய்"],["Monday","திங்கள்"],["Thursday","வியாழன்"]],"answer":2,"explanation":["18 ÷ 7 leaves remainder 4. Move 4 days from Thursday: Monday.","18 ஐ 7 ஆல் வகுக்க மீதி 4. வியாழன் கிழமையிலிருந்து 4 நாட்கள் நகர்ந்தால் திங்கள்."]},{"id":677,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 25 students shakes hands once with every other student. How many handshakes occur?","25 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["600","600"],["299","299"],["301","301"],["300","300"]],"answer":3,"explanation":["Each pair is counted once: 25 × 24 ÷ 2 = 300.","ஒவ்வொரு இணையும் ஒருமுறை: 25 × 24 ÷ 2 = 300."]},{"id":678,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 33 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 33 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["99","99"],["105","105"],["110","110"],["100","100"]],"answer":3,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 32 = 100.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 32 = 100."]},{"id":679,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 4, 8, 13, 19, 26, ?","நிறைவு செய்க: 4, 8, 13, 19, 26, ?"],"options":[["33","33"],["35","35"],["39","39"],["34","34"]],"answer":3,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 34.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 34."]},{"id":680,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 4, 10, 14, 24, 38, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 4, 10, 14, 24, 38, ?"],"options":[["61","61"],["62","62"],["64","64"],["67","67"]],"answer":1,"explanation":["24 + 38 = 62.","24 + 38 = 62."]},{"id":681,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 33, 36, 39, 42, 45, …","அடுத்த எண்ணைக் காண்க: 33, 36, 39, 42, 45, …"],"options":[["51","51"],["47","47"],["48","48"],["49","49"]],"answer":2,"explanation":["Add 3 each time. 45 + 3 = 48.","ஒவ்வொரு முறையும் 3 கூட்டுக. 45 + 3 = 48."]},{"id":682,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 9, 18, 36, 72, ?","தொடரை நிறைவு செய்க: 9, 18, 36, 72, ?"],"options":[["144","144"],["154","154"],["147","147"],["146","146"]],"answer":0,"explanation":["Double each term: 72 × 2 = 144.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 72 × 2 = 144."]},{"id":683,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 25, 55, 115, 235, ?","அடுத்த உறுப்பைக் காண்க: 25, 55, 115, 235, ?"],"options":[["474","474"],["478","478"],["475","475"],["480","480"]],"answer":2,"explanation":["Multiply by 2, then add 5: 235 × 2 + 5 = 475.","2 ஆல் பெருக்கி 5 கூட்டுக: 235 × 2 + 5 = 475."]},{"id":684,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 30, 36, ?, 48, 54","விடுபட்ட எண்ணைக் காண்க: 30, 36, ?, 48, 54"],"options":[["41","41"],["42","42"],["84","84"],["47","47"]],"answer":1,"explanation":["The common difference is 6. 36 + 6 = 42.","பொது வித்தியாசம் 6. 36 + 6 = 42."]},{"id":685,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 529, 576, 625, 676, ?","தொடர்க: 529, 576, 625, 676, ?"],"options":[["731","731"],["739","739"],["732","732"],["729","729"]],"answer":3,"explanation":["These are squares of 23, 24, 25, 26. Next: 27² = 729.","இவை 23, 24, 25, 26 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 27² = 729."]},{"id":686,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 7 from the front and position 16 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 7 ஆவது, பின்னிருந்து 16 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["27","27"],["22","22"],["32","32"],["24","24"]],"answer":1,"explanation":["Total = 7 + 16 − 1 = 22; the student is counted only once.","மொத்தம் = 7 + 16 − 1 = 22; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":687,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹1100 at 9% per year for 2 years.","₹1100 க்கு ஆண்டுக்கு 9% வீதம் 2 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["199","199"],["197","197"],["198","198"],["201","201"]],"answer":2,"explanation":["PRT/100 = 1100 × 9 × 2 / 100 = ₹198.","PRT/100 = 1100 × 9 × 2 / 100 = ₹198."]},{"id":688,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 16x + 9 = 121.","x காண்க: 16x + 9 = 121."],"options":[["6","6"],["17","17"],["10","10"],["7","7"]],"answer":3,"explanation":["x = (121 − 9) ÷ 16 = 7.","x = (121 − 9) ÷ 16 = 7."]},{"id":689,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 34 cm long and 10 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 34 செ.மீ, அகலம் 10 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["341","341"],["340","340"],["345","345"],["680","680"]],"answer":1,"explanation":["Area = length × width = 34 × 10 = 340 cm².","பரப்பளவு = நீளம் × அகலம் = 34 × 10 = 340 ச.செ.மீ."]},{"id":690,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 23 m and 16 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 23 மீ மற்றும் 16 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["78","78"],["156","156"],["79","79"],["83","83"]],"answer":0,"explanation":["Perimeter = 2(23 + 16) = 78 m.","சுற்றளவு = 2(23 + 16) = 78 மீ."]},{"id":691,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 72 cm and height 7 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 72 செ.மீ, உயரம் 7 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["251","251"],["252","252"],["254","254"],["257","257"]],"answer":1,"explanation":["Area = ½ × 72 × 7 = 252 cm².","பரப்பளவு = ½ × 72 × 7 = 252 ச.செ.மீ."]},{"id":692,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 5 cm × 7 cm × 10 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 5 செ.மீ × 7 செ.மீ × 10 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["360","360"],["351","351"],["700","700"],["350","350"]],"answer":3,"explanation":["Volume = length × breadth × height = 5 × 7 × 10 = 350 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 5 × 7 × 10 = 350 க.செ.மீ."]},{"id":693,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 11, 17, 23, 29, 35.","11, 17, 23, 29, 35 ஆகியவற்றின் சராசரி காண்க."],"options":[["25","25"],["28","28"],["23","23"],["46","46"]],"answer":2,"explanation":["Sum ÷ count = 115 ÷ 5 = 23.","கூடுதல் ÷ எண்ணிக்கை = 115 ÷ 5 = 23."]},{"id":694,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 540 km in 9 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 9 மணி நேரத்தில் 540 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["70","70"],["65","65"],["60","60"],["62","62"]],"answer":2,"explanation":["Speed = distance ÷ time = 540 ÷ 9 = 60 km/h.","வேகம் = தொலைவு ÷ நேரம் = 540 ÷ 9 = 60 கி.மீ/மணி."]},{"id":695,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Arteries”?","“தமனிகள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Blood vessels that carry blood away from the heart","இதயத்திலிருந்து இரத்தத்தை வெளியே எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"],["The vitamin whose deficiency causes scurvy","குறைபாட்டால் ஸ்கர்வி நோயை ஏற்படுத்தும் வைட்டமின்"],["The force that opposes relative sliding between surfaces","பரப்புகளுக்கிடையேயான சார்பு சறுக்கல் இயக்கத்தை எதிர்க்கும் விசை"],["Root extensions that increase the surface area for absorption","உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்"]],"answer":0,"explanation":["Arteries: Blood vessels that carry blood away from the heart.","தமனிகள்: இதயத்திலிருந்து இரத்தத்தை வெளியே எடுத்துச் செல்லும் இரத்தக் குழாய்கள்."]},{"id":696,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Veins”?","“சிரைகள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Blood vessels that carry blood towards the heart","இதயத்தை நோக்கி இரத்தத்தை எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"],["The selectively permeable boundary of a cell","தேர்ந்தெடுத்துப் பொருட்களை அனுமதிக்கும் செல்லின் எல்லை"],["Corrosion of iron in the presence of oxygen and moisture","ஆக்சிஜன் மற்றும் ஈரப்பதத்தின் முன்னிலையில் இரும்பு அரித்தல்"],["The change of a liquid into a solid","திரவம் திடப்பொருளாக மாறுதல்"]],"answer":0,"explanation":["Veins: Blood vessels that carry blood towards the heart.","சிரைகள்: இதயத்தை நோக்கி இரத்தத்தை எடுத்துச் செல்லும் இரத்தக் குழாய்கள்."]},{"id":697,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Alveoli”?","“காற்று நுண்ணறைகள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Plant tissue that transports water and minerals from roots","வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு"],["Organs that filter blood and form urine","இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்"],["Tiny air sacs in lungs where gas exchange occurs","நுரையீரலில் வாயுப் பரிமாற்றம் நடைபெறும் சிறிய காற்றுப் பைகள்"],["The substance dissolved in a solvent to form a solution","கரைப்பானில் கரைந்து கரைசலை உருவாக்கும் பொருள்"]],"answer":2,"explanation":["Alveoli: Tiny air sacs in lungs where gas exchange occurs.","காற்று நுண்ணறைகள்: நுரையீரலில் வாயுப் பரிமாற்றம் நடைபெறும் சிறிய காற்றுப் பைகள்."]},{"id":698,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Weather”?","“வானிலை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The latitude circle at about 23.5° south","சுமார் 23.5° தென் அட்சத்தில் அமைந்துள்ள வட்டம்"],["An elevated region with a relatively flat top","ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி"],["Land surrounded by water on three sides","மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்"],["The atmospheric conditions at a place over a short period","ஓர் இடத்தில் குறுகிய காலத்தில் நிலவும் வளிமண்டல நிலை"]],"answer":3,"explanation":["Weather: The atmospheric conditions at a place over a short period.","வானிலை: ஓர் இடத்தில் குறுகிய காலத்தில் நிலவும் வளிமண்டல நிலை."]},{"id":699,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Climate”?","“காலநிலை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["An instrument used to measure rainfall","மழையளவை அளக்கப் பயன்படும் கருவி"],["The smallest of the seven continents","ஏழு கண்டங்களில் மிகச்சிறிய கண்டம்"],["The smallest of the five oceans","ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்"],["The long-term pattern of weather in a region","ஒரு பகுதியில் நீண்ட காலமாக நிலவும் வானிலையின் அமைப்பு"]],"answer":3,"explanation":["Climate: The long-term pattern of weather in a region.","காலநிலை: ஒரு பகுதியில் நீண்ட காலமாக நிலவும் வானிலையின் அமைப்பு."]},{"id":700,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 20 students, a student is in position 15 from the front. Find the position from the back.","20 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 15 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["6","6"],["7","7"],["16","16"],["9","9"]],"answer":0,"explanation":["Position from back = 20 − 15 + 1 = 6.","பின்னிருந்து இடம் = 20 − 15 + 1 = 6."]},{"id":701,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 24 m north, 12 m east, 7 m south and 12 m west. How far are you from the start, in metres?","24 மீ வடக்கு, 12 மீ கிழக்கு, 7 மீ தெற்கு, 12 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["17","17"],["34","34"],["20","20"],["18","18"]],"answer":0,"explanation":["East and west cancel. Net northward distance = 24 − 7 = 17 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 24 − 7 = 17 மீ."]},{"id":702,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 18 km east and then 24 km north. Find the straight-line distance from the start in km.","18 கி.மீ கிழக்கிலும் பின்னர் 24 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["31","31"],["29","29"],["32","32"],["30","30"]],"answer":3,"explanation":["Pythagoras: √(18² + 24²) = 30 km.","பிதாகரஸ் தேற்றம்: √(18² + 24²) = 30 கி.மீ."]},{"id":703,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 6 → 42, then 17 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 6 → 42 எனில் 17 → ?"],"options":[["309","309"],["311","311"],["305","305"],["306","306"]],"answer":3,"explanation":["17 × (17 + 1) = 306.","17 × (17 + 1) = 306."]},{"id":704,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 5 : 125 :: 10 : ?","மும்மடி விதியைப் பயன்படுத்துக: 5 : 125 :: 10 : ?"],"options":[["1000","1000"],["1001","1001"],["999","999"],["2000","2000"]],"answer":0,"explanation":["5³ = 125, so 10³ = 1000.","5³ = 125; எனவே 10³ = 1000."]},{"id":705,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 4 places forward in the alphabet (wrap Z to A). Code ROAD.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 4 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). ROAD இன் குறியீடு என்ன?"],"options":[["VSEH","VSEH"],["XUGJ","XUGJ"],["WTFI","WTFI"],["URDG","URDG"]],"answer":0,"explanation":["Each letter advances by 4: R → V, O → S, A → E, D → H","ஒவ்வோர் எழுத்தும் 4 இடங்கள் முன்னேறும்: R → V, O → S, A → E, D → H"]},{"id":706,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in RAIN.","A = 1, B = 2, …, Z = 26 எனில், RAIN என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["43","43"],["41","41"],["52","52"],["42","42"]],"answer":3,"explanation":["18 + 1 + 9 + 14 = 42.","18 + 1 + 9 + 14 = 42."]},{"id":707,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Tuesday. What day will it be after 85 days?","இன்று செவ்வாய். 85 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Saturday","சனி"],["Thursday","வியாழன்"],["Wednesday","புதன்"],["Friday","வெள்ளி"]],"answer":2,"explanation":["85 ÷ 7 leaves remainder 1. Move 1 days from Tuesday: Wednesday.","85 ஐ 7 ஆல் வகுக்க மீதி 1. செவ்வாய் கிழமையிலிருந்து 1 நாட்கள் நகர்ந்தால் புதன்."]},{"id":708,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 4 students shakes hands once with every other student. How many handshakes occur?","4 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["6","6"],["16","16"],["5","5"],["8","8"]],"answer":0,"explanation":["Each pair is counted once: 4 × 3 ÷ 2 = 6.","ஒவ்வொரு இணையும் ஒருமுறை: 4 × 3 ÷ 2 = 6."]},{"id":709,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 24 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 24 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["75","75"],["72","72"],["83","83"],["73","73"]],"answer":3,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 23 = 73.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 23 = 73."]},{"id":710,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 9, 13, 18, 24, 31, ?","நிறைவு செய்க: 9, 13, 18, 24, 31, ?"],"options":[["38","38"],["39","39"],["40","40"],["78","78"]],"answer":1,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 39.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 39."]},{"id":711,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 30, 38, 68, 106, 174, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 30, 38, 68, 106, 174, ?"],"options":[["280","280"],["290","290"],["281","281"],["282","282"]],"answer":0,"explanation":["106 + 174 = 280.","106 + 174 = 280."]},{"id":712,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 323 in the ratio 7 : 10. Find the smaller share.","323 ஐ 7 : 10 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["132","132"],["133","133"],["135","135"],["143","143"]],"answer":1,"explanation":["Smaller share = 323 × 7/(7+10) = 133.","சிறிய பங்கு = 323 × 7/(7+10) = 133."]},{"id":713,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 24 and 42.","24 மற்றும் 42 இன் மீ.பொ.வ. காண்க."],"options":[["8","8"],["12","12"],["7","7"],["6","6"]],"answer":3,"explanation":["Common factors: 1, 2, 3, 6. Greatest = 6.","பொதுக் காரணிகள்: 1, 2, 3, 6. மிகப்பெரியது 6."]},{"id":714,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 31 and 18.","31 மற்றும் 18 இன் மீ.பொ.ம. காண்க."],"options":[["563","563"],["558","558"],["560","560"],["561","561"]],"answer":1,"explanation":["LCM = product ÷ HCF = 558 ÷ 1 = 558.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 558 ÷ 1 = 558."]},{"id":715,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹3900 is sold for ₹4095. Find the profit percentage.","₹3900 க்கு வாங்கிய பொருள் ₹4095 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["4","4"],["5","5"],["7","7"],["15","15"]],"answer":1,"explanation":["Profit = ₹195. Profit% = 195 × 100 / 3900 = 5%.","இலாபம் = ₹195. இலாப% = 195 × 100 / 3900 = 5%."]},{"id":716,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 74° and 45°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 74°, 45°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["63","63"],["60","60"],["61","61"],["122","122"]],"answer":2,"explanation":["180 − 74 − 45 = 61°.","180 − 74 − 45 = 61°."]},{"id":717,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 10°, in degrees.","10° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["175","175"],["171","171"],["170","170"],["340","340"]],"answer":2,"explanation":["Supplementary angles sum to 180°. 180 − 10 = 170°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 10 = 170°."]},{"id":718,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 2/6 + 3/6.","கூட்டிச் சுருக்குக: 2/6 + 3/6."],"options":[["7/6","7/6"],["5/6","5/6"],["4/3","4/3"],["1","1"]],"answer":1,"explanation":["(2 + 3)/6 = 5/6 = 5/6.","(2 + 3)/6 = 5/6 = 5/6."]},{"id":719,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 4 red and 13 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 4 சிவப்பு, 13 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["6/19","6/19"],["7/20","7/20"],["5/18","5/18"],["4/17","4/17"]],"answer":3,"explanation":["Favourable outcomes / total = 4/17 = 4/17.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 4/17 = 4/17."]},{"id":720,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Small intestine”?","“சிறுகுடல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Blood vessels that carry blood towards the heart","இதயத்தை நோக்கி இரத்தத்தை எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"],["Transfer of pollen from anther to stigma","மகரந்தப்பையிலிருந்து சூலகமுடிக்கு மகரந்தம் மாற்றப்படுதல்"],["The main site of absorption of digested nutrients in humans","மனிதரில் செரிக்கப்பட்ட ஊட்டச்சத்துகள் உறிஞ்சப்படும் முக்கிய இடம்"],["The conversion of a liquid into vapour at its surface","திரவம் அதன் பரப்பில் ஆவியாக மாறுதல்"]],"answer":2,"explanation":["Small intestine: The main site of absorption of digested nutrients in humans.","சிறுகுடல்: மனிதரில் செரிக்கப்பட்ட ஊட்டச்சத்துகள் உறிஞ்சப்படும் முக்கிய இடம்."]},{"id":721,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Kidneys”?","“சிறுநீரகங்கள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Organs that filter blood and form urine","இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்"],["The SI unit of electric current","மின்னோட்டத்தின் SI அலகு"],["The mineral essential for haemoglobin formation","ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது"],["Blood vessels that carry blood away from the heart","இதயத்திலிருந்து இரத்தத்தை வெளியே எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"]],"answer":0,"explanation":["Kidneys: Organs that filter blood and form urine.","சிறுநீரகங்கள்: இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்."]},{"id":722,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Enamel”?","“பற்சிப்பி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The organelle where most aerobic cellular respiration takes place","பெரும்பாலான ஆக்சிஜன் சார்ந்த செல் சுவாசம் நடைபெறும் செல் நுண்ணுறுப்பு"],["The hard outer covering of the crown of a tooth","பல்லின் மகுடப்பகுதியை மூடியுள்ள கடினமான வெளிப்புறப் படலம்"],["The conversion of a liquid into vapour at its surface","திரவம் அதன் பரப்பில் ஆவியாக மாறுதல்"],["The force that opposes relative sliding between surfaces","பரப்புகளுக்கிடையேயான சார்பு சறுக்கல் இயக்கத்தை எதிர்க்கும் விசை"]],"answer":1,"explanation":["Enamel: The hard outer covering of the crown of a tooth.","பற்சிப்பி: பல்லின் மகுடப்பகுதியை மூடியுள்ள கடினமான வெளிப்புறப் படலம்."]},{"id":723,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Rain gauge”?","“மழைமானி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["An instrument used to measure rainfall","மழையளவை அளக்கப் பயன்படும் கருவி"],["The Chola ruler who built the Brihadisvara Temple at Thanjavur","தஞ்சைப் பெரிய கோயிலைக் கட்டிய சோழ மன்னர்"],["The leader who led the Dandi Salt March in 1930","1930 இல் தண்டி உப்பு யாத்திரையை வழிநடத்திய தலைவர்"],["A smaller river that joins a larger river","ஒரு பெரிய ஆற்றுடன் இணையும் சிறிய ஆறு"]],"answer":0,"explanation":["Rain gauge: An instrument used to measure rainfall.","மழைமானி: மழையளவை அளக்கப் பயன்படும் கருவி."]},{"id":724,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Barometer”?","“காற்றழுத்தமானி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Land surrounded by water on three sides","மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்"],["Earth’s movement around its own axis","புவி தனது அச்சில் சுழலும் இயக்கம்"],["An instrument used to measure atmospheric pressure","வளிமண்டல அழுத்தத்தை அளக்கப் பயன்படும் கருவி"],["Land surrounded by water on all sides","அனைத்துப் பக்கங்களிலும் நீரால் சூழப்பட்ட நிலம்"]],"answer":2,"explanation":["Barometer: An instrument used to measure atmospheric pressure.","காற்றழுத்தமானி: வளிமண்டல அழுத்தத்தை அளக்கப் பயன்படும் கருவி."]},{"id":725,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 21, 30, 39, 48, 57, …","அடுத்த எண்ணைக் காண்க: 21, 30, 39, 48, 57, …"],"options":[["66","66"],["76","76"],["67","67"],["65","65"]],"answer":0,"explanation":["Add 9 each time. 57 + 9 = 66.","ஒவ்வொரு முறையும் 9 கூட்டுக. 57 + 9 = 66."]},{"id":726,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 21, 42, 84, 168, ?","தொடரை நிறைவு செய்க: 21, 42, 84, 168, ?"],"options":[["338","338"],["339","339"],["336","336"],["346","346"]],"answer":2,"explanation":["Double each term: 168 × 2 = 336.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 168 × 2 = 336."]},{"id":727,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 17, 36, 74, 150, ?","அடுத்த உறுப்பைக் காண்க: 17, 36, 74, 150, ?"],"options":[["304","304"],["312","312"],["302","302"],["307","307"]],"answer":2,"explanation":["Multiply by 2, then add 2: 150 × 2 + 2 = 302.","2 ஆல் பெருக்கி 2 கூட்டுக: 150 × 2 + 2 = 302."]},{"id":728,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 21, 25, ?, 33, 37","விடுபட்ட எண்ணைக் காண்க: 21, 25, ?, 33, 37"],"options":[["28","28"],["32","32"],["29","29"],["30","30"]],"answer":2,"explanation":["The common difference is 4. 25 + 4 = 29.","பொது வித்தியாசம் 4. 25 + 4 = 29."]},{"id":729,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 256, 289, 324, 361, ?","தொடர்க: 256, 289, 324, 361, ?"],"options":[["400","400"],["401","401"],["402","402"],["403","403"]],"answer":0,"explanation":["These are squares of 16, 17, 18, 19. Next: 20² = 400.","இவை 16, 17, 18, 19 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 20² = 400."]},{"id":730,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 14 from the front and position 5 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 14 ஆவது, பின்னிருந்து 5 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["17","17"],["20","20"],["18","18"],["23","23"]],"answer":2,"explanation":["Total = 14 + 5 − 1 = 18; the student is counted only once.","மொத்தம் = 14 + 5 − 1 = 18; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":731,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 18 students, a student is in position 6 from the front. Find the position from the back.","18 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 6 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["12","12"],["18","18"],["14","14"],["13","13"]],"answer":3,"explanation":["Position from back = 18 − 6 + 1 = 13.","பின்னிருந்து இடம் = 18 − 6 + 1 = 13."]},{"id":732,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 27 m north, 22 m east, 4 m south and 22 m west. How far are you from the start, in metres?","27 மீ வடக்கு, 22 மீ கிழக்கு, 4 மீ தெற்கு, 22 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["22","22"],["24","24"],["23","23"],["26","26"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 27 − 4 = 23 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 27 − 4 = 23 மீ."]},{"id":733,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 9 km east and then 12 km north. Find the straight-line distance from the start in km.","9 கி.மீ கிழக்கிலும் பின்னர் 12 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["17","17"],["16","16"],["25","25"],["15","15"]],"answer":3,"explanation":["Pythagoras: √(9² + 12²) = 15 km.","பிதாகரஸ் தேற்றம்: √(9² + 12²) = 15 கி.மீ."]},{"id":734,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 11 → 132, then 20 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 11 → 132 எனில் 20 → ?"],"options":[["421","421"],["840","840"],["422","422"],["420","420"]],"answer":3,"explanation":["20 × (20 + 1) = 420.","20 × (20 + 1) = 420."]},{"id":735,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 8 : 512 :: 15 : ?","மும்மடி விதியைப் பயன்படுத்துக: 8 : 512 :: 15 : ?"],"options":[["3377","3377"],["3378","3378"],["3376","3376"],["3375","3375"]],"answer":3,"explanation":["8³ = 512, so 15³ = 3375.","8³ = 512; எனவே 15³ = 3375."]},{"id":736,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 2 places forward in the alphabet (wrap Z to A). Code BOOK.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 2 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). BOOK இன் குறியீடு என்ன?"],"options":[["DQQM","DQQM"],["FSSO","FSSO"],["ERRN","ERRN"],["CPPL","CPPL"]],"answer":0,"explanation":["Each letter advances by 2: B → D, O → Q, O → Q, K → M","ஒவ்வோர் எழுத்தும் 2 இடங்கள் முன்னேறும்: B → D, O → Q, O → Q, K → M"]},{"id":737,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 40% of 480.","480 இல் 40% காண்க."],"options":[["192","192"],["191","191"],["195","195"],["194","194"]],"answer":0,"explanation":["480 × 40 / 100 = 192.","480 × 40 / 100 = 192."]},{"id":738,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹3700. Find the price after a 5% discount, in rupees.","குறித்த விலை ₹3700. 5% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["3517","3517"],["3516","3516"],["3515","3515"],["3514","3514"]],"answer":2,"explanation":["Discount = ₹185. Pay 3700 − 185 = ₹3515.","தள்ளுபடி = ₹185. செலுத்துவது 3700 − 185 = ₹3515."]},{"id":739,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2200 at 8% per year for 4 years.","₹2200 க்கு ஆண்டுக்கு 8% வீதம் 4 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["704","704"],["706","706"],["1408","1408"],["709","709"]],"answer":0,"explanation":["PRT/100 = 2200 × 8 × 4 / 100 = ₹704.","PRT/100 = 2200 × 8 × 4 / 100 = ₹704."]},{"id":740,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 13x + 19 = 266.","x காண்க: 13x + 19 = 266."],"options":[["24","24"],["29","29"],["19","19"],["21","21"]],"answer":2,"explanation":["x = (266 − 19) ÷ 13 = 19.","x = (266 − 19) ÷ 13 = 19."]},{"id":741,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 16 cm long and 8 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 16 செ.மீ, அகலம் 8 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["128","128"],["138","138"],["129","129"],["130","130"]],"answer":0,"explanation":["Area = length × width = 16 × 8 = 128 cm².","பரப்பளவு = நீளம் × அகலம் = 16 × 8 = 128 ச.செ.மீ."]},{"id":742,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 28 m and 14 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 28 மீ மற்றும் 14 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["84","84"],["85","85"],["86","86"],["87","87"]],"answer":0,"explanation":["Perimeter = 2(28 + 14) = 84 m.","சுற்றளவு = 2(28 + 14) = 84 மீ."]},{"id":743,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 80 cm and height 8 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 80 செ.மீ, உயரம் 8 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["325","325"],["320","320"],["330","330"],["640","640"]],"answer":1,"explanation":["Area = ½ × 80 × 8 = 320 cm².","பரப்பளவு = ½ × 80 × 8 = 320 ச.செ.மீ."]},{"id":744,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 36 cm × 9 cm × 10 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 36 செ.மீ × 9 செ.மீ × 10 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["3239","3239"],["3243","3243"],["3240","3240"],["3245","3245"]],"answer":2,"explanation":["Volume = length × breadth × height = 36 × 9 × 10 = 3240 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 36 × 9 × 10 = 3240 க.செ.மீ."]},{"id":745,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Vitamin C”?","“வைட்டமின் C” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["A reaction between an acid and a base that forms salt and water","அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்"],["The green pigment that absorbs light for photosynthesis","ஒளிச்சேர்க்கைக்காக ஒளியை உறிஞ்சும் பச்சை நிறமி"],["The vitamin whose deficiency causes scurvy","குறைபாட்டால் ஸ்கர்வி நோயை ஏற்படுத்தும் வைட்டமின்"],["Heat transfer through the bulk movement of a fluid","ஒரு பாய்மத்தின் ஒட்டுமொத்த இயக்கத்தால் வெப்பம் கடத்தப்படுதல்"]],"answer":2,"explanation":["Vitamin C: The vitamin whose deficiency causes scurvy.","வைட்டமின் C: குறைபாட்டால் ஸ்கர்வி நோயை ஏற்படுத்தும் வைட்டமின்."]},{"id":746,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Vitamin D”?","“வைட்டமின் D” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Corrosion of iron in the presence of oxygen and moisture","ஆக்சிஜன் மற்றும் ஈரப்பதத்தின் முன்னிலையில் இரும்பு அரித்தல்"],["The tendency to resist a change in the state of rest or motion","ஓய்வு அல்லது இயக்க நிலையில் ஏற்படும் மாற்றத்தை எதிர்க்கும் தன்மை"],["The vitamin whose deficiency can cause rickets in children","குழந்தைகளில் குறைபாட்டால் ரிக்கெட்ஸ் ஏற்படக்கூடிய வைட்டமின்"],["The change of a solid into a liquid","திடப்பொருள் திரவமாக மாறுதல்"]],"answer":2,"explanation":["Vitamin D: The vitamin whose deficiency can cause rickets in children.","வைட்டமின் D: குழந்தைகளில் குறைபாட்டால் ரிக்கெட்ஸ் ஏற்படக்கூடிய வைட்டமின்."]},{"id":747,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Vitamin A”?","“வைட்டமின் A” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The floral part that usually develops into a fruit after fertilisation","கருவுறுதலுக்குப் பிறகு பொதுவாக கனியாக வளரும் மலரின் பகுதி"],["The vitamin whose deficiency can cause night blindness","குறைபாட்டால் மாலைக்கண் நோய் ஏற்படக்கூடிய வைட்டமின்"],["The gas that makes up the largest fraction of dry air","உலர் காற்றில் மிக அதிகப் பங்கு வகிக்கும் வாயு"],["The mineral essential for haemoglobin formation","ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது"]],"answer":1,"explanation":["Vitamin A: The vitamin whose deficiency can cause night blindness.","வைட்டமின் A: குறைபாட்டால் மாலைக்கண் நோய் ஏற்படக்கூடிய வைட்டமின்."]},{"id":748,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Anemometer”?","“காற்று வேகமானி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The Mauryan emperor associated with the Kalinga War","கலிங்கப் போருடன் தொடர்புடைய மௌரியப் பேரரசர்"],["Earth’s movement around its own axis","புவி தனது அச்சில் சுழலும் இயக்கம்"],["The leader popularly called Netaji","நேதாஜி எனப் போற்றப்படும் தலைவர்"],["An instrument used to measure wind speed","காற்றின் வேகத்தை அளக்கப் பயன்படும் கருவி"]],"answer":3,"explanation":["Anemometer: An instrument used to measure wind speed.","காற்று வேகமானி: காற்றின் வேகத்தை அளக்கப் பயன்படும் கருவி."]},{"id":749,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Wind vane”?","“காற்றுத்திசை காட்டி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["An instrument used to show wind direction","காற்று வீசும் திசையைக் காட்டும் கருவி"],["An elevated region with a relatively flat top","ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி"],["The long-term pattern of weather in a region","ஒரு பகுதியில் நீண்ட காலமாக நிலவும் வானிலையின் அமைப்பு"],["Wearing away and removal of material by moving agents such as water","நீர் போன்ற நகரும் காரணிகளால் பொருட்கள் தேய்ந்து அகற்றப்படுதல்"]],"answer":0,"explanation":["Wind vane: An instrument used to show wind direction.","காற்றுத்திசை காட்டி: காற்று வீசும் திசையைக் காட்டும் கருவி."]},{"id":750,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in PLAY.","A = 1, B = 2, …, Z = 26 எனில், PLAY என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["56","56"],["59","59"],["54","54"],["108","108"]],"answer":2,"explanation":["16 + 12 + 1 + 25 = 54.","16 + 12 + 1 + 25 = 54."]},{"id":751,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Tuesday. What day will it be after 79 days?","இன்று செவ்வாய். 79 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Thursday","வியாழன்"],["Saturday","சனி"],["Friday","வெள்ளி"],["Sunday","ஞாயிறு"]],"answer":0,"explanation":["79 ÷ 7 leaves remainder 2. Move 2 days from Tuesday: Thursday.","79 ஐ 7 ஆல் வகுக்க மீதி 2. செவ்வாய் கிழமையிலிருந்து 2 நாட்கள் நகர்ந்தால் வியாழன்."]},{"id":752,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 21 students shakes hands once with every other student. How many handshakes occur?","21 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["211","211"],["209","209"],["210","210"],["212","212"]],"answer":2,"explanation":["Each pair is counted once: 21 × 20 ÷ 2 = 210.","ஒவ்வொரு இணையும் ஒருமுறை: 21 × 20 ÷ 2 = 210."]},{"id":753,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 7 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 7 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["44","44"],["24","24"],["22","22"],["25","25"]],"answer":2,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 6 = 22.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 6 = 22."]},{"id":754,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 5, 9, 14, 20, 27, ?","நிறைவு செய்க: 5, 9, 14, 20, 27, ?"],"options":[["37","37"],["36","36"],["35","35"],["40","40"]],"answer":2,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 35.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 35."]},{"id":755,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 21, 28, 49, 77, 126, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 21, 28, 49, 77, 126, ?"],"options":[["208","208"],["203","203"],["213","213"],["206","206"]],"answer":1,"explanation":["77 + 126 = 203.","77 + 126 = 203."]},{"id":756,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 23, 27, 31, 35, 39, …","அடுத்த எண்ணைக் காண்க: 23, 27, 31, 35, 39, …"],"options":[["48","48"],["46","46"],["53","53"],["43","43"]],"answer":3,"explanation":["Add 4 each time. 39 + 4 = 43.","ஒவ்வொரு முறையும் 4 கூட்டுக. 39 + 4 = 43."]},{"id":757,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 33, 66, 132, 264, ?","தொடரை நிறைவு செய்க: 33, 66, 132, 264, ?"],"options":[["529","529"],["531","531"],["527","527"],["528","528"]],"answer":3,"explanation":["Double each term: 264 × 2 = 528.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 264 × 2 = 528."]},{"id":758,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 25, 56, 118, 242, ?","அடுத்த உறுப்பைக் காண்க: 25, 56, 118, 242, ?"],"options":[["490","490"],["495","495"],["492","492"],["489","489"]],"answer":0,"explanation":["Multiply by 2, then add 6: 242 × 2 + 6 = 490.","2 ஆல் பெருக்கி 6 கூட்டுக: 242 × 2 + 6 = 490."]},{"id":759,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 4, 10, ?, 22, 28","விடுபட்ட எண்ணைக் காண்க: 4, 10, ?, 22, 28"],"options":[["18","18"],["16","16"],["32","32"],["26","26"]],"answer":1,"explanation":["The common difference is 6. 10 + 6 = 16.","பொது வித்தியாசம் 6. 10 + 6 = 16."]},{"id":760,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 1024, 1089, 1156, 1225, ?","தொடர்க: 1024, 1089, 1156, 1225, ?"],"options":[["1306","1306"],["1297","1297"],["1298","1298"],["1296","1296"]],"answer":3,"explanation":["These are squares of 32, 33, 34, 35. Next: 36² = 1296.","இவை 32, 33, 34, 35 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 36² = 1296."]},{"id":761,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 9 from the front and position 6 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 9 ஆவது, பின்னிருந்து 6 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["19","19"],["16","16"],["15","15"],["14","14"]],"answer":3,"explanation":["Total = 9 + 6 − 1 = 14; the student is counted only once.","மொத்தம் = 9 + 6 − 1 = 14; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":762,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 17, 27, 37, 47, 57.","17, 27, 37, 47, 57 ஆகியவற்றின் சராசரி காண்க."],"options":[["38","38"],["37","37"],["36","36"],["39","39"]],"answer":1,"explanation":["Sum ÷ count = 185 ÷ 5 = 37.","கூடுதல் ÷ எண்ணிக்கை = 185 ÷ 5 = 37."]},{"id":763,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 231 km in 7 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 7 மணி நேரத்தில் 231 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["36","36"],["38","38"],["33","33"],["43","43"]],"answer":2,"explanation":["Speed = distance ÷ time = 231 ÷ 7 = 33 km/h.","வேகம் = தொலைவு ÷ நேரம் = 231 ÷ 7 = 33 கி.மீ/மணி."]},{"id":764,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 120 in the ratio 3 : 9. Find the smaller share.","120 ஐ 3 : 9 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["29","29"],["32","32"],["33","33"],["30","30"]],"answer":3,"explanation":["Smaller share = 120 × 3/(3+9) = 30.","சிறிய பங்கு = 120 × 3/(3+9) = 30."]},{"id":765,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 15 and 25.","15 மற்றும் 25 இன் மீ.பொ.வ. காண்க."],"options":[["6","6"],["15","15"],["5","5"],["8","8"]],"answer":2,"explanation":["Common factors: 1, 5. Greatest = 5.","பொதுக் காரணிகள்: 1, 5. மிகப்பெரியது 5."]},{"id":766,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 19 and 8.","19 மற்றும் 8 இன் மீ.பொ.ம. காண்க."],"options":[["153","153"],["162","162"],["157","157"],["152","152"]],"answer":3,"explanation":["LCM = product ÷ HCF = 152 ÷ 1 = 152.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 152 ÷ 1 = 152."]},{"id":767,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹2000 is sold for ₹2400. Find the profit percentage.","₹2000 க்கு வாங்கிய பொருள் ₹2400 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["40","40"],["19","19"],["20","20"],["23","23"]],"answer":2,"explanation":["Profit = ₹400. Profit% = 400 × 100 / 2000 = 20%.","இலாபம் = ₹400. இலாப% = 400 × 100 / 2000 = 20%."]},{"id":768,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 30° and 45°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 30°, 45°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["210","210"],["110","110"],["105","105"],["104","104"]],"answer":2,"explanation":["180 − 30 − 45 = 105°.","180 − 30 − 45 = 105°."]},{"id":769,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 5°, in degrees.","5° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["174","174"],["177","177"],["350","350"],["175","175"]],"answer":3,"explanation":["Supplementary angles sum to 180°. 180 − 5 = 175°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 5 = 175°."]},{"id":770,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Iron”?","“இரும்பு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The organelle in green plant cells where photosynthesis occurs","பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு"],["The mineral essential for haemoglobin formation","ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது"],["The development of a seed into a seedling","விதை ஒரு நாற்றாக வளரத் தொடங்கும் நிகழ்வு"],["The organelle where most aerobic cellular respiration takes place","பெரும்பாலான ஆக்சிஜன் சார்ந்த செல் சுவாசம் நடைபெறும் செல் நுண்ணுறுப்பு"]],"answer":1,"explanation":["Iron: The mineral essential for haemoglobin formation.","இரும்பு: ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது."]},{"id":771,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Iodine”?","“அயோடின்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The gas that makes up the largest fraction of dry air","உலர் காற்றில் மிக அதிகப் பங்கு வகிக்கும் வாயு"],["The mineral required to make thyroid hormones","தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது"],["The bouncing back of light into the same medium","ஒளி அதே ஊடகத்திற்குத் திரும்பும் நிகழ்வு"],["Heat transfer that can occur through a vacuum","வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்"]],"answer":1,"explanation":["Iodine: The mineral required to make thyroid hormones.","அயோடின்: தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது."]},{"id":772,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Newton”?","“நியூட்டன்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The change of a gas or vapour into a liquid","வாயு அல்லது ஆவி திரவமாக மாறுதல்"],["Plant tissue that transports prepared food","தயாரிக்கப்பட்ட உணவை எடுத்துச் செல்லும் தாவரத் திசு"],["The substance in which a solute dissolves","கரைபொருள் கரையும் பொருள்"],["The SI unit of force","விசையின் SI அலகு"]],"answer":3,"explanation":["Newton: The SI unit of force.","நியூட்டன்: விசையின் SI அலகு."]},{"id":773,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Igneous rock”?","“தீப்பாறை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Rock formed by cooling and solidification of magma or lava","மாக்மா அல்லது லாவா குளிர்ந்து இறுகுவதால் உருவாகும் பாறை"],["The smallest of the five oceans","ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்"],["Angular distance east or west of the Prime Meridian","முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு"],["The place in Amritsar where a massacre occurred in 1919","1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்"]],"answer":0,"explanation":["Igneous rock: Rock formed by cooling and solidification of magma or lava.","தீப்பாறை: மாக்மா அல்லது லாவா குளிர்ந்து இறுகுவதால் உருவாகும் பாறை."]},{"id":774,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Sedimentary rock”?","“படிவுப்பாறை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Rock formed from accumulated sediments","சேர்ந்த படிவுகளிலிருந்து உருவாகும் பாறை"],["A depositional landform that may develop at a river mouth","ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்"],["An instrument used to measure atmospheric pressure","வளிமண்டல அழுத்தத்தை அளக்கப் பயன்படும் கருவி"],["The smallest of the seven continents","ஏழு கண்டங்களில் மிகச்சிறிய கண்டம்"]],"answer":0,"explanation":["Sedimentary rock: Rock formed from accumulated sediments.","படிவுப்பாறை: சேர்ந்த படிவுகளிலிருந்து உருவாகும் பாறை."]},{"id":775,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 25 students, a student is in position 15 from the front. Find the position from the back.","25 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 15 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["16","16"],["11","11"],["21","21"],["10","10"]],"answer":1,"explanation":["Position from back = 25 − 15 + 1 = 11.","பின்னிருந்து இடம் = 25 − 15 + 1 = 11."]},{"id":776,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 27 m north, 6 m east, 3 m south and 6 m west. How far are you from the start, in metres?","27 மீ வடக்கு, 6 மீ கிழக்கு, 3 மீ தெற்கு, 6 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["25","25"],["48","48"],["24","24"],["23","23"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 27 − 3 = 24 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 27 − 3 = 24 மீ."]},{"id":777,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 15 km east and then 20 km north. Find the straight-line distance from the start in km.","15 கி.மீ கிழக்கிலும் பின்னர் 20 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["28","28"],["27","27"],["25","25"],["24","24"]],"answer":2,"explanation":["Pythagoras: √(15² + 20²) = 25 km.","பிதாகரஸ் தேற்றம்: √(15² + 20²) = 25 கி.மீ."]},{"id":778,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 16 → 272, then 22 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 16 → 272 எனில் 22 → ?"],"options":[["509","509"],["506","506"],["508","508"],["505","505"]],"answer":1,"explanation":["22 × (22 + 1) = 506.","22 × (22 + 1) = 506."]},{"id":779,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 2 : 8 :: 12 : ?","மும்மடி விதியைப் பயன்படுத்துக: 2 : 8 :: 12 : ?"],"options":[["1730","1730"],["1729","1729"],["1728","1728"],["1727","1727"]],"answer":2,"explanation":["2³ = 8, so 12³ = 1728.","2³ = 8; எனவே 12³ = 1728."]},{"id":780,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 7 places forward in the alphabet (wrap Z to A). Code FISH.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 7 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). FISH இன் குறியீடு என்ன?"],"options":[["MPZO","MPZO"],["NQAP","NQAP"],["ORBQ","ORBQ"],["LOYN","LOYN"]],"answer":0,"explanation":["Each letter advances by 7: F → M, I → P, S → Z, H → O","ஒவ்வோர் எழுத்தும் 7 இடங்கள் முன்னேறும்: F → M, I → P, S → Z, H → O"]},{"id":781,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in LAMP.","A = 1, B = 2, …, Z = 26 எனில், LAMP என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["44","44"],["45","45"],["42","42"],["47","47"]],"answer":2,"explanation":["12 + 1 + 13 + 16 = 42.","12 + 1 + 13 + 16 = 42."]},{"id":782,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Tuesday. What day will it be after 13 days?","இன்று செவ்வாய். 13 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Tuesday","செவ்வாய்"],["Monday","திங்கள்"],["Wednesday","புதன்"],["Thursday","வியாழன்"]],"answer":1,"explanation":["13 ÷ 7 leaves remainder 6. Move 6 days from Tuesday: Monday.","13 ஐ 7 ஆல் வகுக்க மீதி 6. செவ்வாய் கிழமையிலிருந்து 6 நாட்கள் நகர்ந்தால் திங்கள்."]},{"id":783,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 17 students shakes hands once with every other student. How many handshakes occur?","17 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["136","136"],["146","146"],["137","137"],["135","135"]],"answer":0,"explanation":["Each pair is counted once: 17 × 16 ÷ 2 = 136.","ஒவ்வொரு இணையும் ஒருமுறை: 17 × 16 ÷ 2 = 136."]},{"id":784,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 34 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 34 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["102","102"],["103","103"],["113","113"],["105","105"]],"answer":1,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 33 = 103.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 33 = 103."]},{"id":785,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 4, 7, 11, 16, 22, ?","நிறைவு செய்க: 4, 7, 11, 16, 22, ?"],"options":[["34","34"],["39","39"],["29","29"],["31","31"]],"answer":2,"explanation":["Differences increase by 1: 3, 4, 5, 6, 7. Next = 29.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 3, 4, 5, 6, 7. அடுத்த எண் 29."]},{"id":786,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 9, 17, 26, 43, 69, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 9, 17, 26, 43, 69, ?"],"options":[["117","117"],["113","113"],["112","112"],["224","224"]],"answer":2,"explanation":["43 + 69 = 112.","43 + 69 = 112."]},{"id":787,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 7/8 + 7/8.","கூட்டிச் சுருக்குக: 7/8 + 7/8."],"options":[["7/4","7/4"],["17/8","17/8"],["15/8","15/8"],["2","2"]],"answer":0,"explanation":["(7 + 7)/8 = 14/8 = 7/4.","(7 + 7)/8 = 14/8 = 7/4."]},{"id":788,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 2 red and 6 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 2 சிவப்பு, 6 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["1/3","1/3"],["5/11","5/11"],["1/4","1/4"],["2/5","2/5"]],"answer":2,"explanation":["Favourable outcomes / total = 2/8 = 1/4.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 2/8 = 1/4."]},{"id":789,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 15% of 740.","740 இல் 15% காண்க."],"options":[["112","112"],["110","110"],["116","116"],["111","111"]],"answer":3,"explanation":["740 × 15 / 100 = 111.","740 × 15 / 100 = 111."]},{"id":790,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹2600. Find the price after a 5% discount, in rupees.","குறித்த விலை ₹2600. 5% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["2475","2475"],["2471","2471"],["2470","2470"],["4940","4940"]],"answer":2,"explanation":["Discount = ₹130. Pay 2600 − 130 = ₹2470.","தள்ளுபடி = ₹130. செலுத்துவது 2600 − 130 = ₹2470."]},{"id":791,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹1500 at 11% per year for 3 years.","₹1500 க்கு ஆண்டுக்கு 11% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["500","500"],["505","505"],["495","495"],["990","990"]],"answer":2,"explanation":["PRT/100 = 1500 × 11 × 3 / 100 = ₹495.","PRT/100 = 1500 × 11 × 3 / 100 = ₹495."]},{"id":792,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 6x + 18 = 30.","x காண்க: 6x + 18 = 30."],"options":[["2","2"],["5","5"],["1","1"],["12","12"]],"answer":0,"explanation":["x = (30 − 18) ÷ 6 = 2.","x = (30 − 18) ÷ 6 = 2."]},{"id":793,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 10 cm long and 17 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 10 செ.மீ, அகலம் 17 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["170","170"],["340","340"],["175","175"],["180","180"]],"answer":0,"explanation":["Area = length × width = 10 × 17 = 170 cm².","பரப்பளவு = நீளம் × அகலம் = 10 × 17 = 170 ச.செ.மீ."]},{"id":794,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 9 m and 13 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 9 மீ மற்றும் 13 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["88","88"],["43","43"],["45","45"],["44","44"]],"answer":3,"explanation":["Perimeter = 2(9 + 13) = 44 m.","சுற்றளவு = 2(9 + 13) = 44 மீ."]},{"id":795,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Joule”?","“ஜூல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The SI unit of energy","ஆற்றலின் SI அலகு"],["The bouncing back of light into the same medium","ஒளி அதே ஊடகத்திற்குத் திரும்பும் நிகழ்வு"],["Root extensions that increase the surface area for absorption","உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்"],["The SI unit of pressure","அழுத்தத்தின் SI அலகு"]],"answer":0,"explanation":["Joule: The SI unit of energy.","ஜூல்: ஆற்றலின் SI அலகு."]},{"id":796,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Watt”?","“வாட்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The SI unit of power","திறனின் SI அலகு"],["Organs that filter blood and form urine","இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்"],["A reaction between an acid and a base that forms salt and water","அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்"],["The mineral required to make thyroid hormones","தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது"]],"answer":0,"explanation":["Watt: The SI unit of power.","வாட்: திறனின் SI அலகு."]},{"id":797,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Pascal”?","“பாஸ்கல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Blood components that help in clotting","இரத்தம் உறைதலுக்கு உதவும் இரத்தக் கூறுகள்"],["The substance dissolved in a solvent to form a solution","கரைப்பானில் கரைந்து கரைசலை உருவாக்கும் பொருள்"],["The SI unit of pressure","அழுத்தத்தின் SI அலகு"],["The cellular structure responsible for protein synthesis","புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு"]],"answer":2,"explanation":["Pascal: The SI unit of pressure.","பாஸ்கல்: அழுத்தத்தின் SI அலகு."]},{"id":798,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Metamorphic rock”?","“உருமாறிய பாறை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Rock altered by heat and pressure without complete melting","முழுமையாக உருகாமல் வெப்பம் மற்றும் அழுத்தத்தால் மாறிய பாறை"],["Angular distance east or west of the Prime Meridian","முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு"],["An instrument used to measure rainfall","மழையளவை அளக்கப் பயன்படும் கருவி"],["The leader who led the Dandi Salt March in 1930","1930 இல் தண்டி உப்பு யாத்திரையை வழிநடத்திய தலைவர்"]],"answer":0,"explanation":["Metamorphic rock: Rock altered by heat and pressure without complete melting.","உருமாறிய பாறை: முழுமையாக உருகாமல் வெப்பம் மற்றும் அழுத்தத்தால் மாறிய பாறை."]},{"id":799,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Erosion”?","“அரித்தல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Wearing away and removal of material by moving agents such as water","நீர் போன்ற நகரும் காரணிகளால் பொருட்கள் தேய்ந்து அகற்றப்படுதல்"],["The largest continent by land area","நிலப்பரப்பில் மிகப்பெரிய கண்டம்"],["An elevated region with a relatively flat top","ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி"],["The leader popularly called Netaji","நேதாஜி எனப் போற்றப்படும் தலைவர்"]],"answer":0,"explanation":["Erosion: Wearing away and removal of material by moving agents such as water.","அரித்தல்: நீர் போன்ற நகரும் காரணிகளால் பொருட்கள் தேய்ந்து அகற்றப்படுதல்."]},{"id":800,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 33, 36, 39, 42, 45, …","அடுத்த எண்ணைக் காண்க: 33, 36, 39, 42, 45, …"],"options":[["51","51"],["48","48"],["58","58"],["53","53"]],"answer":1,"explanation":["Add 3 each time. 45 + 3 = 48.","ஒவ்வொரு முறையும் 3 கூட்டுக. 45 + 3 = 48."]},{"id":801,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 28, 56, 112, 224, ?","தொடரை நிறைவு செய்க: 28, 56, 112, 224, ?"],"options":[["447","447"],["458","458"],["448","448"],["896","896"]],"answer":2,"explanation":["Double each term: 224 × 2 = 448.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 224 × 2 = 448."]},{"id":802,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 4, 13, 31, 67, ?","அடுத்த உறுப்பைக் காண்க: 4, 13, 31, 67, ?"],"options":[["139","139"],["142","142"],["149","149"],["278","278"]],"answer":0,"explanation":["Multiply by 2, then add 5: 67 × 2 + 5 = 139.","2 ஆல் பெருக்கி 5 கூட்டுக: 67 × 2 + 5 = 139."]},{"id":803,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 31, 33, ?, 37, 39","விடுபட்ட எண்ணைக் காண்க: 31, 33, ?, 37, 39"],"options":[["35","35"],["45","45"],["34","34"],["36","36"]],"answer":0,"explanation":["The common difference is 2. 33 + 2 = 35.","பொது வித்தியாசம் 2. 33 + 2 = 35."]},{"id":804,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 576, 625, 676, 729, ?","தொடர்க: 576, 625, 676, 729, ?"],"options":[["787","787"],["786","786"],["784","784"],["1568","1568"]],"answer":2,"explanation":["These are squares of 24, 25, 26, 27. Next: 28² = 784.","இவை 24, 25, 26, 27 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 28² = 784."]},{"id":805,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 17 from the front and position 19 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 17 ஆவது, பின்னிருந்து 19 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["34","34"],["38","38"],["45","45"],["35","35"]],"answer":3,"explanation":["Total = 17 + 19 − 1 = 35; the student is counted only once.","மொத்தம் = 17 + 19 − 1 = 35; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":806,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 40 students, a student is in position 6 from the front. Find the position from the back.","40 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 6 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["35","35"],["36","36"],["38","38"],["37","37"]],"answer":0,"explanation":["Position from back = 40 − 6 + 1 = 35.","பின்னிருந்து இடம் = 40 − 6 + 1 = 35."]},{"id":807,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 20 m north, 23 m east, 3 m south and 23 m west. How far are you from the start, in metres?","20 மீ வடக்கு, 23 மீ கிழக்கு, 3 மீ தெற்கு, 23 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["19","19"],["27","27"],["17","17"],["20","20"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 20 − 3 = 17 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 20 − 3 = 17 மீ."]},{"id":808,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 24 km east and then 32 km north. Find the straight-line distance from the start in km.","24 கி.மீ கிழக்கிலும் பின்னர் 32 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["42","42"],["50","50"],["40","40"],["41","41"]],"answer":2,"explanation":["Pythagoras: √(24² + 32²) = 40 km.","பிதாகரஸ் தேற்றம்: √(24² + 32²) = 40 கி.மீ."]},{"id":809,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 14 → 210, then 18 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 14 → 210 எனில் 18 → ?"],"options":[["347","347"],["341","341"],["342","342"],["345","345"]],"answer":2,"explanation":["18 × (18 + 1) = 342.","18 × (18 + 1) = 342."]},{"id":810,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 4 : 64 :: 13 : ?","மும்மடி விதியைப் பயன்படுத்துக: 4 : 64 :: 13 : ?"],"options":[["2200","2200"],["2197","2197"],["2198","2198"],["2196","2196"]],"answer":1,"explanation":["4³ = 64, so 13³ = 2197.","4³ = 64; எனவே 13³ = 2197."]},{"id":811,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 4 places forward in the alphabet (wrap Z to A). Code PLAY.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 4 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). PLAY இன் குறியீடு என்ன?"],"options":[["VRGE","VRGE"],["TPEC","TPEC"],["SODB","SODB"],["UQFD","UQFD"]],"answer":1,"explanation":["Each letter advances by 4: P → T, L → P, A → E, Y → C","ஒவ்வோர் எழுத்தும் 4 இடங்கள் முன்னேறும்: P → T, L → P, A → E, Y → C"]},{"id":812,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 28 cm and height 11 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 28 செ.மீ, உயரம் 11 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["154","154"],["153","153"],["164","164"],["157","157"]],"answer":0,"explanation":["Area = ½ × 28 × 11 = 154 cm².","பரப்பளவு = ½ × 28 × 11 = 154 ச.செ.மீ."]},{"id":813,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 32 cm × 11 cm × 19 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 32 செ.மீ × 11 செ.மீ × 19 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["6698","6698"],["6689","6689"],["6690","6690"],["6688","6688"]],"answer":3,"explanation":["Volume = length × breadth × height = 32 × 11 × 19 = 6688 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 32 × 11 × 19 = 6688 க.செ.மீ."]},{"id":814,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 19, 28, 37, 46, 55.","19, 28, 37, 46, 55 ஆகியவற்றின் சராசரி காண்க."],"options":[["47","47"],["40","40"],["37","37"],["42","42"]],"answer":2,"explanation":["Sum ÷ count = 185 ÷ 5 = 37.","கூடுதல் ÷ எண்ணிக்கை = 185 ÷ 5 = 37."]},{"id":815,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 900 km in 15 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 15 மணி நேரத்தில் 900 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["60","60"],["61","61"],["63","63"],["65","65"]],"answer":0,"explanation":["Speed = distance ÷ time = 900 ÷ 15 = 60 km/h.","வேகம் = தொலைவு ÷ நேரம் = 900 ÷ 15 = 60 கி.மீ/மணி."]},{"id":816,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 66 in the ratio 3 : 8. Find the smaller share.","66 ஐ 3 : 8 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["17","17"],["23","23"],["18","18"],["21","21"]],"answer":2,"explanation":["Smaller share = 66 × 3/(3+8) = 18.","சிறிய பங்கு = 66 × 3/(3+8) = 18."]},{"id":817,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 12 and 28.","12 மற்றும் 28 இன் மீ.பொ.வ. காண்க."],"options":[["5","5"],["4","4"],["7","7"],["6","6"]],"answer":1,"explanation":["Common factors: 1, 2, 4. Greatest = 4.","பொதுக் காரணிகள்: 1, 2, 4. மிகப்பெரியது 4."]},{"id":818,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 31 and 6.","31 மற்றும் 6 இன் மீ.பொ.ம. காண்க."],"options":[["186","186"],["187","187"],["196","196"],["188","188"]],"answer":0,"explanation":["LCM = product ÷ HCF = 186 ÷ 1 = 186.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 186 ÷ 1 = 186."]},{"id":819,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹800 is sold for ₹840. Find the profit percentage.","₹800 க்கு வாங்கிய பொருள் ₹840 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["8","8"],["5","5"],["10","10"],["4","4"]],"answer":1,"explanation":["Profit = ₹40. Profit% = 40 × 100 / 800 = 5%.","இலாபம் = ₹40. இலாப% = 40 × 100 / 800 = 5%."]},{"id":820,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Ampere”?","“ஆம்பியர்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The organelle in green plant cells where photosynthesis occurs","பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு"],["The green pigment that absorbs light for photosynthesis","ஒளிச்சேர்க்கைக்காக ஒளியை உறிஞ்சும் பச்சை நிறமி"],["Plant tissue that transports water and minerals from roots","வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு"],["The SI unit of electric current","மின்னோட்டத்தின் SI அலகு"]],"answer":3,"explanation":["Ampere: The SI unit of electric current.","ஆம்பியர்: மின்னோட்டத்தின் SI அலகு."]},{"id":821,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Volt”?","“வோல்ட்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["A change in light direction at a boundary when its speed changes","ஒளியின் வேகம் மாறும்போது ஊடக எல்லையில் அதன் திசை மாறுதல்"],["The SI unit of electric current","மின்னோட்டத்தின் SI அலகு"],["The SI unit of electric potential difference","மின்னழுத்த வேறுபாட்டின் SI அலகு"],["Tiny air sacs in lungs where gas exchange occurs","நுரையீரலில் வாயுப் பரிமாற்றம் நடைபெறும் சிறிய காற்றுப் பைகள்"]],"answer":2,"explanation":["Volt: The SI unit of electric potential difference.","வோல்ட்: மின்னழுத்த வேறுபாட்டின் SI அலகு."]},{"id":822,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Ohm”?","“ஓம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Direct change from solid to gas without a liquid stage","திரவ நிலையை அடையாமல் திடம் நேரடியாக வாயுவாக மாறுதல்"],["The conversion of a liquid into vapour at its surface","திரவம் அதன் பரப்பில் ஆவியாக மாறுதல்"],["The SI unit of electrical resistance","மின்தடையின் SI அலகு"],["The SI unit of energy","ஆற்றலின் SI அலகு"]],"answer":2,"explanation":["Ohm: The SI unit of electrical resistance.","ஓம்: மின்தடையின் SI அலகு."]},{"id":823,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Deposition”?","“படிதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["An instrument used to show wind direction","காற்று வீசும் திசையைக் காட்டும் கருவி"],["A depositional landform that may develop at a river mouth","ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்"],["The atmospheric conditions at a place over a short period","ஓர் இடத்தில் குறுகிய காலத்தில் நிலவும் வளிமண்டல நிலை"],["The laying down of material carried by water, wind or ice","நீர், காற்று அல்லது பனியால் எடுத்துச் செல்லப்பட்ட பொருட்கள் படியுதல்"]],"answer":3,"explanation":["Deposition: The laying down of material carried by water, wind or ice.","படிதல்: நீர், காற்று அல்லது பனியால் எடுத்துச் செல்லப்பட்ட பொருட்கள் படியுதல்."]},{"id":824,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Delta”?","“கழிமுகம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The imaginary circle at 0° latitude","0° அட்சத்தில் அமைந்துள்ள கற்பனை வட்டம்"],["A depositional landform that may develop at a river mouth","ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்"],["A smaller river that joins a larger river","ஒரு பெரிய ஆற்றுடன் இணையும் சிறிய ஆறு"],["The leader popularly called Netaji","நேதாஜி எனப் போற்றப்படும் தலைவர்"]],"answer":1,"explanation":["Delta: A depositional landform that may develop at a river mouth.","கழிமுகம்: ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்."]},{"id":825,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in EARTH.","A = 1, B = 2, …, Z = 26 எனில், EARTH என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["52","52"],["62","62"],["104","104"],["57","57"]],"answer":0,"explanation":["5 + 1 + 18 + 20 + 8 = 52.","5 + 1 + 18 + 20 + 8 = 52."]},{"id":826,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Saturday. What day will it be after 76 days?","இன்று சனி. 76 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Friday","வெள்ளி"],["Sunday","ஞாயிறு"],["Monday","திங்கள்"],["Saturday","சனி"]],"answer":0,"explanation":["76 ÷ 7 leaves remainder 6. Move 6 days from Saturday: Friday.","76 ஐ 7 ஆல் வகுக்க மீதி 6. சனி கிழமையிலிருந்து 6 நாட்கள் நகர்ந்தால் வெள்ளி."]},{"id":827,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 12 students shakes hands once with every other student. How many handshakes occur?","12 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["69","69"],["66","66"],["67","67"],["68","68"]],"answer":1,"explanation":["Each pair is counted once: 12 × 11 ÷ 2 = 66.","ஒவ்வொரு இணையும் ஒருமுறை: 12 × 11 ÷ 2 = 66."]},{"id":828,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 21 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 21 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["67","67"],["128","128"],["64","64"],["65","65"]],"answer":2,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 20 = 64.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 20 = 64."]},{"id":829,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 8, 10, 13, 17, 22, ?","நிறைவு செய்க: 8, 10, 13, 17, 22, ?"],"options":[["27","27"],["33","33"],["28","28"],["29","29"]],"answer":2,"explanation":["Differences increase by 1: 2, 3, 4, 5, 6. Next = 28.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 2, 3, 4, 5, 6. அடுத்த எண் 28."]},{"id":830,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 29, 34, 63, 97, 160, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 29, 34, 63, 97, 160, ?"],"options":[["258","258"],["257","257"],["260","260"],["262","262"]],"answer":1,"explanation":["97 + 160 = 257.","97 + 160 = 257."]},{"id":831,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 3, 7, 11, 15, 19, …","அடுத்த எண்ணைக் காண்க: 3, 7, 11, 15, 19, …"],"options":[["26","26"],["28","28"],["22","22"],["23","23"]],"answer":3,"explanation":["Add 4 each time. 19 + 4 = 23.","ஒவ்வொரு முறையும் 4 கூட்டுக. 19 + 4 = 23."]},{"id":832,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 26, 52, 104, 208, ?","தொடரை நிறைவு செய்க: 26, 52, 104, 208, ?"],"options":[["415","415"],["418","418"],["417","417"],["416","416"]],"answer":3,"explanation":["Double each term: 208 × 2 = 416.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 208 × 2 = 416."]},{"id":833,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 14, 30, 62, 126, ?","அடுத்த உறுப்பைக் காண்க: 14, 30, 62, 126, ?"],"options":[["257","257"],["264","264"],["255","255"],["254","254"]],"answer":3,"explanation":["Multiply by 2, then add 2: 126 × 2 + 2 = 254.","2 ஆல் பெருக்கி 2 கூட்டுக: 126 × 2 + 2 = 254."]},{"id":834,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 15, 23, ?, 39, 47","விடுபட்ட எண்ணைக் காண்க: 15, 23, ?, 39, 47"],"options":[["41","41"],["32","32"],["31","31"],["30","30"]],"answer":2,"explanation":["The common difference is 8. 23 + 8 = 31.","பொது வித்தியாசம் 8. 23 + 8 = 31."]},{"id":835,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 784, 841, 900, 961, ?","தொடர்க: 784, 841, 900, 961, ?"],"options":[["1034","1034"],["1027","1027"],["1024","1024"],["1023","1023"]],"answer":2,"explanation":["These are squares of 28, 29, 30, 31. Next: 32² = 1024.","இவை 28, 29, 30, 31 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 32² = 1024."]},{"id":836,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 31 from the front and position 24 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 31 ஆவது, பின்னிருந்து 24 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["57","57"],["54","54"],["56","56"],["64","64"]],"answer":1,"explanation":["Total = 31 + 24 − 1 = 54; the student is counted only once.","மொத்தம் = 31 + 24 − 1 = 54; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":837,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 56° and 38°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 56°, 38°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["89","89"],["88","88"],["85","85"],["86","86"]],"answer":3,"explanation":["180 − 56 − 38 = 86°.","180 − 56 − 38 = 86°."]},{"id":838,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 8°, in degrees.","8° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["173","173"],["182","182"],["171","171"],["172","172"]],"answer":3,"explanation":["Supplementary angles sum to 180°. 180 − 8 = 172°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 8 = 172°."]},{"id":839,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 1/11 + 2/11.","கூட்டிச் சுருக்குக: 1/11 + 2/11."],"options":[["3/11","3/11"],["4/11","4/11"],["6/11","6/11"],["5/11","5/11"]],"answer":0,"explanation":["(1 + 2)/11 = 3/11 = 3/11.","(1 + 2)/11 = 3/11 = 3/11."]},{"id":840,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 10 red and 15 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 10 சிவப்பு, 15 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["4/9","4/9"],["13/28","13/28"],["2/5","2/5"],["11/26","11/26"]],"answer":2,"explanation":["Favourable outcomes / total = 10/25 = 2/5.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 10/25 = 2/5."]},{"id":841,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 20% of 460.","460 இல் 20% காண்க."],"options":[["94","94"],["92","92"],["97","97"],["91","91"]],"answer":1,"explanation":["460 × 20 / 100 = 92.","460 × 20 / 100 = 92."]},{"id":842,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹3800. Find the price after a 5% discount, in rupees.","குறித்த விலை ₹3800. 5% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["3610","3610"],["3609","3609"],["3613","3613"],["3615","3615"]],"answer":0,"explanation":["Discount = ₹190. Pay 3800 − 190 = ₹3610.","தள்ளுபடி = ₹190. செலுத்துவது 3800 − 190 = ₹3610."]},{"id":843,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2000 at 4% per year for 3 years.","₹2000 க்கு ஆண்டுக்கு 4% வீதம் 3 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["242","242"],["480","480"],["239","239"],["240","240"]],"answer":3,"explanation":["PRT/100 = 2000 × 4 × 3 / 100 = ₹240.","PRT/100 = 2000 × 4 × 3 / 100 = ₹240."]},{"id":844,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 14x + 19 = 187.","x காண்க: 14x + 19 = 187."],"options":[["22","22"],["12","12"],["17","17"],["13","13"]],"answer":1,"explanation":["x = (187 − 19) ÷ 14 = 12.","x = (187 − 19) ÷ 14 = 12."]},{"id":845,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Hertz”?","“ஹெர்ட்ஸ்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The cellular structure responsible for protein synthesis","புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு"],["The SI unit of frequency","அதிர்வெண்ணின் SI அலகு"],["Heat transfer that can occur through a vacuum","வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்"],["The SI unit of electric current","மின்னோட்டத்தின் SI அலகு"]],"answer":1,"explanation":["Hertz: The SI unit of frequency.","ஹெர்ட்ஸ்: அதிர்வெண்ணின் SI அலகு."]},{"id":846,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Kelvin”?","“கெல்வின்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Blood components that help in clotting","இரத்தம் உறைதலுக்கு உதவும் இரத்தக் கூறுகள்"],["The bouncing back of light into the same medium","ஒளி அதே ஊடகத்திற்குத் திரும்பும் நிகழ்வு"],["The vitamin whose deficiency can cause night blindness","குறைபாட்டால் மாலைக்கண் நோய் ஏற்படக்கூடிய வைட்டமின்"],["The SI base unit of thermodynamic temperature","வெப்ப இயக்கவியல் வெப்பநிலையின் SI அடிப்படை அலகு"]],"answer":3,"explanation":["Kelvin: The SI base unit of thermodynamic temperature.","கெல்வின்: வெப்ப இயக்கவியல் வெப்பநிலையின் SI அடிப்படை அலகு."]},{"id":847,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Inertia”?","“நிலைமம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The organelle in green plant cells where photosynthesis occurs","பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு"],["The mineral essential for haemoglobin formation","ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது"],["The tendency to resist a change in the state of rest or motion","ஓய்வு அல்லது இயக்க நிலையில் ஏற்படும் மாற்றத்தை எதிர்க்கும் தன்மை"],["Blood vessels that carry blood away from the heart","இதயத்திலிருந்து இரத்தத்தை வெளியே எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"]],"answer":2,"explanation":["Inertia: The tendency to resist a change in the state of rest or motion.","நிலைமம்: ஓய்வு அல்லது இயக்க நிலையில் ஏற்படும் மாற்றத்தை எதிர்க்கும் தன்மை."]},{"id":848,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Tributary”?","“துணையாறு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["An instrument used to measure wind speed","காற்றின் வேகத்தை அளக்கப் பயன்படும் கருவி"],["A smaller river that joins a larger river","ஒரு பெரிய ஆற்றுடன் இணையும் சிறிய ஆறு"],["Earth’s movement around the Sun","புவி சூரியனைச் சுற்றி வரும் இயக்கம்"],["The place in Amritsar where a massacre occurred in 1919","1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்"]],"answer":1,"explanation":["Tributary: A smaller river that joins a larger river.","துணையாறு: ஒரு பெரிய ஆற்றுடன் இணையும் சிறிய ஆறு."]},{"id":849,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Plateau”?","“பீடபூமி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["An elevated region with a relatively flat top","ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி"],["The smallest of the five oceans","ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்"],["Angular distance east or west of the Prime Meridian","முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு"],["An instrument used to measure rainfall","மழையளவை அளக்கப் பயன்படும் கருவி"]],"answer":0,"explanation":["Plateau: An elevated region with a relatively flat top.","பீடபூமி: ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி."]},{"id":850,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 49 students, a student is in position 17 from the front. Find the position from the back.","49 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 17 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["33","33"],["66","66"],["36","36"],["38","38"]],"answer":0,"explanation":["Position from back = 49 − 17 + 1 = 33.","பின்னிருந்து இடம் = 49 − 17 + 1 = 33."]},{"id":851,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 39 m north, 4 m east, 7 m south and 4 m west. How far are you from the start, in metres?","39 மீ வடக்கு, 4 மீ கிழக்கு, 7 மீ தெற்கு, 4 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["32","32"],["42","42"],["35","35"],["33","33"]],"answer":0,"explanation":["East and west cancel. Net northward distance = 39 − 7 = 32 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 39 − 7 = 32 மீ."]},{"id":852,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 27 km east and then 36 km north. Find the straight-line distance from the start in km.","27 கி.மீ கிழக்கிலும் பின்னர் 36 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["48","48"],["55","55"],["45","45"],["47","47"]],"answer":2,"explanation":["Pythagoras: √(27² + 36²) = 45 km.","பிதாகரஸ் தேற்றம்: √(27² + 36²) = 45 கி.மீ."]},{"id":853,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 8 → 72, then 18 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 8 → 72 எனில் 18 → ?"],"options":[["342","342"],["341","341"],["352","352"],["347","347"]],"answer":0,"explanation":["18 × (18 + 1) = 342.","18 × (18 + 1) = 342."]},{"id":854,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 7 : 343 :: 12 : ?","மும்மடி விதியைப் பயன்படுத்துக: 7 : 343 :: 12 : ?"],"options":[["1728","1728"],["1727","1727"],["3456","3456"],["1731","1731"]],"answer":0,"explanation":["7³ = 343, so 12³ = 1728.","7³ = 343; எனவே 12³ = 1728."]},{"id":855,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 6 places forward in the alphabet (wrap Z to A). Code WIND.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 6 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). WIND இன் குறியீடு என்ன?"],"options":[["EQVL","EQVL"],["COTJ","COTJ"],["BNSI","BNSI"],["DPUK","DPUK"]],"answer":1,"explanation":["Each letter advances by 6: W → C, I → O, N → T, D → J","ஒவ்வோர் எழுத்தும் 6 இடங்கள் முன்னேறும்: W → C, I → O, N → T, D → J"]},{"id":856,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in BIRD.","A = 1, B = 2, …, Z = 26 எனில், BIRD என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["33","33"],["38","38"],["32","32"],["43","43"]],"answer":0,"explanation":["2 + 9 + 18 + 4 = 33.","2 + 9 + 18 + 4 = 33."]},{"id":857,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Wednesday. What day will it be after 75 days?","இன்று புதன். 75 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Wednesday","புதன்"],["Monday","திங்கள்"],["Tuesday","செவ்வாய்"],["Thursday","வியாழன்"]],"answer":1,"explanation":["75 ÷ 7 leaves remainder 5. Move 5 days from Wednesday: Monday.","75 ஐ 7 ஆல் வகுக்க மீதி 5. புதன் கிழமையிலிருந்து 5 நாட்கள் நகர்ந்தால் திங்கள்."]},{"id":858,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 24 students shakes hands once with every other student. How many handshakes occur?","24 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["279","279"],["275","275"],["276","276"],["281","281"]],"answer":2,"explanation":["Each pair is counted once: 24 × 23 ÷ 2 = 276.","ஒவ்வொரு இணையும் ஒருமுறை: 24 × 23 ÷ 2 = 276."]},{"id":859,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 28 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 28 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["86","86"],["85","85"],["170","170"],["87","87"]],"answer":1,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 27 = 85.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 27 = 85."]},{"id":860,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 11, 14, 18, 23, 29, ?","நிறைவு செய்க: 11, 14, 18, 23, 29, ?"],"options":[["41","41"],["72","72"],["38","38"],["36","36"]],"answer":3,"explanation":["Differences increase by 1: 3, 4, 5, 6, 7. Next = 36.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 3, 4, 5, 6, 7. அடுத்த எண் 36."]},{"id":861,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 11, 16, 27, 43, 70, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 11, 16, 27, 43, 70, ?"],"options":[["112","112"],["115","115"],["113","113"],["226","226"]],"answer":2,"explanation":["43 + 70 = 113.","43 + 70 = 113."]},{"id":862,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 31 cm long and 17 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 31 செ.மீ, அகலம் 17 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["530","530"],["537","537"],["527","527"],["1054","1054"]],"answer":2,"explanation":["Area = length × width = 31 × 17 = 527 cm².","பரப்பளவு = நீளம் × அகலம் = 31 × 17 = 527 ச.செ.மீ."]},{"id":863,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 24 m and 10 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 24 மீ மற்றும் 10 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["71","71"],["78","78"],["68","68"],["136","136"]],"answer":2,"explanation":["Perimeter = 2(24 + 10) = 68 m.","சுற்றளவு = 2(24 + 10) = 68 மீ."]},{"id":864,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 12 cm and height 6 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 12 செ.மீ, உயரம் 6 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["72","72"],["36","36"],["41","41"],["46","46"]],"answer":1,"explanation":["Area = ½ × 12 × 6 = 36 cm².","பரப்பளவு = ½ × 12 × 6 = 36 ச.செ.மீ."]},{"id":865,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 9 cm × 13 cm × 20 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 9 செ.மீ × 13 செ.மீ × 20 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["2343","2343"],["2345","2345"],["2342","2342"],["2340","2340"]],"answer":3,"explanation":["Volume = length × breadth × height = 9 × 13 × 20 = 2340 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 9 × 13 × 20 = 2340 க.செ.மீ."]},{"id":866,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 37, 54, 71, 88, 105.","37, 54, 71, 88, 105 ஆகியவற்றின் சராசரி காண்க."],"options":[["81","81"],["70","70"],["71","71"],["72","72"]],"answer":2,"explanation":["Sum ÷ count = 355 ÷ 5 = 71.","கூடுதல் ÷ எண்ணிக்கை = 355 ÷ 5 = 71."]},{"id":867,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 928 km in 16 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 16 மணி நேரத்தில் 928 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["61","61"],["57","57"],["58","58"],["68","68"]],"answer":2,"explanation":["Speed = distance ÷ time = 928 ÷ 16 = 58 km/h.","வேகம் = தொலைவு ÷ நேரம் = 928 ÷ 16 = 58 கி.மீ/மணி."]},{"id":868,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 154 in the ratio 9 : 13. Find the smaller share.","154 ஐ 9 : 13 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["63","63"],["73","73"],["65","65"],["62","62"]],"answer":0,"explanation":["Smaller share = 154 × 9/(9+13) = 63.","சிறிய பங்கு = 154 × 9/(9+13) = 63."]},{"id":869,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 19 and 31.","19 மற்றும் 31 இன் மீ.பொ.வ. காண்க."],"options":[["3","3"],["2","2"],["11","11"],["1","1"]],"answer":3,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":870,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Friction”?","“உராய்வு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Tiny air sacs in lungs where gas exchange occurs","நுரையீரலில் வாயுப் பரிமாற்றம் நடைபெறும் சிறிய காற்றுப் பைகள்"],["The tendency to resist a change in the state of rest or motion","ஓய்வு அல்லது இயக்க நிலையில் ஏற்படும் மாற்றத்தை எதிர்க்கும் தன்மை"],["The force that opposes relative sliding between surfaces","பரப்புகளுக்கிடையேயான சார்பு சறுக்கல் இயக்கத்தை எதிர்க்கும் விசை"],["The mineral essential for haemoglobin formation","ஹீமோகுளோபின் உருவாக்கத்திற்கு இன்றியமையாத தாது"]],"answer":2,"explanation":["Friction: The force that opposes relative sliding between surfaces.","உராய்வு: பரப்புகளுக்கிடையேயான சார்பு சறுக்கல் இயக்கத்தை எதிர்க்கும் விசை."]},{"id":871,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Gravity”?","“ஈர்ப்புவிசை” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The main site of absorption of digested nutrients in humans","மனிதரில் செரிக்கப்பட்ட ஊட்டச்சத்துகள் உறிஞ்சப்படும் முக்கிய இடம்"],["The change of a liquid into a solid","திரவம் திடப்பொருளாக மாறுதல்"],["The attractive interaction between objects with mass","நிறையுள்ள பொருட்களுக்கிடையேயான ஈர்ப்பு"],["Direct change from solid to gas without a liquid stage","திரவ நிலையை அடையாமல் திடம் நேரடியாக வாயுவாக மாறுதல்"]],"answer":2,"explanation":["Gravity: The attractive interaction between objects with mass.","ஈர்ப்புவிசை: நிறையுள்ள பொருட்களுக்கிடையேயான ஈர்ப்பு."]},{"id":872,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Convection”?","“வெப்பச் சலனம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["A reaction between an acid and a base that forms salt and water","அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்"],["Blood vessels that carry blood towards the heart","இதயத்தை நோக்கி இரத்தத்தை எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"],["Heat transfer through the bulk movement of a fluid","ஒரு பாய்மத்தின் ஒட்டுமொத்த இயக்கத்தால் வெப்பம் கடத்தப்படுதல்"],["The SI unit of electric potential difference","மின்னழுத்த வேறுபாட்டின் SI அலகு"]],"answer":2,"explanation":["Convection: Heat transfer through the bulk movement of a fluid.","வெப்பச் சலனம்: ஒரு பாய்மத்தின் ஒட்டுமொத்த இயக்கத்தால் வெப்பம் கடத்தப்படுதல்."]},{"id":873,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Island”?","“தீவு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Land surrounded by water on all sides","அனைத்துப் பக்கங்களிலும் நீரால் சூழப்பட்ட நிலம்"],["The freedom fighter associated with the Swadeshi Steam Navigation Company","சுதேசி நீராவிக் கப்பல் நிறுவனத்துடன் தொடர்புடைய விடுதலைப் போராட்ட வீரர்"],["The leader popularly called Netaji","நேதாஜி எனப் போற்றப்படும் தலைவர்"],["Angular distance east or west of the Prime Meridian","முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு"]],"answer":0,"explanation":["Island: Land surrounded by water on all sides.","தீவு: அனைத்துப் பக்கங்களிலும் நீரால் சூழப்பட்ட நிலம்."]},{"id":874,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Peninsula”?","“தீபகற்பம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Land surrounded by water on three sides","மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்"],["The latitude circle at about 23.5° north","சுமார் 23.5° வட அட்சத்தில் அமைந்துள்ள வட்டம்"],["The freedom fighter associated with the Swadeshi Steam Navigation Company","சுதேசி நீராவிக் கப்பல் நிறுவனத்துடன் தொடர்புடைய விடுதலைப் போராட்ட வீரர்"],["Rock formed from accumulated sediments","சேர்ந்த படிவுகளிலிருந்து உருவாகும் பாறை"]],"answer":0,"explanation":["Peninsula: Land surrounded by water on three sides.","தீபகற்பம்: மூன்று பக்கங்களில் நீரால் சூழப்பட்ட நிலம்."]},{"id":875,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 26, 32, 38, 44, 50, …","அடுத்த எண்ணைக் காண்க: 26, 32, 38, 44, 50, …"],"options":[["66","66"],["55","55"],["56","56"],["59","59"]],"answer":2,"explanation":["Add 6 each time. 50 + 6 = 56.","ஒவ்வொரு முறையும் 6 கூட்டுக. 50 + 6 = 56."]},{"id":876,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 7, 14, 28, 56, ?","தொடரை நிறைவு செய்க: 7, 14, 28, 56, ?"],"options":[["112","112"],["113","113"],["111","111"],["114","114"]],"answer":0,"explanation":["Double each term: 56 × 2 = 112.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 56 × 2 = 112."]},{"id":877,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 32, 71, 149, 305, ?","அடுத்த உறுப்பைக் காண்க: 32, 71, 149, 305, ?"],"options":[["622","622"],["617","617"],["616","616"],["619","619"]],"answer":1,"explanation":["Multiply by 2, then add 7: 305 × 2 + 7 = 617.","2 ஆல் பெருக்கி 7 கூட்டுக: 305 × 2 + 7 = 617."]},{"id":878,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 28, 31, ?, 37, 40","விடுபட்ட எண்ணைக் காண்க: 28, 31, ?, 37, 40"],"options":[["34","34"],["37","37"],["68","68"],["33","33"]],"answer":0,"explanation":["The common difference is 3. 31 + 3 = 34.","பொது வித்தியாசம் 3. 31 + 3 = 34."]},{"id":879,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 361, 400, 441, 484, ?","தொடர்க: 361, 400, 441, 484, ?"],"options":[["528","528"],["1058","1058"],["539","539"],["529","529"]],"answer":3,"explanation":["These are squares of 19, 20, 21, 22. Next: 23² = 529.","இவை 19, 20, 21, 22 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 23² = 529."]},{"id":880,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 22 from the front and position 22 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 22 ஆவது, பின்னிருந்து 22 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["46","46"],["48","48"],["43","43"],["44","44"]],"answer":2,"explanation":["Total = 22 + 22 − 1 = 43; the student is counted only once.","மொத்தம் = 22 + 22 − 1 = 43; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":881,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 25 students, a student is in position 8 from the front. Find the position from the back.","25 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 8 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["23","23"],["18","18"],["20","20"],["21","21"]],"answer":1,"explanation":["Position from back = 25 − 8 + 1 = 18.","பின்னிருந்து இடம் = 25 − 8 + 1 = 18."]},{"id":882,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 23 m north, 16 m east, 5 m south and 16 m west. How far are you from the start, in metres?","23 மீ வடக்கு, 16 மீ கிழக்கு, 5 மீ தெற்கு, 16 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["23","23"],["20","20"],["21","21"],["18","18"]],"answer":3,"explanation":["East and west cancel. Net northward distance = 23 − 5 = 18 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 23 − 5 = 18 மீ."]},{"id":883,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 15 km east and then 20 km north. Find the straight-line distance from the start in km.","15 கி.மீ கிழக்கிலும் பின்னர் 20 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["30","30"],["35","35"],["25","25"],["24","24"]],"answer":2,"explanation":["Pythagoras: √(15² + 20²) = 25 km.","பிதாகரஸ் தேற்றம்: √(15² + 20²) = 25 கி.மீ."]},{"id":884,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 7 → 56, then 24 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 7 → 56 எனில் 24 → ?"],"options":[["1200","1200"],["610","610"],["601","601"],["600","600"]],"answer":3,"explanation":["24 × (24 + 1) = 600.","24 × (24 + 1) = 600."]},{"id":885,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 7 : 343 :: 16 : ?","மும்மடி விதியைப் பயன்படுத்துக: 7 : 343 :: 16 : ?"],"options":[["4106","4106"],["4097","4097"],["4095","4095"],["4096","4096"]],"answer":3,"explanation":["7³ = 343, so 16³ = 4096.","7³ = 343; எனவே 16³ = 4096."]},{"id":886,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 3 places forward in the alphabet (wrap Z to A). Code BOOK.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 3 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). BOOK இன் குறியீடு என்ன?"],"options":[["ERRN","ERRN"],["DQQM","DQQM"],["GTTP","GTTP"],["FSSO","FSSO"]],"answer":0,"explanation":["Each letter advances by 3: B → E, O → R, O → R, K → N","ஒவ்வோர் எழுத்தும் 3 இடங்கள் முன்னேறும்: B → E, O → R, O → R, K → N"]},{"id":887,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 14 and 11.","14 மற்றும் 11 இன் மீ.பொ.ம. காண்க."],"options":[["308","308"],["154","154"],["156","156"],["157","157"]],"answer":1,"explanation":["LCM = product ÷ HCF = 154 ÷ 1 = 154.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 154 ÷ 1 = 154."]},{"id":888,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹3700 is sold for ₹4440. Find the profit percentage.","₹3700 க்கு வாங்கிய பொருள் ₹4440 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["40","40"],["25","25"],["23","23"],["20","20"]],"answer":3,"explanation":["Profit = ₹740. Profit% = 740 × 100 / 3700 = 20%.","இலாபம் = ₹740. இலாப% = 740 × 100 / 3700 = 20%."]},{"id":889,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 45° and 26°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 45°, 26°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["109","109"],["110","110"],["112","112"],["119","119"]],"answer":0,"explanation":["180 − 45 − 26 = 109°.","180 − 45 − 26 = 109°."]},{"id":890,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 27°, in degrees.","27° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["163","163"],["153","153"],["158","158"],["155","155"]],"answer":1,"explanation":["Supplementary angles sum to 180°. 180 − 27 = 153°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 27 = 153°."]},{"id":891,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 14/15 + 4/15.","கூட்டிச் சுருக்குக: 14/15 + 4/15."],"options":[["19/15","19/15"],["7/5","7/5"],["6/5","6/5"],["4/3","4/3"]],"answer":2,"explanation":["(14 + 4)/15 = 18/15 = 6/5.","(14 + 4)/15 = 18/15 = 6/5."]},{"id":892,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 11 red and 11 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 11 சிவப்பு, 11 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["14/25","14/25"],["12/23","12/23"],["13/24","13/24"],["1/2","1/2"]],"answer":3,"explanation":["Favourable outcomes / total = 11/22 = 1/2.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 11/22 = 1/2."]},{"id":893,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 60% of 560.","560 இல் 60% காண்க."],"options":[["337","337"],["339","339"],["346","346"],["336","336"]],"answer":3,"explanation":["560 × 60 / 100 = 336.","560 × 60 / 100 = 336."]},{"id":894,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹3400. Find the price after a 15% discount, in rupees.","குறித்த விலை ₹3400. 15% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["2893","2893"],["2900","2900"],["2891","2891"],["2890","2890"]],"answer":3,"explanation":["Discount = ₹510. Pay 3400 − 510 = ₹2890.","தள்ளுபடி = ₹510. செலுத்துவது 3400 − 510 = ₹2890."]},{"id":895,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Radiation”?","“வெப்பக் கதிர்வீச்சு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["A reaction between an acid and a base that forms salt and water","அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்"],["The mineral required to make thyroid hormones","தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது"],["Heat transfer that can occur through a vacuum","வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்"],["The development of a seed into a seedling","விதை ஒரு நாற்றாக வளரத் தொடங்கும் நிகழ்வு"]],"answer":2,"explanation":["Radiation: Heat transfer that can occur through a vacuum.","வெப்பக் கதிர்வீச்சு: வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்."]},{"id":896,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Reflection”?","“எதிரொளிப்பு” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Root extensions that increase the surface area for absorption","உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்"],["The selectively permeable boundary of a cell","தேர்ந்தெடுத்துப் பொருட்களை அனுமதிக்கும் செல்லின் எல்லை"],["Heat transfer that can occur through a vacuum","வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்"],["The bouncing back of light into the same medium","ஒளி அதே ஊடகத்திற்குத் திரும்பும் நிகழ்வு"]],"answer":3,"explanation":["Reflection: The bouncing back of light into the same medium.","எதிரொளிப்பு: ஒளி அதே ஊடகத்திற்குத் திரும்பும் நிகழ்வு."]},{"id":897,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Refraction”?","“ஒளிவிலகல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["A change in light direction at a boundary when its speed changes","ஒளியின் வேகம் மாறும்போது ஊடக எல்லையில் அதன் திசை மாறுதல்"],["The change of a solid into a liquid","திடப்பொருள் திரவமாக மாறுதல்"],["The change of a liquid into a solid","திரவம் திடப்பொருளாக மாறுதல்"],["Blood vessels that carry blood away from the heart","இதயத்திலிருந்து இரத்தத்தை வெளியே எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"]],"answer":0,"explanation":["Refraction: A change in light direction at a boundary when its speed changes.","ஒளிவிலகல்: ஒளியின் வேகம் மாறும்போது ஊடக எல்லையில் அதன் திசை மாறுதல்."]},{"id":898,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Isthmus”?","“நிலச்சந்தி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["A narrow strip of land joining two larger land areas","இரு பெரிய நிலப்பகுதிகளை இணைக்கும் குறுகிய நிலப்பட்டை"],["The Chola ruler who founded Gangaikonda Cholapuram","கங்கைகொண்ட சோழபுரத்தை நிறுவிய சோழ மன்னர்"],["An instrument used to measure atmospheric pressure","வளிமண்டல அழுத்தத்தை அளக்கப் பயன்படும் கருவி"],["The smallest of the five oceans","ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்"]],"answer":0,"explanation":["Isthmus: A narrow strip of land joining two larger land areas.","நிலச்சந்தி: இரு பெரிய நிலப்பகுதிகளை இணைக்கும் குறுகிய நிலப்பட்டை."]},{"id":899,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Strait”?","“நீர்ச்சந்தி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Rock formed by cooling and solidification of magma or lava","மாக்மா அல்லது லாவா குளிர்ந்து இறுகுவதால் உருவாகும் பாறை"],["Land surrounded by water on all sides","அனைத்துப் பக்கங்களிலும் நீரால் சூழப்பட்ட நிலம்"],["The largest ocean on Earth","புவியின் மிகப்பெரிய பெருங்கடல்"],["A narrow water passage connecting two larger water bodies","இரு பெரிய நீர்ப்பரப்புகளை இணைக்கும் குறுகிய நீர்ப்பாதை"]],"answer":3,"explanation":["Strait: A narrow water passage connecting two larger water bodies.","நீர்ச்சந்தி: இரு பெரிய நீர்ப்பரப்புகளை இணைக்கும் குறுகிய நீர்ப்பாதை."]},{"id":900,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in PARK.","A = 1, B = 2, …, Z = 26 எனில், PARK என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["45","45"],["92","92"],["48","48"],["46","46"]],"answer":3,"explanation":["16 + 1 + 18 + 11 = 46.","16 + 1 + 18 + 11 = 46."]},{"id":901,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Sunday. What day will it be after 94 days?","இன்று ஞாயிறு. 94 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Wednesday","புதன்"],["Friday","வெள்ளி"],["Saturday","சனி"],["Thursday","வியாழன்"]],"answer":0,"explanation":["94 ÷ 7 leaves remainder 3. Move 3 days from Sunday: Wednesday.","94 ஐ 7 ஆல் வகுக்க மீதி 3. ஞாயிறு கிழமையிலிருந்து 3 நாட்கள் நகர்ந்தால் புதன்."]},{"id":902,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 15 students shakes hands once with every other student. How many handshakes occur?","15 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["108","108"],["105","105"],["115","115"],["104","104"]],"answer":1,"explanation":["Each pair is counted once: 15 × 14 ÷ 2 = 105.","ஒவ்வொரு இணையும் ஒருமுறை: 15 × 14 ÷ 2 = 105."]},{"id":903,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 33 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 33 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["101","101"],["200","200"],["102","102"],["100","100"]],"answer":3,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 32 = 100.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 32 = 100."]},{"id":904,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 7, 11, 16, 22, 29, ?","நிறைவு செய்க: 7, 11, 16, 22, 29, ?"],"options":[["37","37"],["39","39"],["74","74"],["47","47"]],"answer":0,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 37.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 37."]},{"id":905,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 34, 38, 72, 110, 182, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 34, 38, 72, 110, 182, ?"],"options":[["297","297"],["294","294"],["293","293"],["292","292"]],"answer":3,"explanation":["110 + 182 = 292.","110 + 182 = 292."]},{"id":906,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 3, 8, 13, 18, 23, …","அடுத்த எண்ணைக் காண்க: 3, 8, 13, 18, 23, …"],"options":[["29","29"],["56","56"],["30","30"],["28","28"]],"answer":3,"explanation":["Add 5 each time. 23 + 5 = 28.","ஒவ்வொரு முறையும் 5 கூட்டுக. 23 + 5 = 28."]},{"id":907,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 3, 6, 12, 24, ?","தொடரை நிறைவு செய்க: 3, 6, 12, 24, ?"],"options":[["50","50"],["49","49"],["51","51"],["48","48"]],"answer":3,"explanation":["Double each term: 24 × 2 = 48.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 24 × 2 = 48."]},{"id":908,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 23, 52, 110, 226, ?","அடுத்த உறுப்பைக் காண்க: 23, 52, 110, 226, ?"],"options":[["468","468"],["916","916"],["463","463"],["458","458"]],"answer":3,"explanation":["Multiply by 2, then add 6: 226 × 2 + 6 = 458.","2 ஆல் பெருக்கி 6 கூட்டுக: 226 × 2 + 6 = 458."]},{"id":909,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 35, 40, ?, 50, 55","விடுபட்ட எண்ணைக் காண்க: 35, 40, ?, 50, 55"],"options":[["47","47"],["45","45"],["44","44"],["48","48"]],"answer":1,"explanation":["The common difference is 5. 40 + 5 = 45.","பொது வித்தியாசம் 5. 40 + 5 = 45."]},{"id":910,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 841, 900, 961, 1024, ?","தொடர்க: 841, 900, 961, 1024, ?"],"options":[["1090","1090"],["1091","1091"],["1089","1089"],["1088","1088"]],"answer":2,"explanation":["These are squares of 29, 30, 31, 32. Next: 33² = 1089.","இவை 29, 30, 31, 32 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 33² = 1089."]},{"id":911,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 21 from the front and position 12 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 21 ஆவது, பின்னிருந்து 12 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["32","32"],["34","34"],["42","42"],["64","64"]],"answer":0,"explanation":["Total = 21 + 12 − 1 = 32; the student is counted only once.","மொத்தம் = 21 + 12 − 1 = 32; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":912,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹600 at 6% per year for 2 years.","₹600 க்கு ஆண்டுக்கு 6% வீதம் 2 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["82","82"],["71","71"],["72","72"],["77","77"]],"answer":2,"explanation":["PRT/100 = 600 × 6 × 2 / 100 = ₹72.","PRT/100 = 600 × 6 × 2 / 100 = ₹72."]},{"id":913,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 10x + 40 = 230.","x காண்க: 10x + 40 = 230."],"options":[["19","19"],["38","38"],["20","20"],["29","29"]],"answer":0,"explanation":["x = (230 − 40) ÷ 10 = 19.","x = (230 − 40) ÷ 10 = 19."]},{"id":914,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 28 cm long and 12 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 28 செ.மீ, அகலம் 12 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["341","341"],["336","336"],["346","346"],["335","335"]],"answer":1,"explanation":["Area = length × width = 28 × 12 = 336 cm².","பரப்பளவு = நீளம் × அகலம் = 28 × 12 = 336 ச.செ.மீ."]},{"id":915,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 19 m and 11 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 19 மீ மற்றும் 11 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["120","120"],["60","60"],["70","70"],["61","61"]],"answer":1,"explanation":["Perimeter = 2(19 + 11) = 60 m.","சுற்றளவு = 2(19 + 11) = 60 மீ."]},{"id":916,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 40 cm and height 3 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 40 செ.மீ, உயரம் 3 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["60","60"],["120","120"],["70","70"],["65","65"]],"answer":0,"explanation":["Area = ½ × 40 × 3 = 60 cm².","பரப்பளவு = ½ × 40 × 3 = 60 ச.செ.மீ."]},{"id":917,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 10 cm × 12 cm × 4 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 10 செ.மீ × 12 செ.மீ × 4 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["483","483"],["480","480"],["481","481"],["490","490"]],"answer":1,"explanation":["Volume = length × breadth × height = 10 × 12 × 4 = 480 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 10 × 12 × 4 = 480 க.செ.மீ."]},{"id":918,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 10, 22, 34, 46, 58.","10, 22, 34, 46, 58 ஆகியவற்றின் சராசரி காண்க."],"options":[["35","35"],["33","33"],["36","36"],["34","34"]],"answer":3,"explanation":["Sum ÷ count = 170 ÷ 5 = 34.","கூடுதல் ÷ எண்ணிக்கை = 170 ÷ 5 = 34."]},{"id":919,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 810 km in 18 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 18 மணி நேரத்தில் 810 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["48","48"],["45","45"],["50","50"],["44","44"]],"answer":1,"explanation":["Speed = distance ÷ time = 810 ÷ 18 = 45 km/h.","வேகம் = தொலைவு ÷ நேரம் = 810 ÷ 18 = 45 கி.மீ/மணி."]},{"id":920,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Evaporation”?","“ஆவியாக்குதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The conversion of a liquid into vapour at its surface","திரவம் அதன் பரப்பில் ஆவியாக மாறுதல்"],["The SI base unit of thermodynamic temperature","வெப்ப இயக்கவியல் வெப்பநிலையின் SI அடிப்படை அலகு"],["The SI unit of power","திறனின் SI அலகு"],["The SI unit of energy","ஆற்றலின் SI அலகு"]],"answer":0,"explanation":["Evaporation: The conversion of a liquid into vapour at its surface.","ஆவியாக்குதல்: திரவம் அதன் பரப்பில் ஆவியாக மாறுதல்."]},{"id":921,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Condensation”?","“ஆவி சுருங்குதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Organs that filter blood and form urine","இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்"],["The change of a gas or vapour into a liquid","வாயு அல்லது ஆவி திரவமாக மாறுதல்"],["The hard outer covering of the crown of a tooth","பல்லின் மகுடப்பகுதியை மூடியுள்ள கடினமான வெளிப்புறப் படலம்"],["Heat transfer through the bulk movement of a fluid","ஒரு பாய்மத்தின் ஒட்டுமொத்த இயக்கத்தால் வெப்பம் கடத்தப்படுதல்"]],"answer":1,"explanation":["Condensation: The change of a gas or vapour into a liquid.","ஆவி சுருங்குதல்: வாயு அல்லது ஆவி திரவமாக மாறுதல்."]},{"id":922,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Sublimation”?","“பதங்கமாதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Direct change from solid to gas without a liquid stage","திரவ நிலையை அடையாமல் திடம் நேரடியாக வாயுவாக மாறுதல்"],["Loss of water as vapour from aerial parts of plants","தாவரத்தின் தரைக்கு மேலுள்ள பகுதிகளிலிருந்து நீர் ஆவியாக வெளியேறுதல்"],["Blood vessels that carry blood towards the heart","இதயத்தை நோக்கி இரத்தத்தை எடுத்துச் செல்லும் இரத்தக் குழாய்கள்"],["The organelle in green plant cells where photosynthesis occurs","பச்சைத் தாவரச் செல்களில் ஒளிச்சேர்க்கை நடைபெறும் நுண்ணுறுப்பு"]],"answer":0,"explanation":["Sublimation: Direct change from solid to gas without a liquid stage.","பதங்கமாதல்: திரவ நிலையை அடையாமல் திடம் நேரடியாக வாயுவாக மாறுதல்."]},{"id":923,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Ashoka”?","“அசோகர்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Rock formed from accumulated sediments","சேர்ந்த படிவுகளிலிருந்து உருவாகும் பாறை"],["The Mauryan emperor associated with the Kalinga War","கலிங்கப் போருடன் தொடர்புடைய மௌரியப் பேரரசர்"],["The reference meridian at 0° longitude","0° தீர்க்கத்தில் அமைந்துள்ள ஆதாரத் தீர்க்கக்கோடு"],["Earth’s movement around its own axis","புவி தனது அச்சில் சுழலும் இயக்கம்"]],"answer":1,"explanation":["Ashoka: The Mauryan emperor associated with the Kalinga War.","அசோகர்: கலிங்கப் போருடன் தொடர்புடைய மௌரியப் பேரரசர்."]},{"id":924,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Rajaraja I”?","“முதலாம் இராஜராஜன்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The smallest of the five oceans","ஐந்து பெருங்கடல்களில் மிகச்சிறிய பெருங்கடல்"],["The latitude circle at about 23.5° north","சுமார் 23.5° வட அட்சத்தில் அமைந்துள்ள வட்டம்"],["Earth’s movement around its own axis","புவி தனது அச்சில் சுழலும் இயக்கம்"],["The Chola ruler who built the Brihadisvara Temple at Thanjavur","தஞ்சைப் பெரிய கோயிலைக் கட்டிய சோழ மன்னர்"]],"answer":3,"explanation":["Rajaraja I: The Chola ruler who built the Brihadisvara Temple at Thanjavur.","முதலாம் இராஜராஜன்: தஞ்சைப் பெரிய கோயிலைக் கட்டிய சோழ மன்னர்."]},{"id":925,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 25 students, a student is in position 21 from the front. Find the position from the back.","25 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 21 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["10","10"],["5","5"],["8","8"],["15","15"]],"answer":1,"explanation":["Position from back = 25 − 21 + 1 = 5.","பின்னிருந்து இடம் = 25 − 21 + 1 = 5."]},{"id":926,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 31 m north, 16 m east, 9 m south and 16 m west. How far are you from the start, in metres?","31 மீ வடக்கு, 16 மீ கிழக்கு, 9 மீ தெற்கு, 16 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["32","32"],["22","22"],["44","44"],["24","24"]],"answer":1,"explanation":["East and west cancel. Net northward distance = 31 − 9 = 22 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 31 − 9 = 22 மீ."]},{"id":927,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 12 km east and then 16 km north. Find the straight-line distance from the start in km.","12 கி.மீ கிழக்கிலும் பின்னர் 16 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["25","25"],["20","20"],["40","40"],["21","21"]],"answer":1,"explanation":["Pythagoras: √(12² + 16²) = 20 km.","பிதாகரஸ் தேற்றம்: √(12² + 16²) = 20 கி.மீ."]},{"id":928,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 12 → 156, then 29 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 12 → 156 எனில் 29 → ?"],"options":[["870","870"],["873","873"],["871","871"],["872","872"]],"answer":0,"explanation":["29 × (29 + 1) = 870.","29 × (29 + 1) = 870."]},{"id":929,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 9 : 729 :: 18 : ?","மும்மடி விதியைப் பயன்படுத்துக: 9 : 729 :: 18 : ?"],"options":[["5835","5835"],["5832","5832"],["5837","5837"],["5842","5842"]],"answer":1,"explanation":["9³ = 729, so 18³ = 5832.","9³ = 729; எனவே 18³ = 5832."]},{"id":930,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 5 places forward in the alphabet (wrap Z to A). Code READ.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 5 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). READ இன் குறியீடு என்ன?"],"options":[["VIEH","VIEH"],["WJFI","WJFI"],["XKGJ","XKGJ"],["YLHK","YLHK"]],"answer":1,"explanation":["Each letter advances by 5: R → W, E → J, A → F, D → I","ஒவ்வோர் எழுத்தும் 5 இடங்கள் முன்னேறும்: R → W, E → J, A → F, D → I"]},{"id":931,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in TREE.","A = 1, B = 2, …, Z = 26 எனில், TREE என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["48","48"],["49","49"],["96","96"],["50","50"]],"answer":0,"explanation":["20 + 18 + 5 + 5 = 48.","20 + 18 + 5 + 5 = 48."]},{"id":932,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Friday. What day will it be after 78 days?","இன்று வெள்ளி. 78 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Monday","திங்கள்"],["Tuesday","செவ்வாய்"],["Saturday","சனி"],["Sunday","ஞாயிறு"]],"answer":2,"explanation":["78 ÷ 7 leaves remainder 1. Move 1 days from Friday: Saturday.","78 ஐ 7 ஆல் வகுக்க மீதி 1. வெள்ளி கிழமையிலிருந்து 1 நாட்கள் நகர்ந்தால் சனி."]},{"id":933,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 7 students shakes hands once with every other student. How many handshakes occur?","7 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["23","23"],["21","21"],["20","20"],["42","42"]],"answer":1,"explanation":["Each pair is counted once: 7 × 6 ÷ 2 = 21.","ஒவ்வொரு இணையும் ஒருமுறை: 7 × 6 ÷ 2 = 21."]},{"id":934,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 6 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 6 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["22","22"],["29","29"],["19","19"],["20","20"]],"answer":2,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 5 = 19.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 5 = 19."]},{"id":935,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 12, 14, 17, 21, 26, ?","நிறைவு செய்க: 12, 14, 17, 21, 26, ?"],"options":[["35","35"],["34","34"],["64","64"],["32","32"]],"answer":3,"explanation":["Differences increase by 1: 2, 3, 4, 5, 6. Next = 32.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 2, 3, 4, 5, 6. அடுத்த எண் 32."]},{"id":936,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 33, 39, 72, 111, 183, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 33, 39, 72, 111, 183, ?"],"options":[["295","295"],["297","297"],["294","294"],["304","304"]],"answer":2,"explanation":["111 + 183 = 294.","111 + 183 = 294."]},{"id":937,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 45 in the ratio 3 : 6. Find the smaller share.","45 ஐ 3 : 6 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["16","16"],["25","25"],["18","18"],["15","15"]],"answer":3,"explanation":["Smaller share = 45 × 3/(3+6) = 15.","சிறிய பங்கு = 45 × 3/(3+6) = 15."]},{"id":938,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 13 and 30.","13 மற்றும் 30 இன் மீ.பொ.வ. காண்க."],"options":[["3","3"],["2","2"],["1","1"],["0","0"]],"answer":2,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":939,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 15 and 14.","15 மற்றும் 14 இன் மீ.பொ.ம. காண்க."],"options":[["215","215"],["210","210"],["220","220"],["420","420"]],"answer":1,"explanation":["LCM = product ÷ HCF = 210 ÷ 1 = 210.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 210 ÷ 1 = 210."]},{"id":940,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹2400 is sold for ₹3000. Find the profit percentage.","₹2400 க்கு வாங்கிய பொருள் ₹3000 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["24","24"],["25","25"],["50","50"],["30","30"]],"answer":1,"explanation":["Profit = ₹600. Profit% = 600 × 100 / 2400 = 25%.","இலாபம் = ₹600. இலாப% = 600 × 100 / 2400 = 25%."]},{"id":941,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 46° and 67°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 46°, 67°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["77","77"],["67","67"],["134","134"],["68","68"]],"answer":1,"explanation":["180 − 46 − 67 = 67°.","180 − 46 − 67 = 67°."]},{"id":942,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 12°, in degrees.","12° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["168","168"],["336","336"],["171","171"],["167","167"]],"answer":0,"explanation":["Supplementary angles sum to 180°. 180 − 12 = 168°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 12 = 168°."]},{"id":943,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Add and simplify: 4/11 + 8/11.","கூட்டிச் சுருக்குக: 4/11 + 8/11."],"options":[["13/11","13/11"],["12/11","12/11"],["15/11","15/11"],["14/11","14/11"]],"answer":1,"explanation":["(4 + 8)/11 = 12/11 = 12/11.","(4 + 8)/11 = 12/11 = 12/11."]},{"id":944,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A bag contains 11 red and 14 blue balls. One is drawn at random. Find the probability of red.","ஒரு பையில் 11 சிவப்பு, 14 நீலப் பந்துகள் உள்ளன. சமவாய்ப்பில் ஒரு பந்தை எடுத்தால் சிவப்பு கிடைக்கும் நிகழ்தகவு என்ன?"],"options":[["11/25","11/25"],["6/13","6/13"],["1/2","1/2"],["13/27","13/27"]],"answer":0,"explanation":["Favourable outcomes / total = 11/25 = 11/25.","சாதகமான வாய்ப்புகள் / மொத்த வாய்ப்புகள் = 11/25 = 11/25."]},{"id":945,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Melting”?","“உருகுதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Separating an insoluble solid from a liquid using a porous barrier","நுண்துளைத் தடுப்பால் கரையாத திடப்பொருளை திரவத்திலிருந்து பிரித்தல்"],["The change of a solid into a liquid","திடப்பொருள் திரவமாக மாறுதல்"],["Plant tissue that transports water and minerals from roots","வேரிலிருந்து நீர் மற்றும் தாதுக்களைக் கடத்தும் தாவரத் திசு"],["Heat transfer that can occur through a vacuum","வெற்றிடத்தின் வழியாகவும் நிகழக்கூடிய வெப்பப் பரிமாற்றம்"]],"answer":1,"explanation":["Melting: The change of a solid into a liquid.","உருகுதல்: திடப்பொருள் திரவமாக மாறுதல்."]},{"id":946,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Freezing”?","“உறைதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The change of a liquid into a solid","திரவம் திடப்பொருளாக மாறுதல்"],["A fluid-filled cell compartment used for storage","சேமிப்பிற்கு உதவும் திரவம் நிரம்பிய செல் பகுதி"],["Root extensions that increase the surface area for absorption","உறிஞ்சுதலுக்கான பரப்பளவை அதிகரிக்கும் வேரின் நீட்சிகள்"],["The cellular structure responsible for protein synthesis","புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு"]],"answer":0,"explanation":["Freezing: The change of a liquid into a solid.","உறைதல்: திரவம் திடப்பொருளாக மாறுதல்."]},{"id":947,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Solute”?","“கரைபொருள்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Transfer of pollen from anther to stigma","மகரந்தப்பையிலிருந்து சூலகமுடிக்கு மகரந்தம் மாற்றப்படுதல்"],["The gas that makes up the largest fraction of dry air","உலர் காற்றில் மிக அதிகப் பங்கு வகிக்கும் வாயு"],["The substance dissolved in a solvent to form a solution","கரைப்பானில் கரைந்து கரைசலை உருவாக்கும் பொருள்"],["The mineral required to make thyroid hormones","தைராய்டு ஹார்மோன்களை உருவாக்கத் தேவையான தாது"]],"answer":2,"explanation":["Solute: The substance dissolved in a solvent to form a solution.","கரைபொருள்: கரைப்பானில் கரைந்து கரைசலை உருவாக்கும் பொருள்."]},{"id":948,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Rajendra I”?","“முதலாம் இராஜேந்திரன்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The place in Amritsar where a massacre occurred in 1919","1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்"],["An elevated region with a relatively flat top","ஒப்பீட்டளவில் சமமான மேற்பரப்பைக் கொண்ட உயர்ந்த நிலப்பகுதி"],["An instrument used to measure rainfall","மழையளவை அளக்கப் பயன்படும் கருவி"],["The Chola ruler who founded Gangaikonda Cholapuram","கங்கைகொண்ட சோழபுரத்தை நிறுவிய சோழ மன்னர்"]],"answer":3,"explanation":["Rajendra I: The Chola ruler who founded Gangaikonda Cholapuram.","முதலாம் இராஜேந்திரன்: கங்கைகொண்ட சோழபுரத்தை நிறுவிய சோழ மன்னர்."]},{"id":949,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Mahatma Gandhi”?","“மகாத்மா காந்தி” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Angular distance east or west of the Prime Meridian","முதன்மை தீர்க்கக்கோட்டிலிருந்து கிழக்கு அல்லது மேற்காக அளவிடப்படும் கோணத் தொலைவு"],["The laying down of material carried by water, wind or ice","நீர், காற்று அல்லது பனியால் எடுத்துச் செல்லப்பட்ட பொருட்கள் படியுதல்"],["A smaller river that joins a larger river","ஒரு பெரிய ஆற்றுடன் இணையும் சிறிய ஆறு"],["The leader who led the Dandi Salt March in 1930","1930 இல் தண்டி உப்பு யாத்திரையை வழிநடத்திய தலைவர்"]],"answer":3,"explanation":["Mahatma Gandhi: The leader who led the Dandi Salt March in 1930.","மகாத்மா காந்தி: 1930 இல் தண்டி உப்பு யாத்திரையை வழிநடத்திய தலைவர்."]},{"id":950,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 35, 37, 39, 41, 43, …","அடுத்த எண்ணைக் காண்க: 35, 37, 39, 41, 43, …"],"options":[["46","46"],["50","50"],["55","55"],["45","45"]],"answer":3,"explanation":["Add 2 each time. 43 + 2 = 45.","ஒவ்வொரு முறையும் 2 கூட்டுக. 43 + 2 = 45."]},{"id":951,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 13, 26, 52, 104, ?","தொடரை நிறைவு செய்க: 13, 26, 52, 104, ?"],"options":[["208","208"],["209","209"],["210","210"],["213","213"]],"answer":0,"explanation":["Double each term: 104 × 2 = 208.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 104 × 2 = 208."]},{"id":952,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 9, 21, 45, 93, ?","அடுத்த உறுப்பைக் காண்க: 9, 21, 45, 93, ?"],"options":[["194","194"],["189","189"],["378","378"],["191","191"]],"answer":1,"explanation":["Multiply by 2, then add 3: 93 × 2 + 3 = 189.","2 ஆல் பெருக்கி 3 கூட்டுக: 93 × 2 + 3 = 189."]},{"id":953,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 27, 30, ?, 36, 39","விடுபட்ட எண்ணைக் காண்க: 27, 30, ?, 36, 39"],"options":[["32","32"],["38","38"],["36","36"],["33","33"]],"answer":3,"explanation":["The common difference is 3. 30 + 3 = 33.","பொது வித்தியாசம் 3. 30 + 3 = 33."]},{"id":954,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 81, 100, 121, 144, ?","தொடர்க: 81, 100, 121, 144, ?"],"options":[["168","168"],["172","172"],["179","179"],["169","169"]],"answer":3,"explanation":["These are squares of 9, 10, 11, 12. Next: 13² = 169.","இவை 9, 10, 11, 12 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 13² = 169."]},{"id":955,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 6 from the front and position 10 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 6 ஆவது, பின்னிருந்து 10 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["15","15"],["16","16"],["18","18"],["30","30"]],"answer":0,"explanation":["Total = 6 + 10 − 1 = 15; the student is counted only once.","மொத்தம் = 6 + 10 − 1 = 15; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":956,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["In a line of 43 students, a student is in position 8 from the front. Find the position from the back.","43 மாணவர்கள் உள்ள வரிசையில் ஒருவர் முன்னிருந்து 8 ஆவது இடத்தில் உள்ளார். பின்னிருந்து அவரது இடத்தைக் காண்க."],"options":[["36","36"],["72","72"],["39","39"],["37","37"]],"answer":0,"explanation":["Position from back = 43 − 8 + 1 = 36.","பின்னிருந்து இடம் = 43 − 8 + 1 = 36."]},{"id":957,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 32 m north, 16 m east, 5 m south and 16 m west. How far are you from the start, in metres?","32 மீ வடக்கு, 16 மீ கிழக்கு, 5 மீ தெற்கு, 16 மீ மேற்கு செல்க. தொடக்கத்திலிருந்து தொலைவு எத்தனை மீட்டர்?"],"options":[["32","32"],["54","54"],["27","27"],["30","30"]],"answer":2,"explanation":["East and west cancel. Net northward distance = 32 − 5 = 27 m.","கிழக்கு, மேற்கு தொலைவுகள் சமம். நிகர வடக்குத் தொலைவு = 32 − 5 = 27 மீ."]},{"id":958,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Walk 15 km east and then 20 km north. Find the straight-line distance from the start in km.","15 கி.மீ கிழக்கிலும் பின்னர் 20 கி.மீ வடக்கிலும் செல்க. தொடக்கத்திலிருந்து நேர்க்கோட்டுத் தொலைவு எத்தனை கி.மீ?"],"options":[["24","24"],["27","27"],["25","25"],["50","50"]],"answer":2,"explanation":["Pythagoras: √(15² + 20²) = 25 km.","பிதாகரஸ் தேற்றம்: √(15² + 20²) = 25 கி.மீ."]},{"id":959,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Use the rule n → n × (n + 1). If 11 → 132, then 22 → ?","n → n × (n + 1) என்ற விதியைப் பயன்படுத்துக. 11 → 132 எனில் 22 → ?"],"options":[["506","506"],["507","507"],["1012","1012"],["509","509"]],"answer":0,"explanation":["22 × (22 + 1) = 506.","22 × (22 + 1) = 506."]},{"id":960,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using the cube rule, 3 : 27 :: 12 : ?","மும்மடி விதியைப் பயன்படுத்துக: 3 : 27 :: 12 : ?"],"options":[["1729","1729"],["1733","1733"],["1728","1728"],["1738","1738"]],"answer":2,"explanation":["3³ = 27, so 12³ = 1728.","3³ = 27; எனவே 12³ = 1728."]},{"id":961,"section":"MAT","topic":["Coding","குறியீடு"],"text":["Shift every letter 3 places forward in the alphabet (wrap Z to A). Code SHIP.","ஒவ்வோர் எழுத்தையும் ஆங்கில எழுத்துவரிசையில் 3 இடங்கள் முன்னோக்கி நகர்த்துக (Z க்குப் பின் A). SHIP இன் குறியீடு என்ன?"],"options":[["XMNU","XMNU"],["UJKR","UJKR"],["WLMT","WLMT"],["VKLS","VKLS"]],"answer":3,"explanation":["Each letter advances by 3: S → V, H → K, I → L, P → S","ஒவ்வோர் எழுத்தும் 3 இடங்கள் முன்னேறும்: S → V, H → K, I → L, P → S"]},{"id":962,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find 40% of 800.","800 இல் 40% காண்க."],"options":[["323","323"],["322","322"],["320","320"],["321","321"]],"answer":2,"explanation":["800 × 40 / 100 = 320.","800 × 40 / 100 = 320."]},{"id":963,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["The marked price is ₹1900. Find the price after a 5% discount, in rupees.","குறித்த விலை ₹1900. 5% தள்ளுபடிக்குப் பிறகு விலை எத்தனை ரூபாய்?"],"options":[["1805","1805"],["1807","1807"],["1806","1806"],["3610","3610"]],"answer":0,"explanation":["Discount = ₹95. Pay 1900 − 95 = ₹1805.","தள்ளுபடி = ₹95. செலுத்துவது 1900 − 95 = ₹1805."]},{"id":964,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the simple interest in rupees on ₹2100 at 10% per year for 2 years.","₹2100 க்கு ஆண்டுக்கு 10% வீதம் 2 ஆண்டுகளுக்கான தனிவட்டி எத்தனை ரூபாய்?"],"options":[["419","419"],["840","840"],["420","420"],["423","423"]],"answer":2,"explanation":["PRT/100 = 2100 × 10 × 2 / 100 = ₹420.","PRT/100 = 2100 × 10 × 2 / 100 = ₹420."]},{"id":965,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Solve for x: 10x + 27 = 107.","x காண்க: 10x + 27 = 107."],"options":[["10","10"],["8","8"],["16","16"],["9","9"]],"answer":1,"explanation":["x = (107 − 27) ÷ 10 = 8.","x = (107 − 27) ÷ 10 = 8."]},{"id":966,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle is 7 cm long and 13 cm wide. Find its area in cm².","ஒரு செவ்வகத்தின் நீளம் 7 செ.மீ, அகலம் 13 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["101","101"],["91","91"],["94","94"],["182","182"]],"answer":1,"explanation":["Area = length × width = 7 × 13 = 91 cm².","பரப்பளவு = நீளம் × அகலம் = 7 × 13 = 91 ச.செ.மீ."]},{"id":967,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A rectangle has sides 8 m and 10 m. Find its perimeter in metres.","ஒரு செவ்வகத்தின் பக்கங்கள் 8 மீ மற்றும் 10 மீ. சுற்றளவு எத்தனை மீட்டர்?"],"options":[["36","36"],["37","37"],["38","38"],["41","41"]],"answer":0,"explanation":["Perimeter = 2(8 + 10) = 36 m.","சுற்றளவு = 2(8 + 10) = 36 மீ."]},{"id":968,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A triangle has base 42 cm and height 12 cm. Find its area in cm².","ஒரு முக்கோணத்தின் அடிப்பக்கம் 42 செ.மீ, உயரம் 12 செ.மீ. பரப்பளவு எத்தனை ச.செ.மீ?"],"options":[["253","253"],["257","257"],["252","252"],["251","251"]],"answer":2,"explanation":["Area = ½ × 42 × 12 = 252 cm².","பரப்பளவு = ½ × 42 × 12 = 252 ச.செ.மீ."]},{"id":969,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A cuboid measures 8 cm × 13 cm × 10 cm. Find its volume in cm³.","ஒரு கனச்செவ்வகத்தின் அளவுகள் 8 செ.மீ × 13 செ.மீ × 10 செ.மீ. கனஅளவு எத்தனை க.செ.மீ?"],"options":[["1040","1040"],["1041","1041"],["1045","1045"],["1043","1043"]],"answer":0,"explanation":["Volume = length × breadth × height = 8 × 13 × 10 = 1040 cm³.","கனஅளவு = நீளம் × அகலம் × உயரம் = 8 × 13 × 10 = 1040 க.செ.மீ."]},{"id":970,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Solvent”?","“கரைப்பான்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Organs that filter blood and form urine","இரத்தத்தை வடிகட்டி சிறுநீரை உருவாக்கும் உறுப்புகள்"],["The substance in which a solute dissolves","கரைபொருள் கரையும் பொருள்"],["The SI unit of energy","ஆற்றலின் SI அலகு"],["The substance dissolved in a solvent to form a solution","கரைப்பானில் கரைந்து கரைசலை உருவாக்கும் பொருள்"]],"answer":1,"explanation":["Solvent: The substance in which a solute dissolves.","கரைப்பான்: கரைபொருள் கரையும் பொருள்."]},{"id":971,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Filtration”?","“வடிகட்டுதல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The force that opposes relative sliding between surfaces","பரப்புகளுக்கிடையேயான சார்பு சறுக்கல் இயக்கத்தை எதிர்க்கும் விசை"],["Blood cells chiefly involved in defence against infection","நோய்த்தொற்றுக்கு எதிரான பாதுகாப்பில் முதன்மையாக ஈடுபடும் இரத்த அணுக்கள்"],["Separating an insoluble solid from a liquid using a porous barrier","நுண்துளைத் தடுப்பால் கரையாத திடப்பொருளை திரவத்திலிருந்து பிரித்தல்"],["A fluid-filled cell compartment used for storage","சேமிப்பிற்கு உதவும் திரவம் நிரம்பிய செல் பகுதி"]],"answer":2,"explanation":["Filtration: Separating an insoluble solid from a liquid using a porous barrier.","வடிகட்டுதல்: நுண்துளைத் தடுப்பால் கரையாத திடப்பொருளை திரவத்திலிருந்து பிரித்தல்."]},{"id":972,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Distillation”?","“காய்ச்சி வடித்தல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The vitamin whose deficiency can cause night blindness","குறைபாட்டால் மாலைக்கண் நோய் ஏற்படக்கூடிய வைட்டமின்"],["Separation using vaporisation followed by condensation","ஆவியாக்குதலுக்குப் பின் ஆவி சுருங்குதலைப் பயன்படுத்திப் பிரித்தல்"],["The bouncing back of light into the same medium","ஒளி அதே ஊடகத்திற்குத் திரும்பும் நிகழ்வு"],["The SI unit of pressure","அழுத்தத்தின் SI அலகு"]],"answer":1,"explanation":["Distillation: Separation using vaporisation followed by condensation.","காய்ச்சி வடித்தல்: ஆவியாக்குதலுக்குப் பின் ஆவி சுருங்குதலைப் பயன்படுத்திப் பிரித்தல்."]},{"id":973,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “V. O. Chidambaranar”?","“வ. உ. சிதம்பரனார்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The freedom fighter associated with the Swadeshi Steam Navigation Company","சுதேசி நீராவிக் கப்பல் நிறுவனத்துடன் தொடர்புடைய விடுதலைப் போராட்ட வீரர்"],["The leader popularly called Netaji","நேதாஜி எனப் போற்றப்படும் தலைவர்"],["A depositional landform that may develop at a river mouth","ஆற்றின் முகத்துவாரத்தில் படிவுகளால் உருவாகக்கூடிய நிலத்தோற்றம்"],["The imaginary circle at 0° latitude","0° அட்சத்தில் அமைந்துள்ள கற்பனை வட்டம்"]],"answer":0,"explanation":["V. O. Chidambaranar: The freedom fighter associated with the Swadeshi Steam Navigation Company.","வ. உ. சிதம்பரனார்: சுதேசி நீராவிக் கப்பல் நிறுவனத்துடன் தொடர்புடைய விடுதலைப் போராட்ட வீரர்."]},{"id":974,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Subhas Chandra Bose”?","“சுபாஷ் சந்திர போஸ்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The reference meridian at 0° longitude","0° தீர்க்கத்தில் அமைந்துள்ள ஆதாரத் தீர்க்கக்கோடு"],["The Chola ruler who founded Gangaikonda Cholapuram","கங்கைகொண்ட சோழபுரத்தை நிறுவிய சோழ மன்னர்"],["The Chola ruler who built the Brihadisvara Temple at Thanjavur","தஞ்சைப் பெரிய கோயிலைக் கட்டிய சோழ மன்னர்"],["The leader popularly called Netaji","நேதாஜி எனப் போற்றப்படும் தலைவர்"]],"answer":3,"explanation":["Subhas Chandra Bose: The leader popularly called Netaji.","சுபாஷ் சந்திர போஸ்: நேதாஜி எனப் போற்றப்படும் தலைவர்."]},{"id":975,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Using A = 1, B = 2, …, Z = 26, find the sum of the letter values in TREE.","A = 1, B = 2, …, Z = 26 எனில், TREE என்ற சொல்லின் எழுத்து மதிப்புகளின் கூடுதல் என்ன?"],"options":[["49","49"],["48","48"],["47","47"],["96","96"]],"answer":1,"explanation":["20 + 18 + 5 + 5 = 48.","20 + 18 + 5 + 5 = 48."]},{"id":976,"section":"MAT","topic":["Calendar","நாட்காட்டி"],"text":["Today is Tuesday. What day will it be after 65 days?","இன்று செவ்வாய். 65 நாட்களுக்குப் பிறகு என்ன கிழமை?"],"options":[["Thursday","வியாழன்"],["Sunday","ஞாயிறு"],["Friday","வெள்ளி"],["Saturday","சனி"]],"answer":0,"explanation":["65 ÷ 7 leaves remainder 2. Move 2 days from Tuesday: Thursday.","65 ஐ 7 ஆல் வகுக்க மீதி 2. செவ்வாய் கிழமையிலிருந்து 2 நாட்கள் நகர்ந்தால் வியாழன்."]},{"id":977,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each of 7 students shakes hands once with every other student. How many handshakes occur?","7 மாணவர்களில் ஒவ்வொருவரும் மற்ற ஒவ்வொருவருடனும் ஒருமுறை கைகுலுக்குகின்றனர். மொத்த கைகுலுக்கல்கள் எத்தனை?"],"options":[["24","24"],["31","31"],["42","42"],["21","21"]],"answer":3,"explanation":["Each pair is counted once: 7 × 6 ÷ 2 = 21.","ஒவ்வொரு இணையும் ஒருமுறை: 7 × 6 ÷ 2 = 21."]},{"id":978,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A row of 25 adjacent squares is made with matchsticks. Neighbouring squares share one side. How many matchsticks are needed?","ஒரு வரிசையில் 25 சதுரங்கள் தீக்குச்சிகளால் அமைக்கப்படுகின்றன. அடுத்தடுத்த சதுரங்கள் ஒரு பக்கத்தைப் பகிர்கின்றன. எத்தனை தீக்குச்சிகள் தேவை?"],"options":[["79","79"],["152","152"],["76","76"],["75","75"]],"answer":2,"explanation":["First square: 4 sticks. Each extra square: 3. Total = 4 + 3 × 24 = 76.","முதல் சதுரத்திற்கு 4; அடுத்த ஒவ்வொன்றுக்கும் 3. மொத்தம் = 4 + 3 × 24 = 76."]},{"id":979,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete: 8, 12, 17, 23, 30, ?","நிறைவு செய்க: 8, 12, 17, 23, 30, ?"],"options":[["41","41"],["39","39"],["38","38"],["43","43"]],"answer":2,"explanation":["Differences increase by 1: 4, 5, 6, 7, 8. Next = 38.","வித்தியாசங்கள் 1 வீதம் அதிகரிக்கின்றன: 4, 5, 6, 7, 8. அடுத்த எண் 38."]},{"id":980,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Each term is the sum of the previous two. Find ?: 30, 34, 64, 98, 162, ?","ஒவ்வோர் உறுப்பும் முந்தைய இரண்டின் கூடுதல். ? காண்க: 30, 34, 64, 98, 162, ?"],"options":[["263","263"],["261","261"],["260","260"],["262","262"]],"answer":2,"explanation":["98 + 162 = 260.","98 + 162 = 260."]},{"id":981,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next number: 24, 33, 42, 51, 60, …","அடுத்த எண்ணைக் காண்க: 24, 33, 42, 51, 60, …"],"options":[["138","138"],["69","69"],["79","79"],["68","68"]],"answer":1,"explanation":["Add 9 each time. 60 + 9 = 69.","ஒவ்வொரு முறையும் 9 கூட்டுக. 60 + 9 = 69."]},{"id":982,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Complete the series: 3, 6, 12, 24, ?","தொடரை நிறைவு செய்க: 3, 6, 12, 24, ?"],"options":[["49","49"],["96","96"],["47","47"],["48","48"]],"answer":3,"explanation":["Double each term: 24 × 2 = 48.","ஒவ்வோர் உறுப்பையும் இரட்டிப்பாக்குக: 24 × 2 = 48."]},{"id":983,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the next term: 15, 37, 81, 169, ?","அடுத்த உறுப்பைக் காண்க: 15, 37, 81, 169, ?"],"options":[["348","348"],["347","347"],["355","355"],["345","345"]],"answer":3,"explanation":["Multiply by 2, then add 7: 169 × 2 + 7 = 345.","2 ஆல் பெருக்கி 7 கூட்டுக: 169 × 2 + 7 = 345."]},{"id":984,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Find the missing number: 4, 10, ?, 22, 28","விடுபட்ட எண்ணைக் காண்க: 4, 10, ?, 22, 28"],"options":[["19","19"],["17","17"],["16","16"],["18","18"]],"answer":2,"explanation":["The common difference is 6. 10 + 6 = 16.","பொது வித்தியாசம் 6. 10 + 6 = 16."]},{"id":985,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["Continue: 400, 441, 484, 529, ?","தொடர்க: 400, 441, 484, 529, ?"],"options":[["578","578"],["575","575"],["581","581"],["576","576"]],"answer":3,"explanation":["These are squares of 20, 21, 22, 23. Next: 24² = 576.","இவை 20, 21, 22, 23 ஆகியவற்றின் வர்க்கங்கள். அடுத்தது 24² = 576."]},{"id":986,"section":"MAT","topic":["Mental ability","மனத்திறன்"],"text":["A student is in position 13 from the front and position 18 from the back of a line. How many students are in the line?","ஒரு மாணவர் வரிசையில் முன்னிருந்து 13 ஆவது, பின்னிருந்து 18 ஆவது இடத்தில் உள்ளார். மொத்த மாணவர்கள் எத்தனை?"],"options":[["32","32"],["31","31"],["60","60"],["30","30"]],"answer":3,"explanation":["Total = 13 + 18 − 1 = 30; the student is counted only once.","மொத்தம் = 13 + 18 − 1 = 30; அந்த மாணவரை ஒருமுறை மட்டுமே கணக்கிட வேண்டும்."]},{"id":987,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the mean of 23, 29, 35, 41, 47.","23, 29, 35, 41, 47 ஆகியவற்றின் சராசரி காண்க."],"options":[["34","34"],["36","36"],["40","40"],["35","35"]],"answer":3,"explanation":["Sum ÷ count = 175 ÷ 5 = 35.","கூடுதல் ÷ எண்ணிக்கை = 175 ÷ 5 = 35."]},{"id":988,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["A train travels 867 km in 17 hours at constant speed. Find its speed in km/h.","ஒரு ரயில் சீரான வேகத்தில் 17 மணி நேரத்தில் 867 கி.மீ செல்கிறது. வேகம் எத்தனை கி.மீ/மணி?"],"options":[["51","51"],["61","61"],["50","50"],["56","56"]],"answer":0,"explanation":["Speed = distance ÷ time = 867 ÷ 17 = 51 km/h.","வேகம் = தொலைவு ÷ நேரம் = 867 ÷ 17 = 51 கி.மீ/மணி."]},{"id":989,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Divide 504 in the ratio 6 : 12. Find the smaller share.","504 ஐ 6 : 12 என்ற விகிதத்தில் பிரிக்க. சிறிய பங்கு என்ன?"],"options":[["167","167"],["171","171"],["170","170"],["168","168"]],"answer":3,"explanation":["Smaller share = 504 × 6/(6+12) = 168.","சிறிய பங்கு = 504 × 6/(6+12) = 168."]},{"id":990,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the HCF of 16 and 33.","16 மற்றும் 33 இன் மீ.பொ.வ. காண்க."],"options":[["2","2"],["3","3"],["6","6"],["1","1"]],"answer":3,"explanation":["Common factors: 1. Greatest = 1.","பொதுக் காரணிகள்: 1. மிகப்பெரியது 1."]},{"id":991,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the LCM of 37 and 13.","37 மற்றும் 13 இன் மீ.பொ.ம. காண்க."],"options":[["491","491"],["486","486"],["480","480"],["481","481"]],"answer":3,"explanation":["LCM = product ÷ HCF = 481 ÷ 1 = 481.","மீ.பொ.ம. = பெருக்கற்பலன் ÷ மீ.பொ.வ. = 481 ÷ 1 = 481."]},{"id":992,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["An item bought for ₹800 is sold for ₹1000. Find the profit percentage.","₹800 க்கு வாங்கிய பொருள் ₹1000 க்கு விற்கப்படுகிறது. இலாபச் சதவீதம் என்ன?"],"options":[["27","27"],["50","50"],["25","25"],["35","35"]],"answer":2,"explanation":["Profit = ₹200. Profit% = 200 × 100 / 800 = 25%.","இலாபம் = ₹200. இலாப% = 200 × 100 / 800 = 25%."]},{"id":993,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Two angles of a triangle are 44° and 38°. Find the third angle in degrees.","முக்கோணத்தின் இரு கோணங்கள் 44°, 38°. மூன்றாவது கோணம் எத்தனை பாகை?"],"options":[["196","196"],["100","100"],["99","99"],["98","98"]],"answer":3,"explanation":["180 − 44 − 38 = 98°.","180 − 44 − 38 = 98°."]},{"id":994,"section":"SAT","topic":["Mathematics","கணிதம்"],"text":["Find the supplementary angle of 34°, in degrees.","34° இன் மிகைநிரப்புக் கோணம் எத்தனை பாகை?"],"options":[["145","145"],["148","148"],["151","151"],["146","146"]],"answer":3,"explanation":["Supplementary angles sum to 180°. 180 − 34 = 146°.","மிகைநிரப்புக் கோணங்களின் கூடுதல் 180°. 180 − 34 = 146°."]},{"id":995,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Neutralisation”?","“நடுநிலையாக்கல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The SI unit of force","விசையின் SI அலகு"],["The rigid outer layer outside the membrane in a plant cell","தாவரச் செல்லில் செல் சவ்விற்கு வெளியே உள்ள உறுதியான அடுக்கு"],["The SI unit of electric potential difference","மின்னழுத்த வேறுபாட்டின் SI அலகு"],["A reaction between an acid and a base that forms salt and water","அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்"]],"answer":3,"explanation":["Neutralisation: A reaction between an acid and a base that forms salt and water.","நடுநிலையாக்கல்: அமிலமும் காரமும் வினைபுரிந்து உப்பும் நீரும் உருவாதல்."]},{"id":996,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Rusting”?","“துருப்பிடித்தல்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The substance in which a solute dissolves","கரைபொருள் கரையும் பொருள்"],["The main site of absorption of digested nutrients in humans","மனிதரில் செரிக்கப்பட்ட ஊட்டச்சத்துகள் உறிஞ்சப்படும் முக்கிய இடம்"],["Corrosion of iron in the presence of oxygen and moisture","ஆக்சிஜன் மற்றும் ஈரப்பதத்தின் முன்னிலையில் இரும்பு அரித்தல்"],["Fusion of male and female gametes","ஆண் மற்றும் பெண் இனச்செல்களின் இணைவு"]],"answer":2,"explanation":["Rusting: Corrosion of iron in the presence of oxygen and moisture.","துருப்பிடித்தல்: ஆக்சிஜன் மற்றும் ஈரப்பதத்தின் முன்னிலையில் இரும்பு அரித்தல்."]},{"id":997,"section":"SAT","topic":["Science","அறிவியல்"],"text":["Which description correctly matches “Nitrogen”?","“நைட்ரஜன்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The gas that makes up the largest fraction of dry air","உலர் காற்றில் மிக அதிகப் பங்கு வகிக்கும் வாயு"],["Loss of water as vapour from aerial parts of plants","தாவரத்தின் தரைக்கு மேலுள்ள பகுதிகளிலிருந்து நீர் ஆவியாக வெளியேறுதல்"],["The cellular structure responsible for protein synthesis","புரதத் தொகுப்பிற்கு உரிய செல் அமைப்பு"],["The tendency to resist a change in the state of rest or motion","ஓய்வு அல்லது இயக்க நிலையில் ஏற்படும் மாற்றத்தை எதிர்க்கும் தன்மை"]],"answer":0,"explanation":["Nitrogen: The gas that makes up the largest fraction of dry air.","நைட்ரஜன்: உலர் காற்றில் மிக அதிகப் பங்கு வகிக்கும் வாயு."]},{"id":998,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Jallianwala Bagh”?","“ஜாலியன்வாலா பாக்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["Rock formed by cooling and solidification of magma or lava","மாக்மா அல்லது லாவா குளிர்ந்து இறுகுவதால் உருவாகும் பாறை"],["The largest ocean on Earth","புவியின் மிகப்பெரிய பெருங்கடல்"],["The leader popularly called Netaji","நேதாஜி எனப் போற்றப்படும் தலைவர்"],["The place in Amritsar where a massacre occurred in 1919","1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்"]],"answer":3,"explanation":["Jallianwala Bagh: The place in Amritsar where a massacre occurred in 1919.","ஜாலியன்வாலா பாக்: 1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்."]},{"id":999,"section":"SAT","topic":["Social Science","சமூக அறிவியல்"],"text":["Which description correctly matches “Quit India Movement”?","“வெள்ளையனே வெளியேறு இயக்கம்” என்பதற்குச் சரியான விளக்கம் எது?"],"options":[["The mass movement launched under Gandhi’s leadership in August 1942","1942 ஆகஸ்டில் காந்தியின் தலைமையில் தொடங்கப்பட்ட மக்கள் இயக்கம்"],["The imaginary circle at 0° latitude","0° அட்சத்தில் அமைந்துள்ள கற்பனை வட்டம்"],["The place in Amritsar where a massacre occurred in 1919","1919 இல் படுகொலை நடைபெற்ற அமிர்தசரஸ் நகரின் இடம்"],["A smaller river that joins a larger river","ஒரு பெரிய ஆற்றுடன் இணையும் சிறிய ஆறு"]],"answer":0,"explanation":["Quit India Movement: The mass movement launched under Gandhi’s leadership in August 1942.","வெள்ளையனே வெளியேறு இயக்கம்: 1942 ஆகஸ்டில் காந்தியின் தலைமையில் தொடங்கப்பட்ட மக்கள் இயக்கம்."]}]);
